window.JASTROW_CHUNKS[68]={"27200":{"h":"רַזְבּוֹנִית","r":"T00463","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רזב\">preced.</a>) a species of <i>locusts</i>. <span class=\"citation\">Ḥull. 65ᵃ</span> הרזבונ׳ Ar. (ed. <a href=\"#\" data-headword=\"הַרְזְבוֹנִית\">הרזבנ׳</a>, Ms. H. <span dir=\"rtl\">זרבונית</span>, v. Rabb. D. S. a. l. note 3), v. <a href=\"#\" data-headword=\"אַרְזְבוֹנִית\">אַרְזְבוֹנִית</a>.</div>","alt":["רַזְבָּנִית"]},"27201":{"h":"רָזֶה","r":"T00464","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"רזֵי\">רְזֵי</a>) <i>hard, lean.</i>—Pl. <span dir=\"rtl\">רָזִים</span>. <span class=\"citation\">Num. R. s. 16</span><sup>12</sup>; Tanḥ. Sh’laḥ 6 <span dir=\"rtl\">אם של חרסין הן הם ר׳</span> if the stones of the ground are of a clayish nature, the fruits are lean.</div>","alt":[]},"27202":{"h":"רזח","r":"T00465","html":"<div class=\"sense\">, <span class=\"citation\">M. Kat. 28ᵇ</span> מרוזח Ms. M. (ed. <a href=\"#\" data-headword=\"מַרְזֵחַ\">מרזח</a>), read: <span dir=\"rtl\">מַר וָזָח</span>, v. <a href=\"#\" data-headword=\"מַר II\"><span dir=\"rtl\">מַר</span> II</a></div>","alt":[]},"27203":{"h":"רזֵי","r":"T00466","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָז\">רָז</a>) <i>to be strong, hard</i>; [b. h. <a href=\"#\" data-headword=\"רָזֶה\">רזה</a> <i>to be lean</i>].</div><div class=\"sense\"><b>Af. אַרְזֵי</b> <div class=\"sense\"><i>to come with vehemence upon, stir up, irritate</i>. <span class=\"citation\">Yeb. 120ᵇ</span> <span dir=\"rtl\">שאני מיא דמַרְזוּ מכה</span> it is different with water (coming in contact with a wound), it irritates the wound.</div></div><div class=\"sense\"><b>Pa. רַזֵּי</b> <div class=\"sense\"><i>to throw with force</i>.—Part. pass. <span dir=\"rtl\">מְרַזֵּי</span>, <span dir=\"rtl\">מְרַזְּיָא</span>. <span class=\"citation\">Snh. 45ᵇ</span> <span dir=\"rtl\">כי היכא דתיתי מר׳</span> (Ms. M. <span dir=\"rtl\">מִירַזְּיָא</span> <i>Ithpa.</i>, ed. Sonc. <span dir=\"rtl\">ברַזְיָא</span>, v. <a href=\"#\" data-headword=\"רַזְיָא\">next w.</a>; v. Rabb. D. S. a. l. note) in order that the stone may come down with force.</div></div>","alt":[]},"27204":{"h":"רַזְיָא","r":"T00467","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רזֵי\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>strong, vehement, gushing</i>. <span class=\"citation\">Targ. Job XXXVII, 13</span>.—[<span class=\"citation\">Targ. Prov. XXVI, 10</span> some ed. <span dir=\"rtl\">ורזיא</span>, read: <span dir=\"rtl\">ורַוְיָא</span>.]—<span class=\"citation\">Taan. 3ᵇ</span> <span dir=\"rtl\">דאתא ר׳</span> when the rain comes with vehemence, opp. <a href=\"#\" data-headword=\"נְיָיח\">ניחא</a>. <span class=\"citation\">Ib.</span> (ref. to Job l. c.) <span dir=\"rtl\">מיטרא ר׳ לאילני</span> a vehement rain is good for the trees; <span class=\"citation\">Yalk. Job 921</span>.</div><div class=\"sense\"><b>—2)</b> <i>force</i>. <span class=\"citation\">Snh. 45ᵇ</span> <span dir=\"rtl\">בר׳</span> ed. Sonc., v. <a href=\"#\" data-headword=\"רזֵי\">preced.</a></div>","alt":[]},"27205":{"h":"רָזִיאֵל","r":"T00468","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָז\">רָז</a>) pr. n. <i>Raziel</i>, name of an angel. <span class=\"citation\">Targ. Koh. X, 20</span>.</div>","alt":[]},"27206":{"h":"רָזִיחַ","r":"T00469","html":"<div class=\"sense\"><i>raziaḥ</i>, a substitute of <i>nazir</i> (v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>). <span class=\"citation\">Y. Naz. I, 51ᵃ</span> bot.</div>","alt":[]},"27207":{"h":"רזם","r":"T00470","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְמַז\">רְמַז</a></div>","alt":[]},"27208":{"h":"רָזַק","r":"T00471","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָסַק\">רָסַק</a></div>","alt":[]},"27209":{"h":"רח","r":"T00472","html":"<div class=\"sense\">, <i>Ithpe.</i> <span dir=\"rtl\">אִתְרַח</span>, v. <a href=\"#\" data-headword=\"אֲרַח\">אֲרַח</a>.</div>","alt":[]},"27210":{"h":"רָחָב I","r":"T00473","html":"<div class=\"sense\"> (b. h.) pr. n. f. <i>Rahab</i>, a woman of Jericho who received the Israelitish spies. <span class=\"citation\">Zeb. 116ᵃ</span>, sq. <span class=\"citation\">Sot. 34ᵃ</span>. <span class=\"citation\">Meg. 15ᵃ</span>; <span class=\"citation\">Taan. 5ᵇ</span>; a. fr.</div>","alt":[]},"27211":{"h":"רָחַב","r":"T00474","html":"<div class=\"sense\"> (b. h.) <i>to be wide</i>.</div><div class=\"sense\"><b>Hif. הִרְחִיב</b> <div class=\"sense\"><b>1)</b>  (neut. verb) (neut. verb) <i>to widen, be broader; to extend</i>. <span class=\"citation\">Lev. R. s. 31</span> <span dir=\"rtl\">היו מקטינות … ומַרְחִיבוֹת וכ׳</span> (the windows of the Temple) became narrow towards the inside and wider towards the outside, in order to send light forth to the world; Pesik. Ḳumi, p. 145ᵃ, sq. Sifré Deut. s. 1; <span class=\"citation\">Yalk. Zech. 575</span> <span dir=\"rtl\">מַרְחֶבֶת</span>, v. infra. <span class=\"citation\">Yalk. Is. 302</span>, v. <a href=\"#\" data-headword=\"פָּתָה\">פָּתָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to broaden, widen</i>; (with <a href=\"#\" data-headword=\"דַּעַת\">דעת</a>) <i>to comfort, gratify</i>. <span class=\"citation\">Ber. 57ᵇ</span> <span dir=\"rtl\">שלשה מַרְחִיבִין דעתו וכ׳</span></div><div class=\"sense\"><b>—3)</b> <i>to amplify</i>. <span class=\"citation\">B. Bath. 61ᵇ</span>, v. <a href=\"#\" data-headword=\"מֵצַר\">מֵצַר</a>.</div></div><div class=\"sense\"><b>Hithpa. הִתְרַחֵב</b> <div class=\"sense\"><i>to be enlarged, extend</i>. <span class=\"citation\">Cant. R. to VII, 5</span> עתידה … מִתְרַחֶבֶת וכ׳ Jerusalem will be enlarged on all sides; Sifré l. c.; Yalk. Zech. l. c. <span dir=\"rtl\">מרחבת</span>.</div></div>","alt":[]},"27212":{"h":"רָחָב II","r":"T00475","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רָחַב\">preced.</a>) <i>wide, broad</i>. <span class=\"citation\">Midd. IV, 7</span> <span dir=\"rtl\">מה ארי צר … ור׳ מלפניו וכ׳</span> (not <span dir=\"rtl\">ורוחב</span>) as the lion’s body is narrow behind and wide in front, so was the Temple &amp;c.; a. fr.—<span dir=\"rtl\">נפש ר׳</span> (wide desire,) <i>ambition, greed</i>, opp. <span dir=\"rtl\">שפלה</span>. <span class=\"citation\">Ab. V, 19</span>; a. e.—<span dir=\"rtl\">יד ר׳</span>, v. <a href=\"#\" data-headword=\"יָד\">יָד</a>.—Pl. <span dir=\"rtl\">רְחָבִים</span>, <span dir=\"rtl\">רְחָבִין</span>; <span dir=\"rtl\">רְחָבוֹת</span>. Tanḥ. B’haʿăl. 5 <span dir=\"rtl\">שהיו ר׳ מבחוץ וכ׳</span> they (the Temple windows) were wide without &amp;c., v. <a href=\"#\" data-headword=\"רָחַב\">preced.</a>; Tanḥ. T’tsav. 6; <span class=\"citation\">Num. R. s. 15</span>, beg. <span class=\"citation\">Y. Sot. IX, 24ᵃ</span> bot., v. <a href=\"#\" data-headword=\"צַר I\">צַר</a>; a. fr.</div>","alt":["רְחָבָה"]},"27213":{"h":"רְחַב","r":"T00476","html":"<div class=\"sense\">, esp. (with or sub. <a href=\"#\" data-headword=\"נְפַשׁ\">נפשא</a>) <i>ambitious, greedy</i>. <span class=\"citation\">Targ. Prov. XXVIII, 25</span> <span dir=\"rtl\">גברא ר׳</span> (Bxt. <span dir=\"rtl\">ר׳ נפשא</span>; Ms. <span dir=\"rtl\">רעיינא</span>, read: <span dir=\"rtl\">רחב עיינא</span> or <span dir=\"rtl\">רחב רעיינא</span>).</div>","alt":[]},"27214":{"h":"רֹחַב","r":"T00477","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רְחַב\">preced.</a> wds.) <i>width</i>. <span class=\"citation\">Midd. II, 6</span> <span dir=\"rtl\">אורך … על ר׳ וכ׳</span> one hundred and twenty-five cubits in length by eleven in width. <span class=\"citation\">Ib. IV, 1</span> <span dir=\"rtl\">ורָחְבּוֹ וכ׳</span> and its width was ten cubits. <span class=\"citation\">Tam. 29ᵇ</span>; <span class=\"citation\">Shek. VIII, 5</span> <span dir=\"rtl\">ורָחְבָּהּ</span>; a. fr.—<span class=\"citation\">Sifré Deut. 120</span> <span dir=\"rtl\">בר׳ יד</span> with liberality.</div>","alt":["רוֹחַב"]},"27215":{"h":"רַחֲבָא","r":"T00478","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (= <span dir=\"rtl\">רב אחבא</span>) <i>Raḥăba</i>, an Amora. <span class=\"citation\">Pes. 13ᵇ</span>; <span class=\"citation\">52ᵇ</span>; <span class=\"citation\">Succ. 45ᵃ</span>. <span class=\"citation\">Bets. 11ᵇ</span> (v. Rabb. D. S. a. l. note 1). <span class=\"citation\">Ber. 18ᵃ</span>; a. e.</div>","alt":["רַחֲבָה"]},"27216":{"h":"קַץ","r":"S01778","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְצַץ\">קְצַץ</a></div>","alt":[]},"27217":{"h":"קֵץ","r":"S01779","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>end, term, designated time</i>, esp. <i>the time of redemption</i>. <span class=\"citation\">Gen. R. s. 44</span> (ref. to <span class=\"citation\">Is. XLI, 5</span>) <span dir=\"rtl\">זה שרוי בקִיצּוֹ של עולם וכ׳</span> this one (Abraham) dwelt in one extreme part of the world, and that one (Shem) in the other &amp;c. <span class=\"citation\">Ned. 41ᵃ</span> <span dir=\"rtl\">כיון שהגיע קיצו וכ׳</span> when a man’s time (to die) has come. <span class=\"citation\">Meg. 3ᵃ</span> <span dir=\"rtl\">משום דאית ביה קץ משיח</span> because therein (in the Hagiographa) are contained intimations about the Messianic term (the Book of Daniel). <span class=\"citation\">Snh. 92ᵇ</span> <span dir=\"rtl\">שמנו לקץ וטעו</span> who ventured calculations as to the time of the redemption from Egypt, and made a mistake; <span class=\"citation\">Ex. R. s. 20</span> <span dir=\"rtl\">יצאו … שלם הקץ</span> they left Egypt before the predestined term had expired; a. fr.—Pl. <span dir=\"rtl\">קִצִּים</span>, <a href=\"#\" data-headword=\"קָצִין\">קִצִּין</a>, <a href=\"#\" data-headword=\"קִבְעָא\">קִי׳</a>. <span class=\"citation\">Ab. Zar. 61ᵇ</span> <span dir=\"rtl\">ממונה הבא לק׳</span> a superintendent that comes at regular times. <span class=\"citation\">Snh. 97ᵇ</span> <span dir=\"rtl\">מחשבי ק׳</span>, v. <a href=\"#\" data-headword=\"חָשַׁב\">חָשַׁב</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כלו כל הק׳ ואין וכ׳</span> all the dates of redemption (calculated from the Scriptures) have passed, and the thing depends only on repentance. <span class=\"citation\">Cant. R. to II, 8</span>; <span class=\"citation\">Lev. R. s. 19</span>, v. <a href=\"#\" data-headword=\"עִיבּוּר\">עִיבּוּר</a>. <span class=\"citation\">Pesik. R. s. 15</span>, v. <a href=\"#\" data-headword=\"קָפַץ\">קִפַץ</a>; a. fr.—[<span dir=\"rtl\">קיצין</span>, <span class=\"citation\">Cant. R. to V, 11</span>, v. <a href=\"#\" data-headword=\"קִיץ\">קִיץ</a>.]</div>","alt":[]},"27218":{"h":"קֵץ ²","r":"S01780","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. VI, 13</span>. <span class=\"citation\">Targ. Ez. VII, 6</span>. <span class=\"citation\">Targ. Jer. VIII, 20</span> ed. Lag. (ed. <a href=\"#\" data-headword=\"קַבָּא\">קִבָּא</a>); a. fr.—<span class=\"citation\">Lam. R. to II, 2</span>; <span class=\"citation\">to IV, 18</span> קרב קצנו ק׳ דההיא ביתא ‘our end has come near’, the end of that house (the Temple); <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> <span dir=\"rtl\">קִיצֵּיה דההוא וכ׳</span>; a. e.—Pl. <span dir=\"rtl\">קִצַּיָּא</span>, <a href=\"#\" data-headword=\"קִבְעָא\">קִי׳</a>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 1</span>. <span class=\"citation\">Targ. Job VII, 12</span>, v. <a href=\"#\" data-headword=\"גְּרַף\">גְּרַף</a>.</div>","alt":["קִצ","ּא","קִי׳"]},"27219":{"h":"קָצָא","r":"S01781","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָצַע\">קָצַע</a></div>","alt":[]},"27220":{"h":"קְצָא","r":"S01782","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְצֵי\">קְצֵי</a></div>","alt":[]},"27221":{"h":"קָצַב","r":"S01783","html":"<div class=\"sense\"> (b. h.) <i>to cut, decide, determine, limit, bound</i>. <span class=\"citation\">Y. Maasr. IV, 51ᵇ</span> top <span dir=\"rtl\">ק׳ להיסב וכ׳</span> if he had determined to recline for a meal, but did not do so. [<span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> bot. <span dir=\"rtl\">חוגג וקוצב</span>, read: <span dir=\"rtl\">וקוֹצֵר</span>.]—Part. pass. <span dir=\"rtl\">קָצוּב</span>; f. <span dir=\"rtl\">קְצוּבָה</span>; pl. <span dir=\"rtl\">קְצוּבִים</span>, <span dir=\"rtl\">קְצוּבִין</span>; <span dir=\"rtl\">קְצוּבוֹת</span>. <span class=\"citation\">Tosef. Ter. I, 10</span> <span dir=\"rtl\">דבר הק׳ מן התורה</span> a thing (duty) the scope of which is clearly defined in the Torah, v. <a href=\"#\" data-headword=\"קִצְבָה\">קִצְבָה</a>. <span class=\"citation\">Gitt. 50ᵇ</span> <span dir=\"rtl\">לפי שאין ק׳</span> because they (the alimonies of a widow and of orphaned daughters) are not definite (vary according to social position). <span class=\"citation\">Bets. 16ᵃ</span> top <span dir=\"rtl\">כל … ק׳ וכ׳</span> the means of support are definitely assigned to man from the beginning of the year, except the expenses for the Sabbaths … and for education &amp;c. Cant. R. to IV, 2 (ref. to <span dir=\"rtl\">קצובות</span>, ib.) <span dir=\"rtl\">מלין ק׳</span> definitely regulated things (laws); ib. 4 (some ed. <span dir=\"rtl\">קְצִי׳</span>). <span class=\"citation\">Y. Ber. V, beg. 8ᵈ</span> <span dir=\"rtl\">הלכות ק׳</span> decided (settled) questions of law; (Bab. <span class=\"citation\">ib. 31ᵃ</span> <span dir=\"rtl\">הלכה פסוקה</span>); a. fr.</div><div class=\"sense\"><b>Pi. קִיצֵּב</b> <div class=\"sense\"><i>to carve, chop</i> (meat). <span class=\"citation\">Bets. I, 5</span> <span dir=\"rtl\">לקַצֵּב עליו בשר</span> to carve meat on it. <span class=\"citation\">Tosef. ib. I, 11</span> <span dir=\"rtl\">אם קי׳ על העלי</span> if he used the pestle to carve meat on it. Y. Macc. II, beg. 31ᶜ <span dir=\"rtl\">טבח שהוא מְקַצֵּב וכ׳</span> a butcher that chops meat and kills a man (by a slip of the hatchet &amp;c.); a. e.</div></div>","alt":[]},"27222":{"h":"קַצָּב","r":"S01784","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצַב\">preced.</a>) <i>butcher</i>. <span class=\"citation\">Eduy. VIII, 2</span>, a. fr. <span dir=\"rtl\">זכריה בן הק׳</span>.—Pl. <span dir=\"rtl\">קַצָּבִים</span>. <span class=\"citation\">Bets. 25ᵃ</span> <span dir=\"rtl\">והוא הדין לק׳</span> but it applies also to the butchers (that they must not sell meat before flaying and dissecting).</div>","alt":[]},"27223":{"h":"קַצָּבָא","r":"S01785","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">קַצָּבַיָּא</span>. <span class=\"citation\">Bets. 25ᵇ</span>, v. <a href=\"#\" data-headword=\"נְטִיעָה\">נְטִיעָה</a>.</div>","alt":[]},"27224":{"h":"קִצְבָה","r":"S01786","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצַב\">קָצַב</a>) <i>decision, definition, limit, definite scope</i>. <span class=\"citation\">Gitt. 52ᵃ</span> <span dir=\"rtl\">דבר שיש לו ק׳</span> a thing (religious duty) for which there is a definite time and limit v. <a href=\"#\" data-headword=\"קָצַב\">קָצַב</a>. <span class=\"citation\">Pes. VI, 5</span> <span dir=\"rtl\">אם אמרת … שיש להן ק׳ וכ׳</span> you cannot draw an analogy between congregational offerings (on the Sabbath), which are definite, and the Passover sacrifice, which is indefinite; Y. ib. 33ᵃ. Ib. 33ᶜ bot. [read:] <span dir=\"rtl\">מאי אית לך דבר שאין לו ק׳</span> what do you mean by saying, a thing which is undefined? <span dir=\"rtl\">שלא נתנה התורה ק׳ וכ׳</span> the Law does not define how many Passover sacrifices supersede the Sabbath each year (whereas the number of the daily sacrifices is definite). Y. Ber. V, 9ᶜ top <span dir=\"rtl\">כנותן קי׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"מִדָּה\">מִדָּה</a>. <span class=\"citation\">B. Kam. 113ᵃ</span>, v. <a href=\"#\" data-headword=\"מוֹכֵס\">מוֹכֵס</a> h. <span class=\"citation\">B. Mets. IX, 5</span> <span dir=\"rtl\"><span dir=\"rtl\">מה ק׳</span> (<a href=\"#\" data-headword=\"ב\">ב</a>) <a href=\"#\" data-headword=\"כרי\">כרי</a></span> what standard is ‘a pile of grain’? i.e. this cannot be made a standard alike for large and small fields. <span class=\"citation\">Y. Shek. II, 46ᵈ</span> top <span dir=\"rtl\">שקִצְבָתָן מן התורה</span> (ed. Krot. <span dir=\"rtl\">שקִצְוָו׳</span>) which are defined in the Biblical law (as to numbers and times); a. fr.</div>","alt":["קִי׳"]},"27225":{"h":"קַצְדּוֹר","r":"S01787","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּסְדֹּור\">קוּסְדּוֹר</a></div>","alt":[]},"27226":{"h":"קָצָה","r":"S01788","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קצי\">קצי</a></div>","alt":[]},"27227":{"h":"קצה","r":"S01789","html":"<div class=\"sense\">, Pesik. Vayhi, p. 9ᵃ <span dir=\"rtl\">בר ק׳</span>, v. <a href=\"#\" data-headword=\"קַצְרָא II\"><span dir=\"rtl\">קצְרָה</span> I</a></div>","alt":[]},"27228":{"h":"קִצְוָוה","r":"S01790","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִצְבָה\">קִצְבָה</a></div>","alt":[]},"27229":{"h":"קְצָווֹת","r":"S01791","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְצָת\">קְצָת</a></div>","alt":[]},"27230":{"h":"קִצּוּעַ","r":"S01792","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִיצּוּעַ\">קִיצּוּעַ</a></div>","alt":[]},"27231":{"h":"קָצוֹעַ","r":"S01793","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">קָצוֹעוֹת</span> (<a href=\"#\" data-headword=\"קָצַע\">קָצַע</a>) <i>those who cut down trees</i> for war purposes, <i>sappers</i>. <span class=\"citation\">Y. Ned. III, 38ᵃ</span> <span dir=\"rtl\">ראה ק׳ המלך וכ׳</span> (not <span dir=\"rtl\">קצי׳</span>) if he saw the king’s sappers come (to raze plantations).</div>","alt":[]},"27232":{"h":"קְצוּפָה","r":"S01794","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצַף\">קָצַף</a>) <i>visitation by divine anger, death</i>; <span dir=\"rtl\">בית ק׳</span> house of mourning. <span class=\"citation\">Cant. R. to VIII, 5</span> (ref. to <span dir=\"rtl\">הקצפתם</span>, <span class=\"citation\">Deut. IX, 8</span>) <span dir=\"rtl\">עשיתם … לבית אבלה בית ק׳</span> you caused the Lord, as it were, to be a mourner for you; there are places where they call the house of mourning <i>beth ḳ’tsufah</i> (v. P. Sm. 3706 s. v. <a href=\"#\" data-headword=\"קצף\">קצף</a>).—V. <a href=\"#\" data-headword=\"קִצְפָּא\">קִצְפָּא</a>.</div>","alt":[]},"27233":{"h":"קְצוּצָא","r":"S01795","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְצַץ\">קְצַץ</a>; cmp. <a href=\"#\" data-headword=\"גַּוָּוזָא I\"><span dir=\"rtl\">גַּוָּוזָא</span> II</a>) <i>castrate, eunuch.</i> <i>—</i> Pl. <span dir=\"rtl\">קְצוּצֵי</span>. <span class=\"citation\">Ber. 16ᵇ</span> bot. <span dir=\"rtl\">ואע&quot;ג דקיימי ק׳ עילויה דרבי</span> although ennuchs (constables) were at Rabbi’s disposal.</div>","alt":[]},"27234":{"h":"קְצוּצָה","r":"S01796","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">קְצוּצוֹת</span> (<a href=\"#\" data-headword=\"קָצַץ\">קָצַץ</a>; v. <span class=\"citation\">Ex. XXXIX, 3</span>) </div><div class=\"sense\"><b>1)</b> <i>cut metal, strip, wire</i>. <span class=\"citation\">Kel. XI, 3</span> (ed. Dehr. <a href=\"#\" data-headword=\"קְצוֹצֶת\">קְצוֹצֶת</a>); <span class=\"citation\">Tosef. Kel. B. Mets. I, 1</span>.</div><div class=\"sense\"><b>—2)</b> <i>cut fruits</i>, v. <a href=\"#\" data-headword=\"קְצִיצָה\">קְצִיצָה</a>.</div>","alt":[]},"27235":{"h":"קְצוּצִים","r":"S01797","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְצִיצִים\">קְצִיצִים</a></div>","alt":["קְצוּצִין"]},"27236":{"h":"קְצוֹצֶת","r":"S01798","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְצוּצָה\">קְצוּצָה</a></div>","alt":[]},"27237":{"h":"קְצוּצְתָּא","r":"S01799","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קְצוֹצֶת\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>timber, cut board, plank</i>. <span class=\"citation\">B. Kam. 67ᵃ</span> דמעיקרא ק׳ וכ׳ Ms. R. (ed. <a href=\"#\" data-headword=\"קְצִיצְתָּא\">קְצִיצְתָּא</a>; Ms. H. <span dir=\"rtl\">קְצַצְ׳</span>) before (it was made a trough) it was called <i>plank</i>, and now <i>tsinnora.</i>—Pl. <span dir=\"rtl\">קְצוּצְיָיתָה</span>, <span dir=\"rtl\">קְצוּצְיָיתָא</span>. <span class=\"citation\">Ib. 96ᵃ</span> stolen beams <span dir=\"rtl\">עבדינהו קצ׳</span> (Ms. R. <a href=\"#\" data-headword=\"קְצוּצְתָּא\">קְצוּצָתָא</a>; Ms. H. <span dir=\"rtl\">קְצַצְיָיתָא</span>) which he cut into planks.</div><div class=\"sense\"><b>—2)</b>  (comp. <a href=\"#\" data-headword=\"כָּשׁוֹרָא\">כְּשׁוֹרָא</a>) <i>slice</i>.—Pl. <a href=\"#\" data-headword=\"קִיצוּצְוָתָא\">קְצוּצְוָתָא</a>. <span class=\"citation\">Gen. R. s. 79</span> <span dir=\"rtl\">הוה מקצץ … ושדי קְצוּצְוָתֵיה וכ׳</span> (‘Rashi’, <span dir=\"rtl\">קְצִיצָתֵיה</span>; Matt. K. <span dir=\"rtl\">קְצוּצָתֵיה</span>) he cut a lupine and threw its slices about &amp;c.; <span class=\"citation\">Yalk. ib. 133</span> <span dir=\"rtl\">והוה קצרן … קִיצּוּצְוָתֵיה</span> (corr. acc.)</div>","alt":[]},"27238":{"h":"קְצוֹרָא","r":"S01800","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"קְצִירָא\">קְצִירָא</a>; <span dir=\"rtl\">קְצוֹר ערסא</span> <i>sick in bed</i>. <span class=\"citation\">Targ. Job XXIX, 15</span>.</div>","alt":[]},"27239":{"h":"קצותא","r":"S01801","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִיצוּתָא\">קִיצוּתָא</a></div>","alt":[]},"27240":{"h":"קֶצַח","r":"S01802","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>black cumin</i>. <span class=\"citation\">Ukts. III, 6</span>. <span class=\"citation\">Ber. 40ᵃ</span> <span dir=\"rtl\">הרגיל בק׳ וכ׳</span> he that is in the habit of using black cumin will never have pain in the heart (stomach). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ אחד מששים וכ׳</span> black cumin is one of sixty poisonous drugs.</div>","alt":[]},"27241":{"h":"קִצְחָא","r":"S01803","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XXVIII, 25</span>.</div>","alt":["קִי׳"]},"27242":{"h":"קַצְטְרָא","r":"S01804","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַצְרָא III\"><span dir=\"rtl\">קַצְרָא</span> III</a></div>","alt":[]},"27243":{"h":"קצי","r":"S01805","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to scrape</i>. Sifra M’tsorʿa, <span class=\"citation\">Neg., ch. IV</span>, Par. 7 <span dir=\"rtl\">חולץ וקוֹצֶה וטח</span> he must tear out (the leprous stone) and scrape (the wall) and plaster, v. <a href=\"#\" data-headword=\"קָצַע\">קָצַע</a>.</div><div class=\"sense\"><b>—2)</b>  (of figs) <i>to cut, dry, and store; to harvest</i>. <span class=\"citation\">Maasr. II, 7</span> <span dir=\"rtl\">השוכר … לִקְצוֹת עמו וכ׳</span> if a man hires a laborer to help him in the fig harvest. <span class=\"citation\">Ib. III, 1</span> <span dir=\"rtl\">המעביר … לקצות</span> if a person brings figs over to his court to prepare them for storage. Y. ib. II, 50ᵃ bot. <span dir=\"rtl\">להיות … וקוֹצִין אחת</span> that they eat nine portions and store one; a. fr.—V. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a>.</div><div class=\"sense\"><b>—3)</b> <i>to separate, set aside</i>. <span class=\"citation\">Nidd. X, 7</span> (<span class=\"citation\">71ᵇ</span>) <span dir=\"rtl\">קוֹצָה לה חלה</span> she may separate the priest’s share of the dough; <span class=\"citation\">Y. Ber. VIII, 12ᵃ</span>; a. e.</div><div class=\"sense\"><b>—4)</b> <i>to carry off, reduce, level</i> a hill. <span class=\"citation\">Cant. R. to V, 11</span> the fool says, <span dir=\"rtl\">מי יכול לקצות את זה</span> who can level this (mound)?; <span dir=\"rtl\">הריני קוֹצֶה וכ׳</span> I will carry off two loads to-day …, until I have levelled the entire mound; <span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">לקצות … קוצץ</span>; (<span class=\"citation\">Yalk. Cant. 989</span> <span dir=\"rtl\">לפנות … קודח</span>).</div><div class=\"sense\"><b>Hof. הוּקְצָה</b> <div class=\"sense\"><i>to be cut off, separated</i>. <span class=\"citation\">Tosef. B. Bath. III, 5</span> <span dir=\"rtl\">החורשין המוּקְצִין בפני עצמן</span> the forests (near a township) which are isolated (a plantation detached from the town); <span class=\"citation\">B. Bath. 68ᵇ</span> <span dir=\"rtl\">המוקצין לה</span> which are separate but opening into it; corrected <span dir=\"rtl\">המוקצין ממנה</span> separated from it; Y. ib. IV, 14ᶜ bot. <span dir=\"rtl\">החורשים המוקצין ממנה</span> (not <span dir=\"rtl\">הטרשים</span>; corr. quot. s. v. <a href=\"#\" data-headword=\"טֶרֶשׁ\">טֶרֶשׁ</a>).—Esp. <i>to be set aside, be designated for a special purpose and forbidden for any other use</i> (v. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a>). <span class=\"citation\">Sabb. 45ᵃ</span> <span dir=\"rtl\">הואיל וה׳ למצותו ה׳ לאיסורו</span> as the oil was set aside for its religious purpose (for the Sabbath light), it was at the same time set aside as an object prohibited to be used otherwise (during the Sabbath day). Ib. <span dir=\"rtl\">ולית ליה ה׳ למצותו</span> and does he (R. Simon) not adopt the opinion that an object set aside for a religious act is forbidden for any other use (for the time being)?; a. e.—Part. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a> q. v.</div></div>","alt":["קָצָה"]},"27244":{"h":"קְצֵי","r":"S01806","html":"<div class=\"sense\">, <i>to cut, break into pieces</i>. <span class=\"citation\">Targ. Y. Lev. II, 6</span> Ar. (ed. <span dir=\"rtl\">רסיק</span>).—Y. Ber. VI, 10ᵃ bot. <span dir=\"rtl\">כד הוה קָצֵי הוה טעים וכ׳</span> whenever he broke bread, he tasted (carrying a piece to his mouth) with his left hand, and distributed with the right hand. Ib. VIII, 12ᵃ bot. [read:] <span dir=\"rtl\">יהב ליה עגולה דיִקְצֵי</span> he handed him a loaf to break it. <span class=\"citation\">Y. Sabb. VI, end, 8ᵈ</span> [read:] <span dir=\"rtl\">קְצִינָן פלגא וכ׳</span> we broke off one half and gave it to him; a. e.—<span class=\"citation\">B. Mets. 108ᵃ</span> <span dir=\"rtl\">מאן קַצְיֵיה</span>, v. <a href=\"#\" data-headword=\"קוּץ\">קוּץ</a> III ch.</div><div class=\"sense\"><b>Af. אַקְצֵי</b> <div class=\"sense\"><b>1)</b> <i>to set aside, make unavailable for any other purpose</i>. <span class=\"citation\">Succ. 37ᵇ</span> <span dir=\"rtl\">כי אַקְצְיֵיה מריחא אקצייה</span> when he designated it (the myrtle branch) for religious use, he made it unavailable for smelling; <span dir=\"rtl\">מאכילה אקצייה</span> made it unavailable for eating. <span class=\"citation\">Bets. 31ᵇ</span> <span dir=\"rtl\">אַקְצִינְהִי</span>, v. <a href=\"#\" data-headword=\"שְׂרַג\">שְׂרַג</a> or <span dir=\"rtl\">שְׁרַג I</span>.</div><div class=\"sense\"><b>—2)</b> <i>to place in a corner</i>.—Part. pass. f. <span dir=\"rtl\">מַקְצְיָא</span>. <span class=\"citation\">Yoma 17ᵃ</span> <span dir=\"rtl\">האי לשכה אַקְצוּיֵי מקציא וכ׳</span></div></div><div class=\"sense\"><b>Ithpe. אִתְקְצָאִי</b> <div class=\"sense\"><i>to be set aside, be made unavailable</i>. <span class=\"citation\">Sabb. 43ᵃ</span> <span dir=\"rtl\">מיגו דא׳ לבין השמשות א׳ וכ׳</span> since it was forbidden to handle it at twilight (when the Sabbath entered), it became so for the entire day; <span class=\"citation\">Succ. 46ᵇ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">למצותה א׳</span> it was designated only for the religious ceremony (and forbidden for any other use until the ceremony has been performed); <span dir=\"rtl\">לכוליה יומא א׳</span> it is unavailable for the entire day (even after the ceremony has been performed); a. e.</div></div>","alt":["קְצָא"]},"27245":{"h":"קָצַיָּא","r":"S01807","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְצֵי\">preced.</a>) <i>cut pieces, planks</i>. <span class=\"citation\">Ex. R. s. 6</span>, end; Tanḥ. Vaëra 2, v. <a href=\"#\" data-headword=\"הֲנָיָיה\">הֲנָיָיה</a> ch.</div>","alt":["קָצַיָּיא"]},"27246":{"h":"קַצְיָא","r":"S01808","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḳatsia</i>, name of a legendary king residing behind the Dark Mountains (v. <a href=\"#\" data-headword=\"חשֶׁךְ\">חשֶׁךְ</a>). <span class=\"citation\">Gen. R. s. 33</span>; <span class=\"citation\">Lev. R. s. 27</span>; <span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> bot.; Tanḥ. Emor 6; <span class=\"citation\">Yalk. Ps. 727</span>.</div>","alt":["קַצְיָיא"]},"27247":{"h":"קְצִיבִין","r":"S01809","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to IV, 4</span> some ed., a. e. = <span dir=\"rtl\">קְצוּבִין</span>, v. <a href=\"#\" data-headword=\"קָצַב\">קָצַב</a></div>","alt":[]},"27248":{"h":"קציון","r":"S01810","html":"<div class=\"sense\">, <span class=\"citation\">Y. Bets. V, end, 63ᵇ</span>, v. <a href=\"#\" data-headword=\"קְרַצְיוֹן\">קְרַצְיוֹן</a></div>","alt":[]},"27249":{"h":"קַצְיָיא","r":"S01811","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַצְיָא\">קַצְיָא</a></div>","alt":[]},"27250":{"h":"קָצַיָּיא","r":"S01812","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָצַיָּא\">קָצַיָּא</a></div>","alt":["קָצַיָּיה"]},"27251":{"h":"קַצְיָין","r":"S01813","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קְצֵי\">קְצֵי</a>) <i>pieces</i> of bread. <span class=\"citation\">Targ. Y. Lev. II, 6</span> Ar. (ed. <span dir=\"rtl\">ריסוקין</span>).</div>","alt":[]},"27252":{"h":"קָצִין","r":"S01814","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>one who decides, arbitrates</i>,] <i>magistrate, leader, prominent man</i>. <span class=\"citation\">Y. Gitt. I, 43ᵈ</span> top <span dir=\"rtl\">הגע … של ק׳ וכ׳</span> suppose he was the bondman of an influential man, then his emancipation would be a disadvantage to him. <span class=\"citation\">Lam. R. to II, 1</span> <span dir=\"rtl\">בשביל … של ק׳ וכ׳</span> since thou livest in that leader’s house, why dost thou not correct them (the inmates)?</div>","alt":[]},"27253":{"h":"קְצִיעָא","r":"S01815","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (part. pass. of <a href=\"#\" data-headword=\"קְצַע\">קְצַע</a>) <i>cut.</i>—Pl. <span dir=\"rtl\">קְצִיעֵי</span>. <span class=\"citation\">Ex. R. s. 41</span> (in Hebr. dict.) <span dir=\"rtl\">ק׳ צואריא</span> you whose throats deserve to be cut.</div>","alt":[]},"27254":{"h":"קְצִיעָה I","r":"S01816","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצַע\">קָצַע</a>) </div><div class=\"sense\"><b>1)</b> <i>cutting and packing figs, fig-harvest</i>. <span class=\"citation\">Maasr. II, 7</span>; a. e.</div><div class=\"sense\"><b>—2)</b> pl. <span dir=\"rtl\">קְצִיעוֹת</span> <i>figs packed</i> or <i>to be packed</i>. <span class=\"citation\">Ter. IV, 10</span> <span dir=\"rtl\">בדורס ליטרא ק׳ וכ׳</span> if one has packed a litra of figs (of T’rumah) on top of a barrel and knows not of which; <span class=\"citation\">Tosef. ib. V, 11</span>; <span class=\"citation\">Bets. 3ᵇ</span>; <span class=\"citation\">Zeb. 73ᵃ</span>. <span class=\"citation\">Taan. 28ᵃ</span>; Tosef. ib. IV (III), 7 <span dir=\"rtl\">לעשות ק׳ הללו שתי וכ׳</span> to make of these figs two balls; Y. ib. IV, 68ᵇ bot.; a. e.—[<span class=\"citation\">Maasr. III, 4</span>; <span class=\"citation\">B. Mets. 21ᵇ</span>, v. <a href=\"#\" data-headword=\"קְצִיצָה\">קְצִיצָה</a>.]</div><div class=\"sense\"><b>—3)</b>  [<i>store, capsule</i>,] <i>a compartment of the T’fillin</i>. <span class=\"citation\">Tosef. Kel. B. Bath. IV, 1</span> <span dir=\"rtl\">משיתיר … בין ק׳ וכ׳</span> when he detaches one compartment from the other on three sides; [El. Wil. emends: <a href=\"#\" data-headword=\"קְצִיצָה\">קְצִיצָה</a> q. v.]—[<span class=\"citation\">Y. Ned. III, 38ᵃ</span> <span dir=\"rtl\">קציעות</span>, v. <a href=\"#\" data-headword=\"קָצוֹעַ\">קָצוֹעַ</a>.]</div>","alt":[]},"27255":{"h":"קְצִיעָה II","r":"S01817","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>cassia, an aromatic bark</i>, an ingredient of frankincense. <span class=\"citation\">Ker. 6ᵃ</span>; Y. Yoma IV, 41ᵃ; a. e.</div><div class=\"sense\"><b>—2)</b>  pr. n. f. <i>Keziah</i>, one of Job’s daughters. <span class=\"citation\">B. Bath. 16ᵇ</span> <span dir=\"rtl\">ק׳ … כקציעה</span> she was named K., because her savor spread like that of cassia.</div>","alt":[]},"27256":{"h":"קְצִיעֲתָא","r":"S01818","html":"<div class=\"sense\">, <i>cassia</i>. <span class=\"citation\">Targ. Job XLII, 14</span>. <span class=\"citation\">Targ. Ex. XXX, 24</span> (h. text <a href=\"#\" data-headword=\"קִדָּה\">קִדָּה</a>).—Pl. <a href=\"#\" data-headword=\"קְצִיעֲתָא\">קְצִיעָתָא</a>. <span class=\"citation\">Targ. Ps. XLV, 9</span> Ms. (ed. <i>sing.</i>).</div>","alt":[]},"27257":{"h":"קְצִיפָה","r":"S01819","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצַף\">קָצַף</a>) <i>anger</i>. <span class=\"citation\">Lam. R. to V, 20</span> <span dir=\"rtl\">ק׳ הושב ע&quot;י וכ׳</span> the prediction of God’s anger was contradicted by Isaiah (<span class=\"citation\">Is. LVII, 16</span>). Ib. 22; ib. to I, 2, v. <a href=\"#\" data-headword=\"מְאִיסָה\">מְאִיסָה</a>; Pesik. Vattom., p. 130ᵇ <a href=\"#\" data-headword=\"קצפין\">קצפין</a> (read: <a href=\"#\" data-headword=\"קִצָּפוֹן\">קִצָפוֹן</a>). <span class=\"citation\">Esth. R. to I, 18</span> <span dir=\"rtl\">כדי … לק׳ הזאת</span> this shame is enough to cause such anger.</div>","alt":[]},"27258":{"h":"קְצִיצָא","r":"S01820","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְצַץ\">קְצַץ</a>) <i>cut, figure</i>; (cmp. French taille) <i>waist</i>. Targ. II Esth. I, 2 (3) <span dir=\"rtl\">כולהון … בני ק׳ חדא</span> all of them of the same height …, of the same figure.</div>","alt":[]},"27259":{"h":"קְצִיצָה","r":"S01821","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצַץ\">קָצַץ</a>) </div><div class=\"sense\"><b>1)</b> <i>cutting, felling</i>. <span class=\"citation\">B. Kam. 91ᵇ</span> <span dir=\"rtl\">אילן העומד לק׳</span> (Ms. F. <span dir=\"rtl\">לִיקָּצֵץ</span>) a tree which must be cut. Lam. R. introd. (R. Z’ʿera) <span dir=\"rtl\">שבו זמן ק׳ יפה וכ׳</span> on it (the 15<sup>ᵗʰ</sup> of Ab) begins the good season for cutting trees for fuel, v. <a href=\"#\" data-headword=\"מַאֲכוֹלֶת\">מַאֲכוֹלֶת</a>. <span class=\"citation\">Bekh. 34ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">איכוין … בהאי ק׳ וכ׳</span> he intended to make himself appear clean by cutting off (the leprous spot), and the rabbis punished him for this very cut (so that he could never be declared clean from this cut-off leprous spot); a. e.</div><div class=\"sense\"><b>—2)</b> <i>stipulation</i> (<i>of price</i> &amp;c.), bargain. <span class=\"citation\">Shebu. 45ᵇ</span> <span dir=\"rtl\">ק׳ ודאי וכ׳</span> stipulations of prices one surely remembers, v. <a href=\"#\" data-headword=\"קִיצוּתָא\">קִיצוּתָא</a>.</div><div class=\"sense\"><b>—3)</b> pl. <span dir=\"rtl\">קְצִיצוֹת</span> <i>cut fruits</i>. <span class=\"citation\">Maasr. III, 4</span> <span dir=\"rtl\">מצא ק׳ בדרך ואפי׳ בצד שדה ק׳</span> (Ms. M. <span dir=\"rtl\">קציעות</span>) if one finds cut fruit (single berries) on the road or even beside a field where cut fruit has been spread to dry; <span class=\"citation\">B. Mets. 21ᵇ</span> Var. (ed. <span dir=\"rtl\">קציעות</span>).</div><div class=\"sense\"><b>—4)</b>  (v. <a href=\"#\" data-headword=\"קְצִיצָה\">קְצִיצָה</a> a. <a href=\"#\" data-headword=\"קְצִיצִים\">next w.</a>) <i>the capsule of the T’fillin</i> containing Biblical sections. <span class=\"citation\">Ber. 24ᵃ</span>. <span class=\"citation\">Succ. 26ᵇ</span> top. <span class=\"citation\">Kel. XVIII, 8</span> <span dir=\"rtl\">התיר ק׳ וכ׳</span> if he opened the first of the four compartments of the T’fillin and repaired it; a. e.—Pl. <a href=\"#\" data-headword=\"קְצִיצִים\">קְצִיצִין</a>, v. <a href=\"#\" data-headword=\"קְצִיצִים\">next w.</a></div><div class=\"sense\"><b>—5)</b> <i>separation, severance of connection</i>, v. <a href=\"#\" data-headword=\"קְצָצָה\">קְצָצָה</a>.</div>","alt":[]},"27260":{"h":"קְצִיצִים","r":"S01822","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצַץ\">קָצַץ</a>, cmp. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a>) [<i>stores</i>,] </div><div class=\"sense\"><b>1)</b> <i>capsules, pods</i>. <span class=\"citation\">Tosef. Shebi. II, 6</span> <span dir=\"rtl\">אם עשה ק׳ גמורין וכ׳</span> (Var. <a href=\"#\" data-headword=\"קְצוּצִים\">קְצוּצִים</a>) if the plant has produced ripe capsules (or pods) before the New Year; Y. ib. II, 34ᵃ <a href=\"#\" data-headword=\"קְצָצִין\">קְצָצִין</a>.</div><div class=\"sense\"><b>—2)</b> <i>capsules containing Scriptural portions, T’fillin</i>, (v. <a href=\"#\" data-headword=\"קְצִיצָה\">preced.</a> 4). <span class=\"citation\">Gitt. 57ᵇ</span> sq. <span dir=\"rtl\">ארבעים סאה קְצִיצֵי תפלין וכ׳</span> Ar. (ed. <span dir=\"rtl\">קְצוּצֵי</span>; Rashi to <span class=\"citation\">Succ. 26ᵇ</span> <span dir=\"rtl\">קיצוצי</span>) forty S’ahs of capsules of T’fillin were found on the heads of those slain at Bethar; <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">קצוצי</span>; <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> top <span dir=\"rtl\">קצוצי</span>.</div>","alt":["קְצִיצִין"]},"27261":{"h":"קְצִיצְתָּא","r":"S01823","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְצוּצְתָּא\">קְצוּצְתָּא</a></div>","alt":[]},"27262":{"h":"קְצֵיר־","r":"S01824","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָצֵר\">קָצֵר</a></div>","alt":[]},"27263":{"h":"קָצִיר","r":"S01825","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>cutting, harvest, ripening season</i>. <span class=\"citation\">R. Hash. 9ᵃ</span> <span dir=\"rtl\">ק׳ של שביעית וכ׳</span> a ripening in the Sabbatical year which goes over into the eighth year, i.e. plants which were partly ripe in the Sabbatical year are subject to the laws of the Sabbatical year. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קְצִיר העומר</span> the cutting of the ʿOmer (v. <a href=\"#\" data-headword=\"עוֹמֶר\">עוֹמֶר</a>); a. fr.—<span class=\"citation\">Lev. R. s. 18</span> (ref. to <span class=\"citation\">Is. XVII, 11</span>) <span dir=\"rtl\">קְצִירָן של מלכיות</span> (<a href=\"#\" data-headword=\"קְצִיבִין\">קְצִירִין</a>) the cutting down (destruction threatened) by the government; <span dir=\"rtl\">ק׳ של יסורין</span> by sufferings; <span dir=\"rtl\">קְצִירוֹ של מלאך וכ׳</span> the cutting down by the angel of death, v. <a href=\"#\" data-headword=\"נִדְנֵד\">נִדְנֵד</a>; <span class=\"citation\">Yalk. Is. 287</span>.—Pl. <a href=\"#\" data-headword=\"קְצִיבִין\">קְצִירִין</a>, v. supra.</div>","alt":[]},"27264":{"h":"קְצִירָא","r":"S01826","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְצַר\">קְצַר</a>) [<i>cut, afflicted</i>,] <i>sick</i>. <span class=\"citation\">B. Bath. 16ᵇ</span>, v. <a href=\"#\" data-headword=\"דְּלֵי\">דְּלֵי</a>. <span class=\"citation\">Sabb. 12ᵇ</span> לשיולי בק׳ Ar. (ed. <span dir=\"rtl\">בתפיחה</span>) to inquire after the health of (to visit) a sick person.—Pl. <span dir=\"rtl\">קְצִירֵי</span>. <span class=\"citation\">R. Hash. 16ᵃ</span>; <span class=\"citation\">Ned. 49ᵇ</span>, v. <a href=\"#\" data-headword=\"מְרִיעַ\">מְרִיעַ</a>. <span class=\"citation\">Gitt. 56ᵃ</span>, v. <a href=\"#\" data-headword=\"נְקַט\">נְקַט</a>; a. e.—[<span dir=\"rtl\">קציריא</span>, <span class=\"citation\">Targ. Is. VII, 3</span> ed. Wil., v. <a href=\"#\" data-headword=\"קַצָּר\">קַצָּר</a>.]—[<span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> <span dir=\"rtl\">קציריא דגליל</span>, v. <a href=\"#\" data-headword=\"קַצְרָא III\"><span dir=\"rtl\">קַצְרָא</span> III</a>.]</div>","alt":[]},"27265":{"h":"קְצִירָה","r":"S01827","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"קָצִיר\">קָצִיר</a> <i>cutting, harvesting</i>. <span class=\"citation\">Y. Peah I, beg. 15ᵃ</span> <span dir=\"rtl\">קְצִירַת שבולת וכ׳</span> the cutting of the first ear has the same effect (on the duty of leaving a corner) as the striking off of the pile has (on the duty of giving T’rumah). <span class=\"citation\">Sabb. 70ᵃ</span>; a. fr.</div>","alt":[]},"27266":{"h":"קָצַע","r":"S01828","html":"<div class=\"sense\"><b>1)</b> <i>to scrape</i>. <span class=\"citation\">Neg. XII, 6</span> <span dir=\"rtl\">שניהן … קוֹצְעִין</span> both neighbors must bear the expense for tearing out (the leprous stone) and for scraping (the wall); Sifra M’tsorʿa, Neg., Par. 6, ch. IV; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to cut</i>, <i>dry</i>, <i>and pack figs</i> (v. <a href=\"#\" data-headword=\"קְצִיעָה I\">קְצִיעָה</a>). <span class=\"citation\">Taan. 28ᵃ</span> <span dir=\"rtl\">קוֹצְעֵי קציעית</span> those pretending to be engaged in packing figs; Tosef. ib. IV (III), 7 (Var. <span dir=\"rtl\">קוֹצְאֵי</span>); Y. ib. IV, 68ᵇ bot.</div><div class=\"sense\"><b>—3)</b> <i>to trim</i>, v. infra.</div><div class=\"sense\"><b>Pi. קִיצֵּעַ</b> <div class=\"sense\"><i>to cut the ends, trim</i>. <span class=\"citation\">Kel. XXVII, 4</span> <span dir=\"rtl\">המְקַצֵּע מכולם וכ׳</span> if in trimming any of them he cuts off a piece one handbreadth square. <span class=\"citation\">Zeb. 94ᵃ</span> <span dir=\"rtl\">עוצבא … לקַצְּעָהּ … עד שיְקַצְּעֶנָּה</span> a fur intended to be trimmed (v. <a href=\"#\" data-headword=\"עִיצְבָּא\">עיּצְבָּא</a>) remains unsusceptible of uncleanness until it has been trimmed; <span class=\"citation\">Tosef. Kel. B. Bath. IV, 10</span>. <span class=\"citation\">B. Kam. 66ᵇ</span> <span dir=\"rtl\">כגון שקִיצְּעָן</span> (Ar. <span dir=\"rtl\">שקצען</span>) when he trimmed the stolen furs. <span class=\"citation\">Tosef. Kel. B. Mets. XI, 8</span> <span dir=\"rtl\">אם היה גדול וקִיצְּעוֹ</span> (not <span dir=\"rtl\">וקיצעו</span>) if the cloth was large and he shortened it by trimming; <span class=\"citation\">ib. 9</span>. <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">עד שיְקַצֵּעַ</span> (or <span dir=\"rtl\">שיִקְצַע</span>) until he cuts off (the defective portion). <span class=\"citation\">Ḥull. 123ᵇ</span> <span dir=\"rtl\">במקצע ובא לו וכ׳</span> when he trimmed (the skin) going all around; a. e.</div></div>","alt":[]},"27267":{"h":"קְצַע","r":"S01829","html":"<div class=\"sense\"><i>Pa.</i> <span dir=\"rtl\">קַצֵּעַ</span> <a href=\"#\" data-headword=\"קָצַע\">same</a>, <i>to trim, cut</i>. <span class=\"citation\">Zeb. 94ᵃ</span> <span dir=\"rtl\">דחשיב עלה לקַצְּעָהּ</span> when he had planned to trim it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עד דמְקַצַּע לה</span>, v. <a href=\"#\" data-headword=\"קָצַע\">preced.</a></div>","alt":[]},"27268":{"h":"קָצַף","r":"S01830","html":"<div class=\"sense\"> (b. h.) [<i>to be rough, excited</i>,] <i>to be angry</i>. <span class=\"citation\">Esth. R. to I, 18</span>, v. <a href=\"#\" data-headword=\"קִצָּפוֹן\">קִצָּפוֹן</a>. <span class=\"citation\">Midr. Till. to Ps. XXXVIII</span> <span dir=\"rtl\">אנו … ואתה קוֹצֵף</span> we sin, and thou art angry. <span class=\"citation\">Yalk. Esth. 1053</span> <span dir=\"rtl\">קָצְפוּ ואמרו וכ׳</span> they grew excited and said &amp;c.; a. fr.</div><div class=\"sense\"><b>Hif. הִקְצִיף</b> <div class=\"sense\"><i>to arouse to anger, excite, incite</i>. <span class=\"citation\">Meg. 13ᵇ</span> (ref. to <span class=\"citation\">Gen. XL, 2</span> a. <span class=\"citation\">Esth. II, 21</span>) <span dir=\"rtl\">ה׳ הקב&quot;ה אדון על עבדיו וכ׳</span> the Lord incited a master against his servants, in order to satisfy the desire of a righteous man …, servants against their master, in order to perform wonders for a righteous man; <span class=\"citation\">Gen. R. s. 88</span>; <span class=\"citation\">Esth. R. to II, 21</span>; <span class=\"citation\">Yalk. Gen. 146</span> <span dir=\"rtl\">מַקְצִיף</span>; a. e.</div></div>","alt":[]},"27269":{"h":"קצף","r":"S01831","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Lam. II, 3</span> ed. Vien., v. <a href=\"#\" data-headword=\"קְצַץ\">קְצַץ</a></div>","alt":[]},"27270":{"h":"קֶצֶף","r":"S01832","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קצף\">preced. art.</a>) </div><div class=\"sense\"><b>1)</b> <i>anger</i>. <span class=\"citation\">Num. R. s. 1</span>, end <span dir=\"rtl\">שלא יהא ק׳ עליהן</span> that the divine anger be not on them. <span class=\"citation\">Midr. Till. to Ps. XXXVIII</span>; a. fr.—Esp. <i>Ḳetsef</i> name of an angel of destruction. <span class=\"citation\">Targ. Y. Num. XVII, 11</span>, sq.—<span class=\"citation\">Sabb. 55ᵃ</span> (ref. to <span class=\"citation\">Ez. IX, 2</span>) ‘six men’, they are <span dir=\"rtl\">ק׳ אף וחימה וכ׳</span> Ḳ. (Wrath), <i>Af</i> (Anger) &amp;c. <span class=\"citation\">Ex. R. s. 41</span>; a. fr.—2) <i>destruction, harm</i>. <span class=\"citation\">Deut. R. s. 11</span> <span dir=\"rtl\">איך … לעשות לו ק׳</span> how can I do harm to him (Moses)?; <span class=\"citation\">Yalk. ib. 940</span>.</div>","alt":[]},"27271":{"h":"קִצְפָּא","r":"S01833","html":"<div class=\"sense\">, <i>divine anger, visitation</i>, (<i>mourning over a</i>) <i>death</i>. <span class=\"citation\">Midr. Till. to Ps. CVI</span> <span dir=\"rtl\">אית … לאבלא ק׳</span> there are places where they call mourning <i>ḳitspa</i>; v. <span dir=\"rtl\">קְצוּפָח</span>.</div>","alt":["קִיצְ׳"]},"27272":{"h":"קִצָּפוֹן","r":"S01834","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קִצְפָּא\">preced.</a> wds.) <i>anger</i>. <span class=\"citation\">Lev. R. s. 32</span> (ref. to <span dir=\"rtl\">ויקצף</span>, <span class=\"citation\">Deut. I, 34</span>) <span dir=\"rtl\">להם הוא ק׳ ולי מה אני ק׳ וכ׳</span> to them it appears as anger, but to myself what does anger mean? ‘I swore by my anger’ (<span class=\"citation\">Ps. XCV, 11</span>), I swear by my anger and reconsider; Yalk. ib. 657. <span class=\"citation\">Esth. R. to I, 18</span> <span dir=\"rtl\">כדאי הוא הבזיון … לק׳ שקצף וכ׳</span> the disrespect with which her (Vashti’s) father treated the vessels of the Temple is enough to deserve the wrath which he (Ahasverus) vented on her and put her to death. Ib. <span dir=\"rtl\">כדי הק׳ לבזיון זה</span> the anger (of Ahasverus) corresponds to this contempt (shown by Vashti), v. <a href=\"#\" data-headword=\"קְצִיפָה\">קְצִיפָה</a>. Ib. to II, 21 <span dir=\"rtl\">מה ק׳ היה שם</span> what cause was there for discontent? Sifra Sh’mini, Par. 1, ch. II (ref. to <span class=\"citation\">Lev. X, 16</span>) <span dir=\"rtl\">אף אהרן היה בק׳</span> Aaron, too, was included in the anger (of Moses). Pesik. Vattom., p. 130ᵇ <span dir=\"rtl\">אין ק׳ הוא</span> (not <a href=\"#\" data-headword=\"קצפין\">קצפין</a>), v. <a href=\"#\" data-headword=\"קְצִיפָה\">קְצִיפָה</a>.</div>","alt":["קִיצָּ׳"]},"27273":{"h":"קצפין","r":"S01835","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִצָּפוֹן\">preced.</a></div>","alt":[]},"27274":{"h":"קָצַץ","r":"S01836","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to cut, fell</i>. <span class=\"citation\">Shebi. IV, 10</span> <span dir=\"rtl\">מותר לקוֹצְצוֹ</span> it is permitted to cut the tree down (in the Sabbatical year). Ib. <span dir=\"rtl\">כמה … ולא יְקוֹצֶּנּוּ</span> (Y. ed. <span dir=\"rtl\">יקצונו</span>, corr. acc.; Bab. ed. <span dir=\"rtl\">יְקוֹצְצוֹ</span>; Ms. M. <span dir=\"rtl\">יִקְצְצֶנּוּ</span>) how much must an olive tree bear so that one dare not cut it down (because it is an act of wilful destruction, <span class=\"citation\">Deut. XX, 19–20</span>); <span class=\"citation\">B. Kam. 91ᵇ</span> יקצצנו Ms. F. a. R. (later ed. <span dir=\"rtl\">יִקְצְצוֹ</span>; v. Rabb. D. S. a. l. note 10). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נטיעותי קָצַצְתָּ</span> thou hast cut down my young trees; <span dir=\"rtl\">אתה אמרת לי לקוֹצְצָן</span> (not <span dir=\"rtl\">לקוצצו</span>, v. Rabb. D. S. a. l. note 7) thou hast told me to cut them. <span class=\"citation\">Y. Shebi. IV, 35ᵇ</span> bot. <span dir=\"rtl\">לָקוֹץ … יָקוֹץ</span>, v. <a href=\"#\" data-headword=\"נָתַק\">נָתַק</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הקוצץ בקורות</span> he that cuts trunks for beams. <span class=\"citation\">Lev. R. s. 23</span>, v. infra.—<span class=\"citation\">Sifré Deut. 212</span> (expl. <span dir=\"rtl\">ועשתה</span>, <span class=\"citation\">Deut. XXI, 12</span>) <span dir=\"rtl\">תָּקוֹץ</span> let her cut (her nails). <span class=\"citation\">Macc. 22ᵃ</span> <span dir=\"rtl\">הקוצץ את בהרתו</span> he that cuts off a white spot (suspicious of leprosy, v. <a href=\"#\" data-headword=\"קְצִיצָה\">קְצִיצָה</a>); <span class=\"citation\">Neg. VII, 5</span> <span dir=\"rtl\">קְצָצָהּ מתכוין</span> if he cut it intentionally. <span class=\"citation\">Tosef. Sabb. XI</span> (<span class=\"citation\">XII), 3</span>; a. fr.—<span class=\"citation\">Gen. R. s. 85</span> (ref. to <span class=\"citation\">Dan. V, 1</span> a. <span class=\"citation\">VI, 1</span>) <span dir=\"rtl\">והיכן הוא … קוצץ לקוצץ</span> where is Evil Merodach?… (He is left out) in order to join a wicked man to a wicked man, a destroyer to a destroyer. <span class=\"citation\">Y. Yeb. II, 4ᵃ</span> top <span dir=\"rtl\">קוצץ בן קוצץ</span> a destroyer son of a destroyer (wicked by heredity); Pesik. S’liḥ. p. 167ᵇ <span dir=\"rtl\">אין בישראל קו׳ בן קו׳</span> there is no hereditary wickedness in Israel. <span class=\"citation\">Ex. R. s. 1</span> וקוץ … שק׳ עצת וכ׳ Koz (<span class=\"citation\">I Chr. IV, 8</span>) is Caleb, for he destroyed the counsel of the spies; a. fr.—2) (cmp. <a href=\"#\" data-headword=\"קָצַב\">קָצַב</a>, <a href=\"#\" data-headword=\"גָּזַר\">גָּזַר</a>) <i>to stipulate, agree upon</i>. <span class=\"citation\">Shebu. 45ᵇ</span> <span dir=\"rtl\">אפי׳ ק׳ נמי</span> let it be the same even if a stipulation has been made (and the amount is in litigation). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אומן … קָצַצְתָּ … לא קָצַצְתִּי וכ׳</span> if the mechanic says, thou hast stipulated to pay me two (Zuz), and he (the employer) says, I have stipulated one only; a. e.—Part. pass. <span dir=\"rtl\">קָצוּץ</span>; f. <a href=\"#\" data-headword=\"קְצוּצָה\">קְצוּצָה</a>. <span class=\"citation\">B. Mets. 61ᵇ</span> <span dir=\"rtl\">רבית ק׳</span> stipulated, direct usury, opp. <span dir=\"rtl\">אבק רבית</span>, v. <a href=\"#\" data-headword=\"אָבָק\">אָבָק</a>. <span class=\"citation\">Ib. 62ᵇ</span>; a. e.</div><div class=\"sense\"><b>Nif. נִקְצָץ</b> <div class=\"sense\"><b>1)</b> <i>to be cut</i>. Neg. l. c. <span dir=\"rtl\">מי … ונִקְצָצָה</span> if one had a white spot, and it was cut off (accidentally). <span class=\"citation\">Nidd. II, 1</span> <span dir=\"rtl\">תִּקָּצֵץ</span> let the hand be cut off. <span class=\"citation\">B. Kam. 91ᵇ</span>, v. <a href=\"#\" data-headword=\"קְצִיצָה\">קְצִיצָה</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be cut off, excluded</i>. Y. Kidd. I, 60ᶜ, a. e., v. <a href=\"#\" data-headword=\"קְצָצָה\">קְצָצָה</a>.</div><div class=\"sense\"><b>—3)</b> <i>to be stipulated, definitely assigned</i>. <span class=\"citation\">Lev. R. s. 30</span>, beg. <span dir=\"rtl\">מראש השנה נִקְצָצִין וכ׳</span> from the beginning of the year the means of support are definitely assigned to men, except &amp;c., v. <a href=\"#\" data-headword=\"קָצַב\">קָצַב</a>.</div></div><div class=\"sense\"><b>Pi. קִיצֵּץ</b> <div class=\"sense\"><b>1)</b> <i>to scrape, cut off; to fell</i>. <span class=\"citation\">Pes. 56ᵃ</span> <span dir=\"rtl\">ק׳ דלתות וכ׳</span> (<span class=\"citation\">II Kings XVIII, 16</span>) he took the gold off the Temple doors. Y. Ber. VIII, 12ᵃ bot. <span dir=\"rtl\">אפי׳ מְקַצֵּץ וכ׳</span> even when cutting lupines. Ib. II, 5ᶜ top <span dir=\"rtl\">היה מקצץ כל וכ׳</span> he cut down all he had planted. <span class=\"citation\">Pesik. R. s. 31</span> <span dir=\"rtl\">ומְקַצְּצִים</span>, v. <a href=\"#\" data-headword=\"רָצַץ\">רָצַץ</a>. <span class=\"citation\">Cant. R. to II, 2</span> <span dir=\"rtl\">לקַצְּצוֹ</span>; <span class=\"citation\">Lev. R. s. 23</span> <span dir=\"rtl\">לָקוֹצּוֹ</span>, v. <a href=\"#\" data-headword=\"קַצָּץ\">קַצָּץ</a>.—Esp. <span dir=\"rtl\">ק׳ בנט עות</span> [<i>to cut down the shoots</i> in the garden of religion,] <i>to be hostile to religion, corrupt the youths; to be a heretic</i>. <span class=\"citation\">Ḥag. 14ᵇ</span>; Y. ib. II, 77ᵇ top, v. <a href=\"#\" data-headword=\"נְטִיעָה\">נְטִיעָה</a>. <span class=\"citation\">Cant. R. to I, 4</span> <span dir=\"rtl\">כיצד ק׳ בנ׳</span> in what way did he manifest his hostility to religion? <span class=\"citation\">Gen. R. s. 19</span> <span dir=\"rtl\">לא תעשה … וִיקַצֵּץ וכ׳</span> make not the fence (around the religious laws) more important than the essentials, lest it fall down and ruin the shoots.</div><div class=\"sense\"><b>—2)</b> <i>to stipulate</i>. <span class=\"citation\">Shebi. IV, 1</span> <span dir=\"rtl\">ואין … שיְקַצֵּץ להם מזונות</span> (R. S. <span dir=\"rtl\">שיִקְצוֹץ</span>) it is unnecessary to say, that he must not stipulate to give them their food (for their work).</div></div><div class=\"sense\"><b>Hif. הֵקֵיץ</b> <div class=\"sense\"><i>to cut off, deduct</i>. <span class=\"citation\">Sifré Num. 8</span> <span dir=\"rtl\">ומֵקֵיץ מכתובתה</span> he may deduct (his outlay for her) from her jointure.</div></div>","alt":[]},"27275":{"h":"קְצַץ","r":"S01837","html":"<div class=\"sense\"><b>1)</b>  to <i>cut</i> &amp;c. <span class=\"citation\">Targ. Jud. VI, 30</span>. <span class=\"citation\">Targ. O. Deut. XIX, 5</span>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"קְצַץ\">קָצִיץ</a>; f. <a href=\"#\" data-headword=\"קְצִיצָא\">קְצִיצָא</a>; pl. <a href=\"#\" data-headword=\"קְצִיצִים\">קְצִיצִין</a>; <a href=\"#\" data-headword=\"קְצִיצָא\">קְצִיצָן</a>. <span class=\"citation\">Targ. Jud. VI, 28</span>. <span class=\"citation\">Targ. I Sam. V, 4</span>; a. e.—<span class=\"citation\">Snh. 58ᵇ</span> רב הונא קץ ידא Rab Huna ordered the hand (of one in the habit of striking his neighbors) to be cut off; <span class=\"citation\">Nidd. 13ᵇ</span>. <span class=\"citation\">B. Kam. 91ᵇ</span> <span dir=\"rtl\">דקץ תאינתא וכ׳</span> he cut fig-trees down before their time; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to stipulate</i>. <span class=\"citation\">B. Mets. 67ᵃ</span> <span dir=\"rtl\">לא קץ ליה</span> he had not stipulated a fixed amount of interest; a. e.</div><div class=\"sense\"><b>Pa. קַצֵּיץ</b> <div class=\"sense\"> (<a href=\"#\" data-headword=\"קְצַץ\">קָצֵיץ</a>) <i>to cut; to mutilate</i>. <span class=\"citation\">Targ. Ps. CVII, 16</span>. <span class=\"citation\">Targ. Lam. II, 3</span> (ed. Lag. <a href=\"#\" data-headword=\"קָצַץ\">קיצץ</a>, ed. Vien. <a href=\"#\" data-headword=\"קצף\">קצף</a>, corr. acc.). <span class=\"citation\">Targ. O. Deut. VII, 5</span> <span dir=\"rtl\">תְּקָצְצוּן</span> ed. Berl. (oth. ed. <span dir=\"rtl\">תְּקוֹצְצוּן</span>; Y. <span dir=\"rtl\">תְּקַצְּצוּן</span>); a. e.—B. Kam. l. c. <span dir=\"rtl\">דיקלא … לִמְקַצְּצָה</span> it is forbidden to fell a date-tree as long as it bears a Kab of dates. <span class=\"citation\">Gen. R. s. 6</span> (of the agony of death) <span dir=\"rtl\">כמא נפשיה … מְקַצְּצָא ארזין ומקצצא וכ׳</span> how the soul of this man’s (my) brother is cutting cedars and cutting trees, and you sit laughing and know it not; a. e.—[<span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">שעריה מקצץ</span>, v. <a href=\"#\" data-headword=\"קְוַץ\">קְוַץ</a>.]</div></div>","alt":["קַץ"]},"27276":{"h":"קַצָּץ","r":"S01838","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְצַץ\">preced.</a>) <i>wood-cutter</i> (cmp. <a href=\"#\" data-headword=\"קָצוֹעַ\">קָצוֹעַ</a>).—Pl. <a href=\"#\" data-headword=\"קְצָצִים\">קַצָּצִים</a>. <span class=\"citation\">Cant. R. to II, 2</span> <span dir=\"rtl\">הביא ק׳ לְקַצְּצוֹ</span> he brought on cutters to raze the plantation; <span class=\"citation\">Lev. R. s. 23</span>.</div>","alt":[]},"27277":{"h":"קְצָצָה","r":"S01839","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַצָּץ\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>timber</i>. <span class=\"citation\">Cant. R. to IV, 12</span> <span dir=\"rtl\">ק׳ של ארזין</span> cedar planks; Pesik. B’shall. p. 84ᵃ <span dir=\"rtl\">ק׳ של ארז</span>; <span class=\"citation\">Yalk. Ex. 225</span> <a href=\"#\" data-headword=\"קְצָצִים\">קְצָצִים</a> (only).—Pl. <span dir=\"rtl\">קְצָצוֹת</span>. <span class=\"citation\">Y. Keth. VIII, 32ᵇ</span> bot. <span dir=\"rtl\">אילנות וק׳ וכ׳</span> if heirs seize trees or timber, old or young, it is taken away from them.</div><div class=\"sense\"><b>—2)</b> <i>cutting off, severing family connections; ḳ’tsatsah, a ceremony attending the sale of an heirloom to an outsider, and the marriage of a man beneath his social rank</i>. <span class=\"citation\">Y. Kidd. I, 60ᶜ</span> <span dir=\"rtl\">הזרו להיות קונים בק׳</span> then again the custom arose to take possession of an estate by <i>ḳ’tsatsah</i> (instead of taking off the shoe); <span dir=\"rtl\">מהו בק׳ … נקצץ פלוני מאחוזתו</span> what is <i>ḳ</i>.? When a man sold his paternal estate, his relatives brought casks filled with parched ears and nuts, and broke them in the presence of children: the latter picked them up, and they said, this man has been cut off &amp;c.; and when he bought it back, they did the same and called out, this man has returned to his heirloom &amp;c.; <span class=\"citation\">Ruth R. to IV, 7</span>; <span class=\"citation\">Y. Keth. II, 26ᵈ</span> bot. <a href=\"#\" data-headword=\"קְצִיצָה\">קְצִיצָה</a>; <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שאכלנו בקְצִיצַת פלוני</span> adults are admitted to testify, ‘we (as children) ate (grain and nuts) at that man’s <i>ḳ</i>.’; Bab. <span class=\"citation\">Keth. 28ᵇ</span> <span dir=\"rtl\">בקצצה של וכ׳</span> at the <i>ḳ</i>. when that man’s daughter was married; <span dir=\"rtl\">וזו היא הק׳ וכ׳</span> and this is the <i>ḳ</i>. to which a child can testify (when grown up); Tosef. ib. III, 3.</div>","alt":[]},"27278":{"h":"קְצָצִים","r":"S01840","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְצָצָה\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>cut plants, timber</i>, &amp;c. <span class=\"citation\">Yalk. Ex. 225</span>, v. <a href=\"#\" data-headword=\"קְצָצָה\">preced.</a> <span class=\"citation\">Tosef. B. Kam. III, 2</span> if a man cut his neighbor’s plants, the latter has no right to say, <span dir=\"rtl\">טול את הק׳ וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>capsules, pods</i>, v. <a href=\"#\" data-headword=\"קְצִיצִים\">קְצִיצִים</a>.</div>","alt":["קְצָצִין"]},"27279":{"h":"קְצָצִין","r":"S01841","html":"<div class=\"sense\">, <i>capsules, pods</i>. <span class=\"citation\">Y. Kil. I, 27ᵃ</span> <span dir=\"rtl\">קְצָצוֹי</span>, v. <a href=\"#\" data-headword=\"חֲרוּבָא ²\"><span dir=\"rtl\">חֲרוּבָא</span> I</a>.</div>","alt":[]},"27280":{"h":"רְחָבָה","r":"T00479","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  fem. of <a href=\"#\" data-headword=\"רָחָב I\">רָחָב</a>.</div><div class=\"sense\"><b>—2)</b> <i>open place, market</i>. <span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">ברכת ר׳</span>, v. <a href=\"#\" data-headword=\"בְּרָכָה\">בְּרָכָה</a>. <span class=\"citation\">Y. Ned. V, end, 39ᵇ</span>; <span class=\"citation\">Tosef. ib. II, 9</span> <span dir=\"rtl\">ר׳ שדרך הרבים מפסקתה</span> a market which is crossed by a public (caravan) road.</div>","alt":[]},"27281":{"h":"רְחוֹב","r":"T00480","html":"<div class=\"sense\"> m. (b. h.) <a href=\"#\" data-headword=\"רְחָבָה\">same</a>. <span class=\"citation\">Taan. II, 1</span> (<span class=\"citation\">15ᵃ</span>) <span dir=\"rtl\">מוציאין … לרְחוֹבָהּ של עיר</span> (not <span dir=\"rtl\">לרחוב</span>) (at public fasts) they carry the ark out to the open place of the town. <span class=\"citation\">Meg. III, 1</span> (<span class=\"citation\">25ᵇ</span>) <span dir=\"rtl\">בני … רחובה וכ׳</span> if the citizens sold the open place of a town (which is used for public prayer meetings), they may buy a synagogue with the proceeds. Ib. <span dir=\"rtl\">בה&quot;כ … את הר׳</span> if they sold a synagogue, they dare not buy an open place; a. e.</div>","alt":[]},"27282":{"h":"רַחֲוָותָא","r":"T00481","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִחְיָא\">רִחְיָא</a></div>","alt":[]},"27283":{"h":"רחוינית","r":"T00482","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. V, 3</span>, v. <a href=\"#\" data-headword=\"*דַּחֲוָונוֹת\">דַּחֲוָונוֹת</a></div>","alt":[]},"27284":{"h":"רַחוּם","r":"T00483","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>merciful</i>. <span class=\"citation\">Sabb. 133ᵇ</span> <span dir=\"rtl\">מה הוא חנון ור׳ וכ׳</span> as He is gracious and merciful, so be thou &amp;c.; a. e.</div>","alt":[]},"27285":{"h":"רְחוּמִי","r":"T00484","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>R’ḥumi</i>, an Amora. <span class=\"citation\">Keth. 62ᵇ</span>. <span class=\"citation\">Pes. 39ᵃ</span>. <span class=\"citation\">Naz. 13ᵃ</span> <span dir=\"rtl\">בן ר׳</span>; a. e.</div>","alt":[]},"27286":{"h":"רְחוּמְתָא","r":"T00485","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִחִים II\">רְחִימָא</a></div>","alt":[]},"27287":{"h":"רחוץ","r":"T00486","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. IX, 11ᵈ</span>, v. <a href=\"#\" data-headword=\"רָהוֹן\">רָהוֹן</a></div>","alt":[]},"27288":{"h":"רִחוּק","r":"T00487","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיחוּק\">רִיחוּק</a>, <a href=\"#\" data-headword=\"רִיחוֹק\"><a href=\"#\" data-headword=\"רִיחוֹק\">רִיחוֹק</a>.</a></div>","alt":["רִחוֹק"]},"27289":{"h":"רָחוֹק","r":"T00488","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>distant, removed</i>. <span class=\"citation\">Snh. VI, 2</span> <span dir=\"rtl\">היה ר׳ מבית וכ׳</span> when the culprit arrived at a distance of about ten cubits from the place of execution. <span class=\"citation\">Ib. 3</span>. <span class=\"citation\">Pes. IX, 1</span> <span dir=\"rtl\">מי … או בדרך ר׳</span> he who (on the fourteenth day of Nisan) was unclean or on a distant journey (<span class=\"citation\">Num. IX, 10</span>). Ib. 2 <span dir=\"rtl\">לפיכך … מפני שרחוקה ודאי וכ׳</span> (Bab. ed. 93ᵇ <span dir=\"rtl\">רחוק</span>) therefore is the Hé (of <span dir=\"rtl\">רחוקה</span>, Num. l. c.) dotted, not that it necessarily be distant (that he be really far away), but that he be outside of the Temple court (and unable to enter in time); Y. ib. 36ᵈ <span dir=\"rtl\">ה&quot;א … איש ר׳ ואין דרך ר׳</span> the Hé is dotted to intimate that the man is at a distance <span dir=\"rtl\">(רחוק</span>), not that the way be far; a. fr.—<span dir=\"rtl\">שמועה ר׳</span>, v. <a href=\"#\" data-headword=\"שְׁמוּעָה\">שְׁמוּעָה</a>.—Pl. <span dir=\"rtl\">רְחוֹקִים</span>, <span dir=\"rtl\">רְחוֹקִין</span>; <span dir=\"rtl\">רְחוֹקוֹת</span>. Sabb. 182ᵃ <span dir=\"rtl\">קרובים נעשו ר׳</span>; <span class=\"citation\">Lev. R. s. 18</span>, v. <a href=\"#\" data-headword=\"קָרוֹב I\">קָרוֹב</a>. <span class=\"citation\">Sifré Num. 131</span>, v. <a href=\"#\" data-headword=\"סָמַךְ\">סָמַךְ</a>; a. fr.</div>","alt":["רְחוֹקָה"]},"27290":{"h":"רְחוּקָה","r":"T00489","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַק\">רְחַק</a>) <i>alienation, severing a connection</i>. <span class=\"citation\">Kidd. 50ᵃ</span>, v. <a href=\"#\" data-headword=\"קוֹרְבָא\">קוֹרְבָא</a>.</div>","alt":[]},"27291":{"h":"רִחוּשׁ","r":"T00490","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיחוּשׁ\">רִיחוּשׁ</a></div>","alt":[]},"27292":{"h":"רָחוֹשׁ","r":"T00491","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַשׁ\">רָחַשׁ</a>) <i>an ornament in the shape of a reptile</i>, used as a gem or amulet. <span class=\"citation\">Tosef. Kel. B. Mets. I, 9</span> a ‘reptile’ (scarabee &amp;c.) which is broken (out of its setting), or whose point is broken off, is not susceptible of uncleanness; but if the hooks remain on it on both sides &amp;c. <span class=\"citation\">Tosef. Ab. Zar. V</span> (<span class=\"citation\">VI), 2</span> <span dir=\"rtl\">הר׳ העשוי כמין הדרקון וכ׳</span> a <i>raḥosh</i> which is made like a dragon (intimating an idolatrous emblem, v. <a href=\"#\" data-headword=\"צִיץ\">צִיץ</a>) is forbidden, but if a dragon is suspended from it, you may throw the dragon away &amp;c.; Y. ib. III, 42ᵈ top [read:] <span dir=\"rtl\">המוצא ר׳ עשוי כמין דרקון אסור וכ׳</span>.</div>","alt":[]},"27293":{"h":"רְחוּשִׁין","r":"T00492","html":"<div class=\"sense\">, constr. <span dir=\"rtl\">רְחוּשֵׁי</span>, v. <a href=\"#\" data-headword=\"רַחֲשׁוּשׁ\">רַחֲשׁוּשׁ</a></div>","alt":[]},"27294":{"h":"רחזיונות","r":"T00493","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*דַּחֲוָונוֹת\">דַּחֲוָונוֹת</a></div>","alt":[]},"27295":{"h":"רִחְיָא","r":"T00494","html":"<div class=\"sense\"> ch. = <a href=\"#\" data-headword=\"רֵחַיִים\">next w.</a> <span class=\"citation\">Targ. O. Ex. XI, 5</span> (Y. <span dir=\"rtl\">חַיָּא …</span>). <span class=\"citation\">Targ. O. Deut. XXIV, 6</span> (Y. <span dir=\"rtl\">חַיָּא …</span>). <span class=\"citation\">Targ. O. Num. XI, 8</span> (ed. Vien. <a href=\"#\" data-headword=\"רִחְיָא\">רֵחַיָּא</a>; Y. I <a href=\"#\" data-headword=\"רֵיחוּתָא\">רִיחוּתָא</a>; II <a href=\"#\" data-headword=\"רַחֲוָותָא\">רַחֲוָותָא</a>).—<span class=\"citation\">M. Kat. 10ᵇ</span>, <span dir=\"rtl\">חמרא דרי׳</span> the ass employed in the mill; <span dir=\"rtl\">לאוקומי ר׳</span> to put up the millstones; <span dir=\"rtl\">אמת ר׳</span> the pole of the mill. <span class=\"citation\">Y. Kidd. I, 61ᵇ</span>; <span class=\"citation\">Y. Peah I, 15ᶜ</span> bot. <a href=\"#\" data-headword=\"רֵיחוּתָא\">רֵיחַיָיא</a>; a. e.</div>","alt":["רִיחְ׳","רֵחַיָּא","רֵי׳"]},"27296":{"h":"רֵחַיִים","r":"T00495","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (sing.) (b. h.; <span dir=\"rtl\">רחה</span> <i>to rub</i>) <i>millstone, mill</i>. <span class=\"citation\">B. Mets. IX, 13</span> <span dir=\"rtl\">החובל את הר׳ עובר וכ׳</span> he who takes a mill to pledge violates a prohibitory law, and is guilty of taking two vessels &amp;c.; <span dir=\"rtl\">ולא ר׳ ורכב בלבד וכ׳</span> and not only mill and upper millstone are meant (<span class=\"citation\">Deut. XXIV, 6</span>), but anything with which a living is made &amp;c. <span class=\"citation\">Men. X, 4</span>, a. e., v. <a href=\"#\" data-headword=\"גָּרוֹסָה\">גָּרוֹסָה</a>. <span class=\"citation\">Bets. II, 9</span>, v. <a href=\"#\" data-headword=\"פִּלְפָּל\">פִּלְפָּל</a> <span class=\"citation\">Tosef. B. Bath. III, 2</span>; Y. ib. IV, 14ᶜ bot. <span dir=\"rtl\">ר׳ התחתונה</span> the lower (stationary) millstone (for crushing olives); <span dir=\"rtl\">ר׳ העליונה</span> the upper millstone. Ohol. VIII, 3 <span dir=\"rtl\">הר׳ של אדם</span> a mill worked by man, handmill. <span class=\"citation\">Tosef. ib. IX, 2</span> <span dir=\"rtl\">נדחק בר׳ שהגוי וכ׳</span> if a person is pressed to work at a mill where there is a gentile or a menstruant; <span dir=\"rtl\">איזו היא הר׳ כל שעוקרין אותה וכ׳</span> (not <span dir=\"rtl\">כל שאין עוקרין</span>, v. R. S. to Ohol. VIII, 3) what kind of a mill is meant? Such as can be lifted or pushed from its place; <span class=\"citation\">Tosef. Toh. VI, 11</span>; a. fr.—<span class=\"citation\">Kidd. 29ᵇ</span> <span dir=\"rtl\">ר׳ בצוארו</span> he has a millstone on his neck (has wife and children to support).</div>","alt":["רִחַיִם","רֵי׳"]},"27297":{"h":"רְחֵיל־","r":"T00496","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָחֵל II\"><span dir=\"rtl\">רָחֵל</span> II</a>, <a href=\"#\" data-headword=\"רְחֵלָא\">רְחֵלָא</a>.</div>","alt":["רְחֵילָא"]},"27298":{"h":"רֵחַיִם","r":"T00497","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵחַיִים\">רֵחַיִים</a></div>","alt":[]},"27299":{"h":"רְחֵים","r":"T00498","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְחֵם\">רְחֵם</a></div>","alt":[]},"27300":{"h":"רְחִים I","r":"T00499","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְחֵים\">preced.</a>) <i>love</i>. <span class=\"citation\">Targ. Cant. VII, 7</span>.—V. <a href=\"#\" data-headword=\"רְחִימְתָּא\">רְחִימְתָּא</a>.</div>","alt":[]},"27301":{"h":"רִחִים II","r":"T00500","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְחִים I\">preced.</a>) <i>beloved, friend; lovable</i>. <span class=\"citation\">Targ. Jer. IX, 3</span> (ed. Wil. <a href=\"#\" data-headword=\"רְחֵים\">רְחֵים</a>). <span class=\"citation\">Ib. XXXI, 19</span> (<span class=\"citation\">20</span>) <a href=\"#\" data-headword=\"רְחִים I\">רָחֵים</a>. Targ. O. a. Y. II <span class=\"citation\">Deut. XXXIII, 12</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"רְתִימִין\">רְחִימִין</a>. <span class=\"citation\">Targ. Hos. I, 6</span>; <span class=\"citation\">8</span>. <span class=\"citation\">Targ. II Sam. I, 23</span>; a. e.—<span class=\"citation\">Gen. R. s. 65</span> [read:] <span dir=\"rtl\">כמה ר׳ הוו ליה וכ׳</span> so many friends had he, and yet he said, (I appoint as my son’s guardian) the scribe; <span class=\"citation\">Yalk. ib. 115</span> <a href=\"#\" data-headword=\"רַחֲמִין\">רַחֲמִין</a>.—<i>Fem.</i> <a href=\"#\" data-headword=\"רִחִים II\">רְחִימָא</a>, <a href=\"#\" data-headword=\"רְחִימְתָּא\">רְחִימְתָּא</a>. <span class=\"citation\">Targ. Y. Ex. XI, 2</span>. <span class=\"citation\">Targ. Hos. III, 1</span>. <span class=\"citation\">Targ. O. Deut. XXI, 16</span> <a href=\"#\" data-headword=\"רְחוּמְתָא\">רְחוּמְתָא</a> ed. Berl. (ed. Vien. <a href=\"#\" data-headword=\"רַחֲמָא ²\">רְחֶמְתָּא</a>); Y. <a href=\"#\" data-headword=\"רְחִימְתָּא\">רְחִימְתָּא</a>, <a href=\"#\" data-headword=\"רְחוּמְתָא\">רְחוּמְתָא</a>, <span dir=\"rtl\">רְחִמְ׳</span>.</div>","alt":["רְחִימָא"]},"27302":{"h":"רְחִימוּתָא","r":"T00501","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַחֲמוּ\">רַחֲמוּ</a></div>","alt":[]},"27303":{"h":"רְחִימְתָּא","r":"T00502","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  v. <a href=\"#\" data-headword=\"רִחִים II\"><span dir=\"rtl\">רְחִים</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>love</i>. <span class=\"citation\">Targ. Koh. IX, 1</span> (ed. Vien. <span dir=\"rtl\">רְחִמְ׳</span>). <span class=\"citation\">Targ. Hos. III, 1</span> <a href=\"#\" data-headword=\"רִחִים II\">רְחִימַת</a> constr. a. fr.—<span class=\"citation\">Snh. 7ᵃ</span> <span dir=\"rtl\">רְחִימְתִּין</span> our love, v. <a href=\"#\" data-headword=\"סַפְסֵירָא\">סַפְסֵירָא</a>.</div>","alt":["רְחִימְתָא"]},"27304":{"h":"רחיפין","r":"T00503","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Shebi. VII, 15</span>, v. <a href=\"#\" data-headword=\"טְפִיחַ II\"><span dir=\"rtl\">טְפִיחַ</span> II</a></div>","alt":[]},"27305":{"h":"רִחֵיץ","r":"T00504","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְחֵץ\">רְחֵץ</a></div>","alt":["רָחֵיץ"]},"27306":{"h":"רְחִיצָה","r":"T00505","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַץ\">רָחַץ</a>) <i>washing, bathing</i>. <span class=\"citation\">Yoma VIII, 1</span>. <span class=\"citation\">Ḥall. I, 9</span> <span dir=\"rtl\">רְחִיצַת ידים</span> washing the hands. <span class=\"citation\">Y. Naz. VII, end, 56ᵈ</span> <span dir=\"rtl\">על רחיצת גופו</span> for omitting to bathe his body. <span class=\"citation\">Num. R. s. 14</span><sup>1</sup> <span dir=\"rtl\">שרפאתיו ע&quot;י רחיצת הירדן</span> whom I cured by bathing in the Jordan. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שהסרתי … ע&quot;י רחיצת וכ׳</span> whom I saved from drowning through the bathing of Pharaoh’s daughter. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">גחזי שלקה ע&quot;י ר׳</span> Gehazi who was punished on the occasion of (Naaman’s) bathing; a. fr.</div>","alt":[]},"27307":{"h":"רְחֵיק","r":"T00506","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָחַק\">רְחַק</a></div>","alt":[]},"27308":{"h":"רָחִיק I","r":"T00507","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְחֵיק\">preced.</a>) <i>distance</i>. <span class=\"citation\">Targ. Ex. II, 4</span>. <span class=\"citation\">Targ. Ps. X, 1</span>. <span class=\"citation\">Targ. Prov. XXXI, 14</span> (Ms. <a href=\"#\" data-headword=\"רוֹחַק\">רוֹחַק</a>); a. fr.</div>","alt":[]},"27309":{"h":"רָחִיק II","r":"T00508","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחִיק I\">preced.</a>) <i>far, distant, removed</i>. <span class=\"citation\">Targ. Deut. XXIX, 21</span>. <span class=\"citation\">Targ. Jer. XII, 2</span>. <span class=\"citation\">Targ. Prov. XXV, 25</span>; a. fr.—<span class=\"citation\">Succ. 52ᵃ</span>; <span class=\"citation\">Yalk. Joel 535</span>, v. <a href=\"#\" data-headword=\"צַוְותָּא\">צַוְותָּא</a>. <span class=\"citation\">Y. Shebi. IX, 38ᵈ</span> bot. <span dir=\"rtl\">לארעא דר׳</span> to a distant land; a. e.—Pl. <span dir=\"rtl\">רְחִיקִין</span>; <span dir=\"rtl\">רְחִיקָן</span>. <span class=\"citation\">Targ. Josh. IX, 22</span>. <span class=\"citation\">Targ. Jud. XVIII, 7</span>; a. fr.—<span class=\"citation\">Y. Ned. XI, end, 42ᵈ</span> (expl. <span dir=\"rtl\">שמים ביני לבינך</span> Mish. <span class=\"citation\">Ned. XI, 12</span>) [read:] <span dir=\"rtl\">כמא דשמיא ר׳ … כן האי אתתא רחיקא וכ׳</span> as the heavens are remote from the earth, so is this woman (I) from this man (I cannot live with him); a. e.</div>","alt":["רַחִיקָא","רְ׳","רְחִיקְתָּא"]},"27310":{"h":"רְחֵישׁ","r":"T00509","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְחַשׁ\">רְחַשׁ</a>, <a href=\"#\" data-headword=\"רְחֵשׁ\"><a href=\"#\" data-headword=\"רְחֵשׁ\">רְחֵשׁ</a>.</a></div>","alt":["רְחִישׁ"]},"27311":{"h":"רְחִישָׁה","r":"T00510","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַשׁ\">רָחַשׁ</a>) <i>movement</i>. <span class=\"citation\">Cant. R. to IV, 4</span> (ref. to <span class=\"citation\">Cant. IV, 3</span>) <span dir=\"rtl\">רְחִישַׁת פיך חביבה וכ׳</span> the moving of thy mouth (in prayer) is as pleasing to me as the crimson thread (the strap in the Temple on the Day of Atonement, v. <span class=\"citation\">Yoma VI, 8</span>).—[<span class=\"citation\">Gen. R. s. 12</span>, beg. <span dir=\"rtl\">רחישת קנים</span> Ar., v. <a href=\"#\" data-headword=\"חֲרִישָׁה III\"><span dir=\"rtl\">חֲרִישָׁה</span> III</a>.]</div>","alt":[]},"27312":{"h":"רחישותא","r":"T00511","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Gen. XXII, 13</span> some ed., v. <a href=\"#\" data-headword=\"חֲרִישׁוּתָא\">חֲרִישׁוּתָא</a></div>","alt":[]},"27313":{"h":"רְחִישְׁתָּא","r":"T00512","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְחַשׁ\">רְחַשׁ</a>) <i>sense, sensation</i>. <span class=\"citation\">Targ. Job XX, 2</span> ed. Lag., v. <a href=\"#\" data-headword=\"חִישׁוּתָא\">חִישׁוּתָא</a>.</div>","alt":[]},"27314":{"h":"רָחֵל I","r":"T00513","html":"<div class=\"sense\"> f. (b. h.) pr. n. f. <i>Rachel</i>, </div><div class=\"sense\"><b>1)</b>  wife of Jacob. <span class=\"citation\">Gen. R. s. 71</span> (play on <span dir=\"rtl\">עקרה</span>, <span class=\"citation\">Gen. XXIX, 31</span>) <span dir=\"rtl\">ר׳ תהיה עיקרו וכ׳</span> Rachel shall be the chief person of the household; ib. <span dir=\"rtl\">לפי שכל הדברים תלויין בר׳ וכ׳</span> because all depends on R., therefore is Israel called by her name; <span class=\"citation\">Ruth R. to IV, 11</span>, v. <a href=\"#\" data-headword=\"עִיקָּר\">עִיקָּר</a>; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  R. Akiba’s wife. <span class=\"citation\">Ab. d’R. N. ch. VI</span>.—3) R., mother of Rab Mari. <span class=\"citation\">Sabb. 154ᵃ</span>; a. fr.</div>","alt":[]},"27315":{"h":"רָחֵל II","r":"T00514","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>ewe, sheep</i>. <span class=\"citation\">Bekh. III, 1</span> <span dir=\"rtl\">ר׳ בת שתים וכ׳</span> if an ewe gives birth in her second year of age, the issue belongs to the priest with certainty. <span class=\"citation\">Ib. 20ᵃ</span>. <span class=\"citation\">Tosef. Ḥull. X, 1</span> <span dir=\"rtl\">כלאיים מן הר׳ וכ׳</span> a hybrid of an ewe and a kid is subject to the law concerning the first of the fleece (<span class=\"citation\">Deut. XVIII, 4</span>); a. fr.—Pl. <span dir=\"rtl\">רְחֵלוֹת</span>, <span dir=\"rtl\">רְחֵלִים</span>, <span dir=\"rtl\">רְחֵלִין</span>, <a href=\"#\" data-headword=\"רְחֵלָא\">רְחֵי׳</a>. Ib. 4 <span dir=\"rtl\">השוטף רְחֵלָיו</span> if one washes his lambs (and wool comes out). Ib.; <span class=\"citation\">Ḥull. XI, 2</span> <span dir=\"rtl\">חמש ר׳ גוזזות וכ׳</span> five lambs yielding wool of the weight of &amp;c. <span class=\"citation\">Ib. 137ᵇ</span> <span dir=\"rtl\">דקא מתני ליה לבריה רחלים</span> taught his son (the Mishnah l. c.) using <i>r’ḥelim</i> (according to Biblical usage); <span dir=\"rtl\">א&quot;ל אתנייה רחלות</span> said he to him, teach him <i>r’ḥeloth</i> (in accordance with later usage). <span class=\"citation\">Bekh. V, 3</span> <span dir=\"rtl\">זכר של ר׳</span>, v. <a href=\"#\" data-headword=\"זָכָר\">זָכָר</a>. <span class=\"citation\">Sabb. V, 2</span>; <span class=\"citation\">4</span>; a. fr.</div>","alt":[]},"27316":{"h":"רְחֵלָא","r":"T00515","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. LIII, 7</span>. <span class=\"citation\">Targ. Y. Lev. XXII, 8</span>; a. e.—Y. Ber. V, 9ᶜ top; v. <a href=\"#\" data-headword=\"רַחֲמָן ²\">רַחֲמָנָא</a>. <span class=\"citation\">Keth. 63ᵃ</span> (prov., with ref. to Akiba’s daughter, betrothed to Ben ʿAzzai for many years, and alluding to Rachel, the name of Akiba’s wife, v. <a href=\"#\" data-headword=\"רָחֵל I\"><span dir=\"rtl\">רָחֵל</span> I</a>) <span dir=\"rtl\">ר׳ בתר ר׳ אזלא וכ׳</span> ewe follows ewe, as the mother acts, so does the daughter; a. e.—Pl. <span dir=\"rtl\">רְחֵלִין</span>, <span dir=\"rtl\">רְחֵלֵי</span>, <a href=\"#\" data-headword=\"רְחֵלָא\">רְחֵי׳</a>, <span dir=\"rtl\">רַחְל׳</span>. <span class=\"citation\">Targ. Gen. XXXII, 15</span> (<span class=\"citation\">14</span>) (O. ed. Berl. <span dir=\"rtl\">רַחְלי</span>). <span class=\"citation\">Targ. Deut. XIV, 4</span> (O. ed. Berl. <span dir=\"rtl\">רַחְלִין</span>); a. e.</div>","alt":["רְחֵי׳","רַחְלָא"]},"27317":{"h":"רָחַם","r":"T00516","html":"<div class=\"sense\"> (b. h.) <i>to love</i>.</div><div class=\"sense\"><b>Pi. רִיחֵם</b> <div class=\"sense\"><b>1)</b>  (with (with <span dir=\"rtl\">על</span>) <i>to have compassion on, pity; to befriend</i>. <span class=\"citation\">Ber. 33ᵃ</span> <span dir=\"rtl\">כל מי … אסור לרַחֵם עליו</span> you must not befriend him who has no sense (ref. to <span class=\"citation\">Is. XXVII, 11</span>). <span class=\"citation\">Sabb. 151ᵇ</span> <span dir=\"rtl\">כל המְרַחֵם … מְרַחֲמִין עליו וכ׳</span> he who shows mercy to creatures (men), will be shown mercy in heaven (ref. to <span class=\"citation\">Deut. XIII, 18</span>), v. <a href=\"#\" data-headword=\"רַחֲמָן\">רַחֲמָן</a>. <span class=\"citation\">Ab. Zar. 18ᵃ</span> <span dir=\"rtl\">מן השמים יְרַחֵמוּ</span> heaven will have mercy (protect me); <span class=\"citation\">Nidd. 45ᵃ</span>. <span class=\"citation\">Sot. VIII, 1</span> <span dir=\"rtl\">יְרַחֲמוּ עליכם</span> they will have mercy on you (spare your lives); a. fr.—Trnsf. <i>to give suck to a strange animal</i>. <span class=\"citation\">Bekh. 24ᵃ</span> <span dir=\"rtl\">אינה מְרַחֶמֶת אלא וכ׳</span> no dam gives suck to a stranger, unless she has had a child of her own. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מרחמת אע&quot;פ וכ׳</span> she may give suck, even if she has never given birth.</div><div class=\"sense\"><b>—2)</b> <i>to stimulate the maternal instinct</i> (v. <a href=\"#\" data-headword=\"רֶחֶם\">רֶחֶם</a>) of an animal after confinement by inserting a lump of salt into the womb. <span class=\"citation\">Tosef. Sabb. XV</span> (<span class=\"citation\">XVI), 2</span> <span dir=\"rtl\">מְרַחֲמִין היינו בהמה טהורה ביו&quot;ט</span> ed. Zuck. (Var. <span dir=\"rtl\">על בהמה</span>) we (in my father’s house) used to stimulate &amp;c. on a Holy Day; <span class=\"citation\">Sabb. 128ᵇ</span> <span dir=\"rtl\">על בהמה</span>; Y. ib. XVIII, end, 16ᶜ <span dir=\"rtl\">על הבהמה</span>.</div></div><div class=\"sense\"><b>Hithpa. הִתְרַחֵם</b> <div class=\"sense\"><i>to have pity</i>. <span class=\"citation\">Num. R. s. 9</span><sup>24</sup> <span dir=\"rtl\">אם נופלים אנו … מִתְרַחֵם עלינו אין אנו מִתְרַחֲמִים עליו</span> if we fall into David’s hands, he will have pity on us, but if David fall into our hands, we shall have no pity on him; Y. Sot. I, 17ᵇ bot. <span dir=\"rtl\">הוא מרחם … אנו מרחמין</span>).</div></div>","alt":[]},"27318":{"h":"רְחֵם","r":"T00517","html":"<div class=\"sense\"><b>1)</b> <i>to love</i> (h. <a href=\"#\" data-headword=\"אָהַב\">אהב</a>). <span class=\"citation\">Targ. Gen. XXII, 2</span>. <span class=\"citation\">Ib. XXXVII, 3</span>. <span class=\"citation\">Targ. O. Deut. VI, 5</span>. <span class=\"citation\">Targ. Prov. IV, 6</span> (ed. Wil. <span dir=\"rtl\">רָחֲמָהּ</span> <i>Pa.</i>); a. fr.—<span class=\"citation\">Midr. Till. to Ps. XVIII, 2</span> (expl. <span dir=\"rtl\">ארחמך</span>, ib.) <span dir=\"rtl\">רַחֲמִית יתך וכ׳</span> I love thee (ref. to Targ. Deut. l. c.); Yalk. ib. 671 <span dir=\"rtl\">רַחְמָאִי יתך</span>. <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> bot. (R. Akiba speaking to his pupils before his death) <span dir=\"rtl\">רְחִמְתֵּיה בכל לבי ורחמתיה וכ׳</span> I loved him with all my heart, and I loved him with all I possessed, but how to love him with all my soul (life) I could not understand, and now &amp;c. <span class=\"citation\">Sabb. 23ᵇ</span> <span dir=\"rtl\">דרָחֵים רבנן וכ׳</span> he who loves scholars shall have children that are scholars. Y. ib. XIV, 14ᵈ bot. <span dir=\"rtl\">חד בר נש ר׳ אתתא וכ׳</span> a man fell in love with a woman … and grew dangerously ill; <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> bot. <span class=\"citation\">Lev. R. s. 25</span> שמעית דמלכא רַחְמָא וכ׳ I heard that the king loves figs; <span class=\"citation\">Koh. R. to II, 20</span> <a href=\"#\" data-headword=\"רְחִים I\">רחים</a>; <span class=\"citation\">ib.</span> <a href=\"#\" data-headword=\"רִחִים II\">רחימא</a>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">רחמיה</span> (corr. acc.). <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> bot. <span dir=\"rtl\">דהוות רַחְמָא מצוותא</span> who loved to be charitable; <span class=\"citation\">Y. Ter. VIII, 45ᶜ</span> bot. <span dir=\"rtl\">הוו רחמנא וכ׳</span> (corr. acc.). <span class=\"citation\">Keth. 105ᵇ</span> <span dir=\"rtl\">אם מִרְחַם כולהו רַחְמוּ לי וכ׳</span> if there is love (among them), they all love me &amp;c., v. <a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a>. <span class=\"citation\">Snh. 89ᵇ</span> תרוייהו רַחֲמִינִי להו I love both of them (Isaac und Ishmael); a. fr.</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">על</span>) <i>to have compassion on, pity</i>. <span class=\"citation\">Targ. Ps. CIII, 13</span>. <span class=\"citation\">Targ. Prov. XXVIII, 13</span>; a. fr.</div><div class=\"sense\"><b>Pa. רַחֵם</b> <div class=\"sense\"><b>1)</b> <i>to love</i>. <span class=\"citation\">Targ. Gen. XXIX, 32</span> (O. ed. Vien. <i>Pe.</i>). <span class=\"citation\">Targ. Y. Deut. VI, 5</span>; a. e.—Keth. l. c. <span dir=\"rtl\">האי … דמְרַחְמִין ליה וכ׳</span> if the people of a place love a teacher, it is not because he is a good man, but because he does not reprove them on heavenly matters (for neglect of religious duties). Y. Ter. VIII, 45ᶜ <span dir=\"rtl\">אילולי דאתון מרחמין שמועתא וכ׳</span> but for your loving traditions (you would not ask such questions); is it not a Mishnah?; Y. Ab. Zar. II, 41ᵃ <a href=\"#\" data-headword=\"רַחֲמִין\">רחמין</a>; a. e.—Trnsf. <i>to give suck</i> (v. <a href=\"#\" data-headword=\"רָחַם\">preced.</a>). <span class=\"citation\">Bekh. 24ᵃ</span> or shall we say, <span dir=\"rtl\">דידה מְרַחְמָא דלא וכ׳</span> a dam gives suck to her own young, but not to a stranger. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דילמא רַחוּמֵי רחים</span> perhaps this is a case when one gives suck to a stranger (although having a child of her own); v. <a href=\"#\" data-headword=\"שְׁבַק\">שְׁבַק</a>.</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">על</span>) <i>to compassionate, pity</i>. <span class=\"citation\">Targ. Jer. XXXI, 19</span>. <span class=\"citation\">Targ. O. Num. VI, 25</span> <span dir=\"rtl\">וירחם עלך</span> ed. Lisb. (oth. ed. <span dir=\"rtl\">ויר׳ יתך</span>; in ed. Berl. untranslated). <span class=\"citation\">Targ. Deut. VII, 2</span>; a. fr.—<span class=\"citation\">Macc. 23ᵇ</span> <span dir=\"rtl\">מדהא מְרַחַמְתָּא והא לא מרחמתא</span> (Solomon found out which was the true mother of the living child,) because the one showed compassion, and the other did not. Y. Taan. II, 65ᵇ <span dir=\"rtl\">אמרין … מִתְרַחֵם עלינן לינן מְרַחְמִין וכ׳</span> the men of Niniveh said, if thou wilt have no mercy on us, we shall have no mercy on them (the beasts and the children); a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִתְרחֵם</b> </div><div class=\"sense\"><b>Ithpe. אִתְרְחֵם</b> <div class=\"sense\"><b>1)</b> <i>to be loved, beloved</i>. <span class=\"citation\">Targ. Prov. XV, 9</span>.</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">על</span>) <i>to be pitied, be shown mercy</i>. <span class=\"citation\">Targ. Y. Ex. XXXIII, 19</span>. <span class=\"citation\">Targ. Gen. XLIII, 29</span>. <span class=\"citation\">Targ. Hos. XIV, 4</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to be moved to mercy, have pity</i>. <span class=\"citation\">Targ. Jer. XXXI, 18</span> (<span class=\"citation\">19</span>) <span dir=\"rtl\">מתרחם</span> ed. Lag. (oth. ed. <span dir=\"rtl\">מתנחם</span>; h. text <span dir=\"rtl\">נחמתי</span>).—Y. Taan. l. c., v. supra; a. e.</div></div>","alt":["רְחֵים"]},"27319":{"h":"רָחָם","r":"T00518","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>raḥam</i>, name of an unclean bird, <i>giereagle</i> or <i>vulture</i>. <span class=\"citation\">Ḥull. 63ᵃ</span> ר׳ זו שרקרק ולמה … ר׳ כיון שבא ר׳ וכ׳ <i>raḥam</i> (<span class=\"citation\">Lev. XI, 18</span>) is the <i>sh’raḳraḳ</i>, and why is it called <i>raḥam</i> (love)? Because when the <i>r.</i> comes, mercy comes upon the world (it betokens rain).</div>","alt":[]},"27320":{"h":"רָחֵם","r":"T00519","html":"<div class=\"sense\"><i>friend</i>, v. <span dir=\"rtl\">רַחֲמָא III</span>.</div>","alt":[]},"27321":{"h":"רֶחֶם","r":"T00520","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>orifice of the matrix; womb</i>. <span class=\"citation\">B. Bath. 16ᵇ</span>, a. e. <span dir=\"rtl\">רַחְמָהּ צר</span>, v. <a href=\"#\" data-headword=\"אַיָּלָה\">אַיָּלָה</a>. <span class=\"citation\">Num. R. s. 10</span><sup>5</sup> <span dir=\"rtl\">קבלה הר׳ וכ׳</span> (fem.) the womb conceived &amp;c. <span class=\"citation\">Ḥull. 70ᵃ</span> <span dir=\"rtl\">כותלי בית הר׳</span> the sides of the womb; a. fr.—<span class=\"citation\">Gen. R. s. 37</span>; <span class=\"citation\">Yalk. Ps. 869</span> (ref. to <span class=\"citation\">Ps. CX, 3</span>) <span dir=\"rtl\">מרַחְמוֹ של אולם שחרתיך לי</span> from the womb of the world (sunrise, east) did I choose thee for me.—Pl. <a href=\"#\" data-headword=\"רַחֲמִים\">רְחָמִים</a>. Ḥull. l. c. <span class=\"citation\">Ber. 32ᵇ</span> <span dir=\"rtl\">פטרי ר׳</span> the firstborn; a. e.</div>","alt":[]},"27322":{"h":"רַחֲמָא","r":"T00521","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job III, 10</span>. <span class=\"citation\">Ib. XXXVIII, 8</span>.</div>","alt":["רַחְ׳ I"]},"27323":{"h":"רַחֲמָא ²","r":"T00522","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַם\">רְחַם</a>) <i>love</i>. <span class=\"citation\">Targ. Hos. XI, 4</span>. <span class=\"citation\">Targ. II Sam. XIII, 15</span> (ed. Wil. <a href=\"#\" data-headword=\"רִיחֲמָתָא\">רִיחֲמָתָא</a>). <span class=\"citation\">Targ. I Sam. XX, 17</span> <span dir=\"rtl\">רַחֲמַת</span> constr.; a. e.—Pl. <a href=\"#\" data-headword=\"רַחֲמָא ²\">רַחֲמָתָא</a>. <span class=\"citation\">Targ. Prov. VII, 18</span> (Ms. <span dir=\"rtl\">רַחֲמָאתָא</span>; h. text <span dir=\"rtl\">דדים</span>).—V. <a href=\"#\" data-headword=\"רַחֲמוּ\">רַחֲמוּ</a>.</div>","alt":["רַחְ׳ II","רַחְמְתָא"]},"27324":{"h":"רַחְמָא","r":"T00523","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַחֲמָא ²\">preced.</a>) <i>friend</i>. <span class=\"citation\">Targ. Y. Ex. XI, 2</span>. <span class=\"citation\">Targ. Prov. XXVII, 6</span> (Ms. <a href=\"#\" data-headword=\"רִחִים II\">רחימא</a>); a. e.—<span class=\"citation\">Gitt. 55ᵇ</span> <span dir=\"rtl\">דרָחְמֵיה קמצא</span> whose friend’s name was Ḳamtsa. <span class=\"citation\">Gen. R. s. 96</span> <span dir=\"rtl\">בריה דרָחְמִיךְ</span> thy friend’s son, v. <a href=\"#\" data-headword=\"טָעַן II\"><span dir=\"rtl\">טְעַן</span> II</a>. <span class=\"citation\">Y. Shebi. IX, 39ᵃ</span> top <span dir=\"rtl\">בגין דלית … רחם</span> whereas these people (we) have no friend; a. e.—Pl. <a href=\"#\" data-headword=\"רַחֲמִין\">רַחֲמִין</a>, <a href=\"#\" data-headword=\"רַחֲמִין\">רַחְמֵי</a>, <a href=\"#\" data-headword=\"רַדְתָּא\">רָ׳</a>. <span class=\"citation\">Targ. Prov. VIII, 36</span>. <span class=\"citation\">Targ. Ps. XXXVIII, 12</span> Ms. (ed. <a href=\"#\" data-headword=\"רְחֵלָא\">רְחִי׳</a>). <span class=\"citation\">Targ. O. Gen. XXVI, 26</span> <span dir=\"rtl\">רַחְמוֹהִי</span> ed. Berl. (oth. ed. <span dir=\"rtl\">מרח׳</span>); a. e.—Y. Shebi. l. c. <span dir=\"rtl\">חמי לך תלתא ר׳ וכ׳</span> choose thee three friends &amp;c. <span class=\"citation\">Yalk. Gen. 115</span>, v. <a href=\"#\" data-headword=\"רִחִים II\"><span dir=\"rtl\">רְחִים</span> II</a>. <span class=\"citation\">Sabb. 32ᵃ</span> Ar. (ed. <span dir=\"rtl\">מרחמי</span>); a. e.</div>","alt":["רַחְ׳ III","רָחְמָא","רָחֵם"]},"27325":{"h":"רַחֲמוּ","r":"T00524","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַחְמָא\">preced.</a>) <i>love; loveliness; mercy</i>. <span class=\"citation\">Targ. Ez. XXIII, 17</span>. <span class=\"citation\">Targ. Prov. V, 19</span>. <span class=\"citation\">Ib. XVII, 9</span> (ed. Wil. <span dir=\"rtl\">רְחִמוּ׳</span>; Bxt. <span dir=\"rtl\">רְחִימ׳</span>). <span class=\"citation\">Targ. Ps. XXIX, 10</span> <span dir=\"rtl\">כורסי ר׳</span> (= h. <span dir=\"rtl\">כסא רחמים</span>, v. <a href=\"#\" data-headword=\"כִּסֵּא\">כִּסֵּא</a>); a. e.—<span class=\"citation\">B. Bath. 16ᵃ</span>, v. <a href=\"#\" data-headword=\"רַחֲמָנוּתָא\">רַחְמָנוּתָא</a>.—Trnsf. <i>maternal instinct, giving suck to a strange animal</i> (v. <a href=\"#\" data-headword=\"רָחַם\">רָחַם</a>, a. <a href=\"#\" data-headword=\"רָחַם\">רְחַם</a>). <span class=\"citation\">Bekh. 24ᵃ</span> <span dir=\"rtl\">חיישינן לר׳</span> we consider the possibility of her giving suck to a strange animal.</div>","alt":["רַחֲמוּתָא"]},"27326":{"h":"רַחֲמֵיּ","r":"T00525","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַחֲמִין\">רַחֲמִין</a></div>","alt":[]},"27327":{"h":"רַחֲמִים","r":"T00526","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>love, mercy</i>; (sub. <span dir=\"rtl\">בקשת</span>) <i>prayer</i>. <span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">שיכבשו רַחֲמַי את כעסי וכ׳</span> that my mercy may conquer my anger &amp;c., v. <a href=\"#\" data-headword=\"גָּלַל\">גָּלַל</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שיכבשו רַחֲמֶיךָ וכ׳</span> that thy mercy &amp;c. <span class=\"citation\">Ib. 10ᵃ</span>, sq. <span dir=\"rtl\">אל ימנע עצמו מן הר׳</span> must not despair of mercy (cease to pray), v. <a href=\"#\" data-headword=\"מָנַע\">מָנַע</a>. <span class=\"citation\">Ib. 55ᵃ</span> <span dir=\"rtl\">שלשה צריכים ר׳</span> three things must be prayed for. <span class=\"citation\">Ab. II, 3</span>, v. <a href=\"#\" data-headword=\"קֶבַע\">קֶבַע</a>. <span class=\"citation\">Lev. R. s. 2</span>, end <span dir=\"rtl\">הריני עמו בר׳ וכ׳</span> I shall be in grace with him, and he will receive me in repentance. <span class=\"citation\">Num. R. s. 20</span>, beg. <span dir=\"rtl\">כל הנביאים היו במדת ר׳ על וכ׳</span> all the (Israelitish) prophets were benevolently disposed towards Israel and towards the nations; a. v. fr.—<span dir=\"rtl\">בקש ר׳</span> to ask for mercy, <i>to pray</i>. <span class=\"citation\">Macc. 11ᵃ</span> <span dir=\"rtl\">שהיה להן לבקש ר׳ על וכ׳</span> it was their duty to pray for their generation &amp;c. <span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">ורבים יבקשו עליו ר׳</span> and the people will pray for him. <span class=\"citation\">Ib. 151ᵇ</span> <span dir=\"rtl\">לעולם … ר׳ על מידה זו וכ׳</span> man must always pray concerning this condition (poverty), for if he does not come to it, his son will &amp;c.; a. fr., v. <a href=\"#\" data-headword=\"בָּקַשׁ\">בָּקַשׁ</a>.—<span dir=\"rtl\">מדת הר׳</span>, v. <a href=\"#\" data-headword=\"דִּין II\"><span dir=\"rtl\">דִּין</span> II</a>. <span dir=\"rtl\">כסא ר׳</span>, v. <a href=\"#\" data-headword=\"כִּסֵּא\">כִּסֵּא</a>.</div>","alt":[]},"27328":{"h":"רַחֲמִין","r":"T00527","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XLIII, 30</span>. <span class=\"citation\">Targ. Jer. XVI, 5</span>; a. fr.—<span class=\"citation\">Ber. 20ᵇ</span> <span dir=\"rtl\">וחייבין … דר׳ נינהו</span> and they (women) are bound to say prayers, for they are a manifestation of love (and not a ceremony). <span class=\"citation\">Ḥull. 59ᵇ</span> <span dir=\"rtl\">בעא ר׳ וכ׳</span> he prayed, and it returned to its place; a. fr.; v. <a href=\"#\" data-headword=\"בְּעֵי I\"><span dir=\"rtl\">בְּעֵי</span> I</a></div>","alt":["רַחֲמֵי"]},"27329":{"h":"רַחֲמָן","r":"T00528","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַחֲמִין\">preced.</a>) <i>merciful, compassionate, sympathetic</i>; <span dir=\"rtl\">הר׳</span> <i>the Merciful, God</i>. <span class=\"citation\">Tosef. B. Kam. IX, 30</span> (ref. to <span class=\"citation\">Deut. XIII, 18</span>) <span dir=\"rtl\">כל זמן שאתה ר׳ הר׳ וכ׳</span> if thou art merciful, the Merciful will have mercy on thee. <span class=\"citation\">Kidd. 81ᵇ</span> <span dir=\"rtl\">הר׳ יצילנו וכ׳</span> the Lord save us from evil inclinations. <span class=\"citation\">Midr. Till. to Ps. CIII, 13</span> <span dir=\"rtl\">כר׳ שבאבות</span> like the most merciful of the patriarchs (Abraham). <span class=\"citation\">B. Bath. 145ᵇ</span> (ref. to <span class=\"citation\">Prov. XV, 15</span>) <span dir=\"rtl\">זה ר׳</span> this means the sympathetic man. <span class=\"citation\">Snh. 39ᵃ</span> <span dir=\"rtl\">אם ר׳ הוא … אם ר׳ מלא רחמים הוא וכ׳</span> if he (the human king) is merciful, he puts half of them (the rebels) to death; if he is most merciful, he chastises the prominent &amp;c.; a. fr.—Pl. <a href=\"#\" data-headword=\"רַחֲמָנִי\">רַחֲמָנִים</a>, <a href=\"#\" data-headword=\"רַחֲמָנִי\">רַחֲמָנִין</a>. <span class=\"citation\">Yeb. 79ᵃ</span> <span dir=\"rtl\">שלשה … הר׳ וכ׳</span> this nation (Israel) is known by three characteristic features, they are merciful, chaste, charitable; Y. Kidd. IV, 65ᶜ; <span class=\"citation\">Midr. Till. to Ps. XVII</span>. <span class=\"citation\">Pes. 113ᵇ</span> <span dir=\"rtl\">שלשה חייהן … הר׳ וכ׳</span> there are three persons whose lives are no lives, the sympathetic, the hot-tempered, and the delicate. <span class=\"citation\">M. Kat. 27ᵇ</span> (to those mourning to excess) <span dir=\"rtl\">אמר הקב&quot;ה אי אתם ר׳ בו יותר ממני</span> (Ms. M. omits <a href=\"#\" data-headword=\"בּוֹ\">בו</a>) the Lord says, you do not bear him more love than I do?; a. e.—<i>Fem.</i> (b. h.) <a href=\"#\" data-headword=\"רַחֲמָנִי\">רַחֲמָנִית</a>. Tanḥ. Vayetsé 8 <span dir=\"rtl\">אמר לה הקב&quot;ה את ר׳ וכ׳</span> the Lord said to her (Leah), thou art compassionate, I will also have compassion on her (Rachel).—Pl. <span dir=\"rtl\">רַחֲמָנִיּוֹת</span>. <span class=\"citation\">Meg. 14ᵇ</span> <span dir=\"rtl\">מפני שהנשים ר׳ הן</span> because women are compassionate. <span class=\"citation\">Ex. R. s. 2</span>, beg. <span dir=\"rtl\">מדותיו … ר׳ הן</span> the dealings and dispositions of the Lord are full of love; a. e.</div>","alt":[]},"27330":{"h":"רַחֲמָן ²","r":"T00529","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Lev. XXII, 28</span> (not <a href=\"#\" data-headword=\"רַחֲמִין\">רחמין</a>, v. infra). <span class=\"citation\">Targ. Y. Num. XII, 13</span>; a. e.—Esp. <a href=\"#\" data-headword=\"רַחֲמָן ²\">רחמנא</a> <i>the Merciful, God</i>. <span class=\"citation\">Targ. Ps. CXII, 4</span>. <span class=\"citation\">Targ. Ex. XXXIV, 6</span>; a. e.—Y. Ber. V, 9ᶜ top (ref. to <span class=\"citation\">Lev. XXII, 28</span>) <span dir=\"rtl\">אילין דמתרגמין … כמא דאנא ר׳ … כך תהוון רחמנין וכ׳</span> those who in the interpretation of this verse say, my people, as I am merciful in heaven, so shall you be merciful: cow or ewe &amp;c.; <span class=\"citation\">Y. Meg. IV, 75ᶜ</span> top <span dir=\"rtl\">דאנן רחמין</span> (corr. acc.).—<span class=\"citation\">Y. Kidd. I, 61ᵇ</span> <span dir=\"rtl\">בריך ר׳ דלית וכ׳</span> blessed be the Lord that I have neither father nor mother (because it is so difficult to do one’s duty by one’s parents); <span class=\"citation\">Y. Peah I, 15ᶜ</span> bot. <span class=\"citation\">Taan. 9ᵇ</span> <span dir=\"rtl\">ר׳ ליצלן וכ׳</span> the Lord save us &amp;c., v. <a href=\"#\" data-headword=\"כִּיסּוּפָא\">כִּיסּוּפָא</a>; a. fr.—Trnsf. <i>the Word of God, Scripture, the Law</i>. <span class=\"citation\">B. Mets. 3ᵃ</span> <span dir=\"rtl\">דרמיא ר׳ שבועה וכ׳</span> the Law imposes an oath upon him. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">ואמר ר׳ רמי וכ׳</span> and the Law says, impose an oath upon him. <span class=\"citation\">Ker. 7ᵃ</span> (ref. to <span class=\"citation\">Lev. XXI, 12</span>) <span dir=\"rtl\">שמן … קרייה ר׳ וכ׳</span> the Scripture calls it oil of ordination (sacred) to intimate, that it does not lose its sacred character even after being put on his head; a. v. fr.—Pl. <a href=\"#\" data-headword=\"רַחֲמָנִי\">רַחֲמָנִין</a>. Targ. Y. Lev. l. c.—Y. Ber. l. c.; Y. Meg. l. c.; a. e.—[Y. Ter. VIII, 45ᶜ bot. <span dir=\"rtl\">הוו רחמנא</span>, v. <a href=\"#\" data-headword=\"רְחֵם\">רְחֵם</a>.]</div>","alt":["רַחֲמָנָא"]},"27331":{"h":"רַחֲמָנוּת","r":"T00530","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַחֲמָן ²\">preced.</a>) <i>love, mercifulness, compassion</i>. <span class=\"citation\">Succ. 14ᵃ</span> <span dir=\"rtl\">מדת ר׳</span> divine mercy, opp. <a href=\"#\" data-headword=\"אַכְזְרִיּוּת\">אכזריות</a>. <span class=\"citation\">Keth. 50ᵇ</span> יודע אני … אלא מידת ר׳ I know that thou decidest so not as a matter of justice but as a matter of humanity. <span class=\"citation\">Gen. R. s. 56</span> <span dir=\"rtl\">ונופלות … מרַחֲמָנוּתוֹ של אבא</span> and tears of paternal love fell upon Isaac’s eyes; a. e.</div>","alt":[]},"27332":{"h":"רַחֲמָנוּתָא","r":"T00531","html":"<div class=\"sense\"> <span class=\"citation\">B. Bath. 16ᵃ</span> <span dir=\"rtl\">מינשי ליה לרַחֲמָנוּתֵיהּ דאברהם</span> (marg. vers. <span dir=\"rtl\">לרחימותיה</span>; Ms. H. <span dir=\"rtl\">לרחמותיה</span>) shall Abraham’s love (of God) be forgotten (fall into disuse)?</div>","alt":[]},"27333":{"h":"רַחֲמָנִי","r":"T00532","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"רַחֲמָן\">רַחֲמָן</a>. Tanḥ. <span class=\"citation\">B’shall. 11</span> <span dir=\"rtl\">אומרין שהוא ר׳ וכ׳</span> they say (in praise of a man) that he is merciful, he (God) is more. Mekh. B’shall., Shir., s. 1 <span dir=\"rtl\">שהוא ר׳ ואינו וכ׳</span> they praise a king that he is kindhearted, yet he is cruel; <span class=\"citation\">Yalk. Ex. 242</span>. Tanḥ. ʿEḳeb 2 <span dir=\"rtl\">נשר שהוא ר׳ על בניו</span> the eagle which is full of love for its young; <span class=\"citation\">Yalk. Prov. 963</span>; a. e.—Pl. <a href=\"#\" data-headword=\"רַחֲמָנִי\">רַחֲמָנִים</a>, v. <a href=\"#\" data-headword=\"רַחֲמָן\">רַחֲמָן</a>.—<i>Fem.</i> <a href=\"#\" data-headword=\"רַחֲמָנִי\">רַחֲמָנִית</a>, v. <a href=\"#\" data-headword=\"רַחֲמָן\">רַחֲמָן</a>.</div>","alt":[]},"27334":{"h":"רֵחָנָא","r":"T00533","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵיחָנָא\">רֵיחָנָא</a></div>","alt":[]},"27335":{"h":"רָחַף","r":"T00534","html":"<div class=\"sense\"> (b. h.) <i>to move, vibrate</i>.</div><div class=\"sense\"><b>Pi. רִחֵף</b> <div class=\"sense\"><i>to move, hover, flatter</i>. <span class=\"citation\">Ḥag. 15ᵃ</span> (ref. to <span class=\"citation\">Gen. I, 2</span>) <span dir=\"rtl\">כיונה שמְרַחֶפֶת על בניה וכ׳</span> like a dove that hovers over her young without touching them.</div></div>","alt":[]},"27336":{"h":"רָחַץ","r":"T00535","html":"<div class=\"sense\"> (b. h.) <i>to bathe, wash</i>. <span class=\"citation\">Sabb. 122ᵃ</span> <span dir=\"rtl\">מותר לִרְחוֹץ בה מיד</span> it is permitted to bathe in it immediately (after the exit of the Sabbath); ib. 151ᵃ; <span class=\"citation\">Makhsh. II, 5</span> <span dir=\"rtl\">רוֹחֵץ מיד</span>. <span class=\"citation\">Ber. 15ᵃ</span> <span dir=\"rtl\">מי שאין … לרחוץ ידיו</span> (Ms. M. <span dir=\"rtl\">ליטול</span>) he that has no water with which to wash his hands (before prayer). <span class=\"citation\">Tosef. Keth. VII, 6</span> <span dir=\"rtl\">ורוֹחֶצֶת במרחץ עם כל אדם</span> a woman that bathes in a bath-house with all kind of people (loses her jointure). Y. ib. VII, 31ᵇ bot. (as a case for divorce) <span dir=\"rtl\">הדירה שלא תִרְחֲצִי וכ׳</span> if he bound her by a vow (saying), thou shalt not bathe in a bath-house; a. fr.—Part. pass. <a href=\"#\" data-headword=\"רחוץ\">רָחוּץ</a>. <span class=\"citation\">Zeb. 17ᵇ</span> <span dir=\"rtl\">שלא רְחוּץ ידים וכ׳</span> not having washed his hands and feet (before a sacred function); <span class=\"citation\">Tosef. Men. I, 9</span>. <span class=\"citation\">Ib. 12</span> <span dir=\"rtl\">שלא רחוץ</span>, Var. <span dir=\"rtl\">ולא רָחְצוּ</span>.</div><div class=\"sense\"><b>Hif. הִרְחִיץ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רָחַף\">same</a>, <a href=\"#\" data-headword=\"רָחַף\">same</a>, <i>to wash, cleanse</i>. Ib. 10 <span dir=\"rtl\">משפשף ומַרְחִיץ</span> he rubs and washes (hands and feet). Ber. l. c. (ref. to <span class=\"citation\">Ps. XXVI, 6</span>) <span dir=\"rtl\">דכתיב אֶרְחַץ ולא אַרְחִיץ</span> (v. Ms. M., Rabb. D. S. a. l.) it is written <i>erḥats</i> (I bathe), and not <i>arḥits</i> (I cleanse), i.e. washing of hands as a symbolical act is equal to immersion. Y. Keth. V, 30ᵃ bot. <span dir=\"rtl\">ומַרְחֶצֶת לו וכ׳</span> she must bathe his feet (personally attend to his foot-bath). <span class=\"citation\">Yalk. Cant. 988</span> <span dir=\"rtl\">שמַרְחִיצִין את ישראל וכ׳</span> who cleanse Israel from sins; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to cause to bathe</i>. <span class=\"citation\">Num. R. s. 13</span><sup>2</sup> <span dir=\"rtl\">עתיד … ולהַרְחִיצָם בנחלי חלב</span> the Lord shall cause them to drink …, and to bathe in rivers of milk. Sabb. l. c.; Makhsh. l. c. <span dir=\"rtl\">מרחץ המרחצת בשבת</span> a bath-house that allows bathing (is heated and open) on the Sabbath. Y. Ber. II, 4ᶜ bot. <span dir=\"rtl\">מרחץ ואע&quot;פ שאינה מרחצת</span> a bath-house, even if it is not in use.</div></div><div class=\"sense\"><b>Pi. רִיחֵץ</b> <div class=\"sense\"><i>to cleanse</i>.—Part. pass. <span dir=\"rtl\">מְרוּחָץ</span>; pl. <span dir=\"rtl\">מְרוּחָצִין</span>. <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">שהיו כולן מר׳ מן העונות</span> they were all cleansed of their sins.</div></div><div class=\"sense\"><b>Nif. נִרְחַץ</b> <div class=\"sense\"><i>to be cleansed</i>. Yalk. Cant. l. c. <span dir=\"rtl\">שהטיף … ונִרְחֲצוּ מעונותיהם</span> the Lord dropped dew upon them, and they were cleansed of their sins.</div></div>","alt":[]},"27337":{"h":"רְחֵץ","r":"T00536","html":"<div class=\"sense\"> (with <span dir=\"rtl\">על</span>, or <a href=\"#\" data-headword=\"ב\">ב־</a>) <i>to lean on; to trust; to be safe</i>. <span class=\"citation\">Targ. Ps. CXVIII, 8</span>, sq. <span class=\"citation\">Ib. 10</span>, sq. <span class=\"citation\">Targ. Y. I Gen. XXVII, 40</span>. <span class=\"citation\">Targ. Job XII, 6</span>; a. fr.—Y. Ber. II, 5ᵃ <span dir=\"rtl\">רְחִיצַיָּא אנן</span> we are sure (cmp. <span dir=\"rtl\">מובטח</span>, v. <a href=\"#\" data-headword=\"בָּטַח\">בָּטַח</a>). <span class=\"citation\">Snh. 7ᵃ</span> <span dir=\"rtl\">גברא דרחיצנא עליה וכ׳</span> the man in whom I trusted lifted up his club &amp;c.; a. e.</div><div class=\"sense\"><b>Ithpa. אִתְרַחֵיץ</b> </div><div class=\"sense\"><b>Ithpe. אִתְרְחִיץ  אִתְרְחֵץ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רָחַץ\">same</a>. <span class=\"citation\">Targ. II Kings XVIII, 19</span>, sq. <span class=\"citation\">Targ. Ps. XXV, 2</span>. <span class=\"citation\">Ib. XXXVI, 8</span> Ms. (v. <a href=\"#\" data-headword=\"רוּחְצָן\">רוּחְצָן</a>). <span class=\"citation\">Targ. Jer. XLIX, 4</span>; a. fr.—<span class=\"citation\">B. Bath. 91ᵇ</span> <span dir=\"rtl\">דמודי … דמִתְרְחִיץ עליהון וכ׳</span> he who assents to them (pretends to share their errors) falls into their hand; he who confides in them,—what is his is theirs. Y. Sabb. II, 5ᵇ <span dir=\"rtl\">לא תִתְרְחֵץ על צלותי</span> rely not on my prayer. <span class=\"citation\">Cant. R. to VII, 2</span> <span dir=\"rtl\">בגין דאִיתְרְחִיצוּ ביה</span> because they trusted in him; a. e.</div></div><div class=\"sense\"><b>Af. אַרְחֵיץ</b> <div class=\"sense\"><i>to cause to trust</i>. <span class=\"citation\">Targ. Is. XXXVI, 15</span>; <span class=\"citation\">Targ. II Kings XVIII, 30</span>. <span class=\"citation\">Targ. Jer. XXIX, 31</span>.</div></div>","alt":["רְחֵיץ"]},"27338":{"h":"רָחֲצָן","r":"T00537","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוּחְצָן\">רוּחְצָן</a></div>","alt":[]},"27339":{"h":"רָחַק","r":"T00538","html":"<div class=\"sense\"> (b. h.) <i>to be distant, far, removed</i>. Y’lamd. to Num. X, 29, quot. in Ar. (ref. to <span class=\"citation\">Ps. LXXIII, 27</span>) <span dir=\"rtl\">מי שרוֹחֵק הק&quot;בה וכ׳</span> (ed. Koh. <span dir=\"rtl\">שׁמִתְרַחֵק</span>) he who keeps away from the Lord, so as not to repent. <span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">כרְחוֹק מזרח וכ׳</span> as far as the east is removed from the west; a. e.</div><div class=\"sense\"><b>Pi. רִחֵק  רִיחֵק</b> <div class=\"sense\"><i>to remove; to alienate; to reject, expel; to loathe</i>. <span class=\"citation\">B. Kam. 24ᵃ</span> top, a. e. <span dir=\"rtl\">ר׳ נגיחותיו</span> if the ox did his gorings in intervals (of three days), opp. <a href=\"#\" data-headword=\"קָרֵב\">קירב</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">רִיחֲקָה ראיותיה</span>, v. <a href=\"#\" data-headword=\"רְאִיָּה\">רְאִיָּה</a>. <span class=\"citation\">Yalk. Ps. 809</span> (ref. to Ps. l. c.) <span dir=\"rtl\">זה … שׁרִחֲקוּ את הקץ</span> this alludes to Balaam and his associates, who put far off the end (the day of judgment, <span class=\"citation\">Num. XXIV, 17</span>), opp. <a href=\"#\" data-headword=\"קְרָבוּ\">קרבו</a>. <span class=\"citation\">Ber. 60ᵇ</span> <span dir=\"rtl\">ורַחֲקֵנִי מאדם רע וכ׳</span> keep me far from a bad man and a bad associate. <span class=\"citation\">Eduy. V, 7</span> <span dir=\"rtl\">מעשיך יקרבוך ומעשיך יְרַחֲקוּךָ</span> thy own doings will bring thee near (win thee friends), and thy own doings will alienate thee. <span class=\"citation\">Ib. VIII, 7</span> <span dir=\"rtl\">לרַחֵק</span>, v. <a href=\"#\" data-headword=\"קָרֵב\">קָרֵב</a>; a. fr.—Part. pass. <span dir=\"rtl\">מְרוּחָק</span>; pl. <span dir=\"rtl\">מְרוּחָקִים</span>, <span dir=\"rtl\">מְרוּחָקִין</span>. Ib. <span dir=\"rtl\">המר׳ בזרוע</span>, v. <a href=\"#\" data-headword=\"קָרֵב\">קָרֵב</a>. <span class=\"citation\">Ber. 63ᵇ</span> <span dir=\"rtl\">שלא היה מר׳ וכ׳</span> which was only twelve miles off.</div></div><div class=\"sense\"><b>Hif. הִרְחִיק</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רָחֲצָן\">same</a>. <span class=\"citation\">Sifré Num. 94</span> <span dir=\"rtl\">מַרְחִיקִים</span>, v. <a href=\"#\" data-headword=\"קָרֵב\">קָרֵב</a>. <span class=\"citation\">B. Bath. II, 5</span> <span dir=\"rtl\">מַרְחִיקִין את הסולם וכ׳</span> (neighbors) must keep a ladder removed from the (neighbor’s) dove-cote four cubits. <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">אלא אם כן ה׳ ממנו וכ׳</span> unless he places (the wall) at a distance of four cubits. <span class=\"citation\">Ib. 18ᵇ</span> <span dir=\"rtl\">על המזיק להַרְחִיק את עצמו</span> it is the duty of him who causes the damage to remove himself; (oth. opin.) <span dir=\"rtl\">על הניזק להרחיק וכ׳</span> he who is injured must remove himself. <span class=\"citation\">Ber. I, 1</span> <span dir=\"rtl\">כדי להרחיק וכ׳</span> in order to keep men away (prevent them) from sin. <span class=\"citation\">Snh. 103ᵇ</span> <span dir=\"rtl\">שהִרְחִיקָה וכ׳</span>, v. <a href=\"#\" data-headword=\"לְגִימָה\">לְגִימָה</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מַרְחֶקֶת וכ׳</span> estranges those who are near (related) &amp;c.; a. fr.—2) <i>to keep aloof, stay away</i>. <span class=\"citation\">Ab. I, 7</span> <span dir=\"rtl\">הַרְחֵק משכן רע</span> keep aloof from a bad neighbor; a. e.—[Y. Ber. I, 2ᵈ bot. <span dir=\"rtl\">והרחיק על פתחו וכ׳</span>, read: <span dir=\"rtl\">והִרְתִּיק</span>, v. <a href=\"#\" data-headword=\"רָתַק\">רָתַק</a>.]</div></div><div class=\"sense\"><b>Hithpa. הִתְרַחֵק</b> </div><div class=\"sense\"><b>Nithpa. נִתְרַחֵק</b> <div class=\"sense\"><i>to remove one’s self; to become a stranger</i>. <span class=\"citation\">Yeb. 109ᵃ</span> <span dir=\"rtl\">לעולם ידבק … ויִתְרַחֵק וכ׳</span> man should always cling to three things, and keep aloof from three things. <span class=\"citation\">Snh. III, 4</span> <span dir=\"rtl\">קרוב ונ׳</span>, v. <a href=\"#\" data-headword=\"קָרוֹב I\">קָרוֹב</a>. <span class=\"citation\">Ber. 34ᵇ</span> (ref. to <span class=\"citation\">Is. LVII, 19</span>) <span dir=\"rtl\">שהיה קרוב … ונ׳ וכ׳</span> who came near committing a sin, and withdrew himself from it. Y’lamd. l. c., v. supra; a. e.</div></div>","alt":[]},"27340":{"h":"רִחֵק","r":"T00539","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Prov. XIX, 7</span>. <span class=\"citation\">Targ. Ps. CIII, 12</span>. <span class=\"citation\">Ib. LIII, 2</span>. <span class=\"citation\">Targ. Job XXI, 16</span>; a. fr.</div><div class=\"sense\"><b>Af. אַרְחֵיק</b> <div class=\"sense\"><b>1)</b> <i>to remove; to reject, loathe</i>. <span class=\"citation\">Targ. Ps. CIII, 12</span>. <span class=\"citation\">Targ. Ex. XXXIII, 7</span>. <span class=\"citation\">Targ. Is. VI, 12</span>. <span class=\"citation\">Targ. Job XXXIII, 20</span> (Ms. <i>Pa.</i>); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be removed</i>. <span class=\"citation\">Gitt. 58ᵃ</span> <span dir=\"rtl\">כמה מַרְחִיקְנָא וכ׳</span> how far am I (in my studies) from that place (the passage quoted)?</div></div><div class=\"sense\"><b>Pa. רַחֵק  רָחֵיק</b> <div class=\"sense\"><i>to remove, keep off; to loathe, abominate; to make abominable</i>. <span class=\"citation\">Targ. Job XI, 14</span>. <span class=\"citation\">Targ. Am. VI, 3</span> <span dir=\"rtl\">מר׳ יום</span> (ed. Lag. <span dir=\"rtl\">מיום</span>, corr. acc.; h. text <span dir=\"rtl\">מנדים</span>). <span class=\"citation\">Targ. Jer. II, 37</span> (h. text <span dir=\"rtl\">מאס</span>). <span class=\"citation\">Targ. Deut. VII, 26</span> (h. text <span dir=\"rtl\">תעב</span>). <span class=\"citation\">Targ. Job IX, 31</span>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מְרָחַק\">מְרָחַק</a>. <span class=\"citation\">Targ. Mal. I, 7</span> (h. text <span dir=\"rtl\">מגאל</span>).—<span class=\"citation\">Sabb. 128ᵇ</span> <span dir=\"rtl\">טמאה לא מְרַחֲקָא וולדא ואי מרחקא וכ׳</span> an unclean animal (after giving birth) does not keep its young off, and if it does, it does not allow them to come near again (stimulation of the maternal instinct does not avail, v. <a href=\"#\" data-headword=\"רָחַם\">רָחַם</a>). <span class=\"citation\">Snh. 29ᵃ</span> <span dir=\"rtl\">משום דמְרָחֲקָא דעתיה</span> (an enemy cannot be witness,) because his mind is estranged (hostile), opp. <a href=\"#\" data-headword=\"מִקְרְבָא\">מקרבא</a>; <span class=\"citation\">Yalk. Num. 788</span>; a. e.—V. <a href=\"#\" data-headword=\"מְרָחַק\">מְרָחַק</a>, <a href=\"#\" data-headword=\"מְרַחֲקָא\">מְרַחַקְתָּא</a>.</div></div>","alt":["רְחֵיק"]},"27341":{"h":"רָחַשׁ","r":"T00540","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to move, vibrate</i>. <span class=\"citation\">Y. Ber. II, 4ᵇ</span> bot. <span dir=\"rtl\">האומר … שפתותיו רוֹחֲשׁוֹת עמו בקבר</span> if one reports a tradition in the name of its author, his (the author’s) lips move in the grave with him (the reporter); Y. M. Kat. III, 83ᶜ bot.; Y. Shek. II, end, 47ᵃ. <span class=\"citation\">Ib.</span> <a href=\"#\" data-headword=\"מְרַאֲשׁוֹת\">מְרַחֲשׁוֹת</a> (<i>Pi.</i>, v. <a href=\"#\" data-headword=\"דָּבַב I\">דָּבַב</a>). <span class=\"citation\">Men. V, 8</span> (<span class=\"citation\">63ᵃ</span>) <span dir=\"rtl\">מרחשת … ומעשיה רוֹחֲשִׁין</span> (Bab. ed. <span dir=\"rtl\">רוחשין רכין</span>; Ms. M. only <span dir=\"rtl\">רכין</span>, v. Rabb. D. S. a. l. note) a <i>marḥesheth</i> is deep, and the pastry made in it vibrates (like jelly), opp. <span dir=\"rtl\">קשין</span>; Sifra Vayikra, N’dab., Par. 10, ch. XII; <span class=\"citation\">Lev. R. s. 3</span>, end; <span class=\"citation\">Yalk. ib. 451</span>.</div><div class=\"sense\"><b>—2)</b> <i>to swarm</i>.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"רִחוּשׁ\">רָחוּשׁ</a>; f. <span dir=\"rtl\">רְחוּשָׁה</span> <i>crowded</i>. <span class=\"citation\">Lev. R. s. 30</span>; Pesik. Ul’ḳaḥ., p. 184ᵃ sq., v. <a href=\"#\" data-headword=\"דָּחַס\">דָּחַס</a>.</div><div class=\"sense\"><b>—3)</b>  with <a href=\"#\" data-headword=\"לֵב\">לב</a>, <i>to be moved, to feel, think</i>. <span class=\"citation\">Midr. Till. to Ps. XLV, 2</span> <span dir=\"rtl\">לא יכלו … אלא כיון שר׳ לבם בתשובה וכ׳</span> they could not confess with their lips, but when their heart was moved in repentance, the Lord received them. Ib. <span dir=\"rtl\">אם בלבנו רָחַשְׁנוּ וכ׳</span> if we only have been thinking in our hearts, we have already told our deeds to the Lord; a. e.</div><div class=\"sense\"><b>Pi. רִיחֵשׁ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רִחֵק\">same</a>, <i>to move</i>. <span class=\"citation\">Pes. 88ᵇ</span> <span dir=\"rtl\">הטילו … ורִיחֲשָׁה</span> they poured cold water upon it (the lizard), and it moved. Y. Shek. l. c., v. supra.</div></div><div class=\"sense\"><b>Hif. הִרְחִישׁ</b> <div class=\"sense\"><b>1)</b> <i>to move</i> (the lips); <i>to whisper, think</i>. Y. Ber. IV, beg. 7ᵃ (ref. to <span class=\"citation\">I Sam. I, 13</span>) <span dir=\"rtl\">מיכן … להַרְחִישׁ בשפתותיו</span> from this we learn that he who prays must move his lips. Ib. <span dir=\"rtl\">מַרְחִישׁ בשפתותיו</span>. <span class=\"citation\">Pesik. R. s. 13</span> (ref. to <span class=\"citation\">Ex. XVII, 7</span>) [read:] <span dir=\"rtl\">אם מַרְחִישִׁים אנו בקרבנו דברים והוא יודע מה אנו מרחישים בקרבנו וכ׳</span> if we think words in our hearts, and he knows what we think in our hearts, we will worship him; (<span class=\"citation\">Ex. R. s. 26</span> <span dir=\"rtl\">מהרהרים</span>).</div><div class=\"sense\"><b>—2)</b> <i>to swarm, come forth</i> (of worms); <i>to bring forth</i> (<i>worms</i>). <span class=\"citation\">Koh. R. to V, 10</span> (ref. to <span class=\"citation\">Job XXV, 6</span>) <span dir=\"rtl\">אלו תולעים שמַרְחִישִׁין תחתיו במותו</span> that means the worms which come forth under him when he is dead. <span class=\"citation\">Gen. R. s. 23</span> <span dir=\"rtl\">התחיל המת מרחיש</span> (not <span dir=\"rtl\">מרחש</span>) corpses began to beget worms; a. e.—Trnsf. <i>to bring forth in abundance</i>. <span class=\"citation\">Ber. 17ᵃ</span> <span dir=\"rtl\">יַרְחִישׁ</span>, v. <a href=\"#\" data-headword=\"רְנָנָה\">רְנָנָה</a>.</div></div>","alt":[]},"27342":{"h":"רְחַשׁ","r":"T00541","html":"<div class=\"sense\"><b>1)</b> <i>to move, creep; to swarm, bring forth</i>. <span class=\"citation\">Targ. Gen. I, 26</span>; <span class=\"citation\">28</span>; <span class=\"citation\">30</span> (h. text <span dir=\"rtl\">רמש</span>). Ib. O. 20 (Y. <span dir=\"rtl\">יְרַחֲשׁוּן</span> <i>Pa.</i>; h. text <span dir=\"rtl\">שרץ</span>). <span class=\"citation\">Targ. Ps. CV, 30</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to move</i> (the lips); <i>to be moved</i>. <span class=\"citation\">Targ. Lam. I, 18</span>. <span class=\"citation\">Targ. Y. Gen. XLIII, 29</span>; a. e.—[<span class=\"citation\">Targ. Ps. XIV, 7</span> יִרְחַשׁ Ms., v. infra.]</div><div class=\"sense\"><b>Af. אַרְחֵישׁ</b> <div class=\"sense\"><b>1)</b> <i>to bring forth</i> (worms &amp;c.). (worms &amp;c.). <span class=\"citation\">Targ. Gen. I, 21</span>. <span class=\"citation\">Ib. IX, 2</span>. <span class=\"citation\">Targ. Y. Ex. XVI, 20</span>.</div><div class=\"sense\"><b>—2)</b> <i>to cause to come forth, bring about</i>. <span class=\"citation\">Targ. Ps. XIV, 7</span> (Ms. <i>Pe.</i>). <span class=\"citation\">Targ. Lam. III, 23</span>. <span class=\"citation\">Targ. Ps. LV, 9</span> (h. text <span dir=\"rtl\">אחישה</span>).</div></div><div class=\"sense\"><b>Pa. רַחֵשׁ</b> <div class=\"sense\"><b>1)</b> <i>to bring forth</i>. <span class=\"citation\">Targ. Y. Gen. I, 20</span> (v. supra).</div><div class=\"sense\"><b>—2)</b> <i>to move</i>. <span class=\"citation\">Ḥag. 3ᵃ</span> <span dir=\"rtl\">מניידי … ומְרַחֲשִׁין שפוותייהו</span> (mutes) nodded their heads and moved their lips.—Part. pass. <span dir=\"rtl\">מְרַחַשׁ</span>; f. <a href=\"#\" data-headword=\"מְנַחֵשׁ ²\">מְרַחְשָׁא</a>; pl. f. <span dir=\"rtl\">מְרַחְשָׁן</span>. <span class=\"citation\">Snh. 67ᵇ</span> <span dir=\"rtl\">חזא דקא מר׳ שפוותה</span> (not <span dir=\"rtl\">שפוותיה</span>) he saw that her lips were moving (she was mumbling a charm). <span class=\"citation\">Ib. 90ᵇ</span> <span dir=\"rtl\">דילמא רַחוּשֵׁי מר׳ שפוותייהו בעלמא</span> (not <span dir=\"rtl\">שפוותיה</span>) perhaps only their lips moved (in the grave)?, v. <a href=\"#\" data-headword=\"רָחַשׁ\">preced.</a>; (Ms. F. <span dir=\"rtl\">מְרַחֲשִׁין וכ׳</span> they moved their lips). <span class=\"citation\">Men. 63ᵃ</span> כדאמרי אינשי קמרחשן וכ׳ Ms. M. (ed. <span dir=\"rtl\">הוה מר׳ וכ׳</span>) as people say, his lips are moving (he is excited).</div></div><div class=\"sense\"><b>Ithpa. אִתְרַחֵישׁ</b> </div><div class=\"sense\"><b>Ithpe. אִתְרְחִישׁ</b> <div class=\"sense\"><i>to be brought about, to occur</i>. <span dir=\"rtl\">א׳ ניסא</span> <i>a miracle happened</i>. <span class=\"citation\">Targ. Ps. XVIII, 1</span>. <span class=\"citation\">Targ. Koh. IV, 13</span>.—<span class=\"citation\">B. Mets. 106ᵃ</span> <span dir=\"rtl\">אי הוות חזית לאִתְרַחוּשֵׁי לך ניסא הוה א׳ וכ׳</span> if thou wert worthy of a miracle to happen to thee, a miracle would have happened to thee like that &amp;c. <span class=\"citation\">Meg. 7ᵇ</span> <span dir=\"rtl\">לא בכל … מִתְרְחִישׁ ניסא</span> not always does a miracle happen. <span class=\"citation\">Gitt. 45ᵃ</span>; a. fr.</div></div>","alt":["רְחֵישׁ"]},"27343":{"h":"רַחַשׁ","r":"T00542","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְחַשׁ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>a creeping thing, reptile</i>. <span class=\"citation\">Ter. VIII, 4</span> <span dir=\"rtl\">כדי שיצא הר׳ וכ׳</span> as long as it would take a poisonous reptile to come forth … and drink; <span class=\"citation\">Ḥull. 10ᵃ</span>.—V. <a href=\"#\" data-headword=\"רָחוֹשׁ\">רָחוֹשׁ</a>.</div><div class=\"sense\"><b>—2)</b> <i>emotion, thought</i>. <span class=\"citation\">Midr. Till. to Ps. XLV, 2</span> <span dir=\"rtl\">אם ר׳ למה אמירה ואם אמירה למה ר׳</span> if thought is meant, why does the text mention speech, and if speech, why thought?; a. e.—V. <a href=\"#\" data-headword=\"רַחֲשׁוּשׁ\">רַחֲשׁוּשׁ</a>.</div>","alt":[]},"27344":{"h":"רֶפֶשׂ","r":"T00967","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְפַשׂ I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>stamping</i>; trnsf. <i>conquest.</i>—Pl. <span dir=\"rtl\">רְפָשִׂים</span>. <span class=\"citation\">Lam. R. to I, 13</span>; Midr. Sam. ch. XXIV, v. <a href=\"#\" data-headword=\"רָפַשׂ\">רָפַשׂ</a>.</div><div class=\"sense\"><b>—2)</b> <i>stamped dung</i>. <span class=\"citation\">B. Kam. 30ᵃ</span> <span dir=\"rtl\">לא יהא אלא כרִפְשׂוֹ</span> is this not the same as if he had deposited and stamped his dung (in the public road)?</div>","alt":[]},"27345":{"h":"רְפַשׂ II","r":"T00968","html":"<div class=\"sense\">, <i>stamping</i>. <span class=\"citation\">Gen. R. s. 93</span> <span dir=\"rtl\">חד ר׳</span> (some ed. <a href=\"#\" data-headword=\"רְפֵישׂ\">רְפֵישׂ</a>), v. <a href=\"#\" data-headword=\"רְפַשׂ I\"><span dir=\"rtl\">רְפַשׂ</span> I</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דין ר׳ מן דבית אבא</span> this stamp of the foot is peculiar to my father’s household; <span class=\"citation\">Yalk. ib. 150</span>.</div>","alt":[]},"27346":{"h":"*רְפַשׁ","r":"T00969","html":"<div class=\"sense\"> (cmp. Assyr. rapâsu, Del. Assyr. Handw. 626) <i>to spread</i>. <span class=\"citation\">Targ. Y. Num. XI, 31</span> Ar. a. Levita (ed. <span dir=\"rtl\">שרא</span>; h. text <span dir=\"rtl\">ויטש</span>).</div>","alt":[]},"27347":{"h":"רֶפֶת","r":"T00970","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span dir=\"rtl\">רְפָתִים</span> pl.; cmp. <a href=\"#\" data-headword=\"רָפַף\">רָפַף</a> a. <i>cattle-shed, stall</i>. <span class=\"citation\">Pes. 8ᵃ</span> <span dir=\"rtl\">ר׳ בקר</span> ox-stall. Y. ib. IV, 31ᵇ <span dir=\"rtl\">שבר׳ וכ׳</span> (<a href=\"#\" data-headword=\"זָבַל I\">זבל</a>) the dung of a stall whether large or small. <span class=\"citation\">B. Bath. II, 3</span>. <span class=\"citation\">Ib. VI, 4</span> <span dir=\"rtl\">ר׳ בקר הוא זה</span> this (four cubits by six) is a stall (but not a dwelling); a. fr.</div>","alt":[]},"27348":{"h":"רִפְתָּא","r":"T00971","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיפְתָּא\">רִיפְתָּא</a></div>","alt":[]},"27349":{"h":"רְצָא","r":"T00972","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְצֵי\">רְצֵי</a></div>","alt":[]},"27350":{"h":"רְצַד","r":"T00973","html":"<div class=\"sense\"><i>Pi</i>.)<i> to lie in wait, watch</i>. <span class=\"citation\">Lev. R. s. 26</span> <span dir=\"rtl\">אזל ור׳ עלוי</span> he went and held himself in wait for him.</div>","alt":[]},"27351":{"h":"רָצָה","r":"T00974","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רצי\">רצי</a></div>","alt":[]},"27352":{"h":"רִצּוּי","r":"T00975","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיצּוּי\">רִיצּוּי</a></div>","alt":[]},"27353":{"h":"רָצוֹן","r":"T00976","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>desire, will, good-will</i>. Tanḥ. Ki Thissa 27 <span dir=\"rtl\">כשאהיה אני עליהם אתה הוי בר׳ … אני בר׳</span> when I am angry with them, be thou in a conciliatory mood; and when thou art angry, I will be conciliatory, v. <a href=\"#\" data-headword=\"רָצָה\">רָצָה</a>. <span class=\"citation\">Ab. II, 4</span> <span dir=\"rtl\">עשה רְצוֹנוֹ כרְצוֹנְךָ וכ׳</span> do his (God’s) will as being thy will, in order that he may do thy desire as being his own; <span dir=\"rtl\">בטל רצונך וכ׳</span>, v. <a href=\"#\" data-headword=\"בָּטֵל I\"><span dir=\"rtl\">בָּטֵל</span> I</a>. <span class=\"citation\">Tosef. Ber. III, 7</span> <span dir=\"rtl\">עשה רצונך וכ׳</span> do thou thy will in the heavens above; <span class=\"citation\">Ber. 29ᵇ</span>; a. v. fr.—<span dir=\"rtl\">יהי ר׳</span> (abbrev. <span dir=\"rtl\">יה&quot;ר</span>) be it the will (of God), v. <a href=\"#\" data-headword=\"רַעְוָא\">רַעֲוָא</a>. <span class=\"citation\">Ib. 28ᵇ</span>. <span class=\"citation\">Taan. 5ᵇ</span>, sq.; a. v. fr.—<span dir=\"rtl\">יהי ר׳ מלפניך</span> (abbrev. <span dir=\"rtl\">יר&quot;מ</span>) be it thy will. <span class=\"citation\">Ber. 60ᵃ</span>; a. fr.—בר׳ <i>willingly</i>, opp. <span dir=\"rtl\">באונס</span>. <span class=\"citation\">Keth. 9ᵃ</span>; a. fr.—לר׳ <i>a</i>)<i> acceptable</i>. Sifra Vayikra, N’dab., ch. III, Par. 3 (ref. to <span class=\"citation\">Lev. I, 3</span>) <span dir=\"rtl\">כשם שאם אינו תמים אינו לר׳ וכ׳</span> as a sacrifice is not acceptable when it is not perfect &amp;c.; a. e.—<i>b</i>) <i>intentionally</i>. <span class=\"citation\">Makhsh. VI, 8</span> <span dir=\"rtl\">מטמא לר׳ ושלא לר׳</span> makes susceptible of uncleanness whether it is discharged intentionally (by milking) or unintentionally (by spontaneous dripping); ib. <span dir=\"rtl\">המשקין … לר׳</span> the liquids which come out of them with man’s intention (by pressing); <span class=\"citation\">Sabb. 143ᵇ</span>, sq.; a. fr.—<i>c</i>) <i>welcome</i>. <span class=\"citation\">Makhsh. I, 1</span> <span dir=\"rtl\">כל משקה שתחלתו לר׳ וכ׳</span> a liquid the contact with which is welcome at first (e.g. rain washing utensils), though finally it may be unwelcome (injurious).</div>","alt":[]},"27354":{"h":"רְצוּעָה","r":"T00977","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָצַע\">רָצַע</a>) </div><div class=\"sense\"><b>1)</b>  [<i>flattened</i>, cmp. <a href=\"#\" data-headword=\"רָצַם\">רָצַם</a>,] (<i>leather</i>) <i>thong, strap, lash</i>. <span class=\"citation\">Sabb. V, 4</span> <span dir=\"rtl\">בר׳ שבין קרניה</span> with the strap between her horns. <span class=\"citation\">Men. 35ᵇ</span> <span dir=\"rtl\">ר׳ דתפלין</span> the thong of the T’fillin. <span class=\"citation\">Num. R. s. 16</span> <span dir=\"rtl\">לתינוק שסרח ולקה בר׳ … מזכירין לו הר׳ וכ׳</span> like a child that did some mischief and was punished with a strap, and when they want to frighten it, they mention the strap with which it was punished; <span dir=\"rtl\">כך היה עמלק ר׳ רעה וכ׳</span> so was Amalek the bad lash for Israel; Tanḥ. Ḥuck. 18 <span dir=\"rtl\">מעולם רְצוּעַת מרדות וכ׳</span> (not <a href=\"#\" data-headword=\"רְצוּעָה\">רצועה</a>) Amalek was at all times the strap of chastisement for Israel. <span class=\"citation\">Macc. III, 12</span> (<span class=\"citation\">22ᵇ</span>) <span dir=\"rtl\">ור׳ בידו של וכ׳</span> and he (the beadle) held in his hand a lash of calf-skin, which was twisted doubly, and two (thinner) straps were going up and down (were plaited) through it (v. Rabb. D. S. a. l. note 7). <span class=\"citation\">Y. Sot. IX, 24ᵇ</span> top <span dir=\"rtl\">בעל הר׳</span> the strap-bearer, v. <a href=\"#\" data-headword=\"רַצְעָן\">רַצְעָן</a>. <span class=\"citation\">Yoma 12ᵃ</span>, a. e. <span dir=\"rtl\">ור׳ היתה יוצאה מחלקו וכ׳</span> a strip of land went forth from Judah’s lot and entered into Benjamin’s territory, and on this the Temple was built; a. fr.—Pl. <span dir=\"rtl\">רְצוּעוֹת</span>. Macc. l. c. <span dir=\"rtl\">ושתי ר׳</span> (not <span dir=\"rtl\">ושני</span>), v. supra. <span class=\"citation\">Midr. Till. to Ps. LXXVII</span> <span dir=\"rtl\">עשר ר׳ אתה לוקה</span> thou art to receive ten lashes. <span class=\"citation\">Sabb. VI, 1</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (trnsf.) <i>restriction</i>; <span dir=\"rtl\">הותרה הר׳</span> [the strap is untied,] the restriction is removed. <span class=\"citation\">Koh. R. to XI, 9</span> (ref. to <span dir=\"rtl\">שמח וכ׳</span>, ib.) <span dir=\"rtl\">הותרה הר׳ לית דין וכ׳</span> is every restraint removed? is there no justice and no judge?; <span class=\"citation\">ib. to I, 3</span>; <span class=\"citation\">Lev. R. s. 28</span>, beg.; a. e.—<span class=\"citation\">Y. Bicc. I, 64ᵃ</span>; Y. Kidd. IV, 66ᵇ top <span dir=\"rtl\">הואיל והותרה הר׳ יכ׳</span> since the restriction has been removed (by usage), I am likewise permitted to marry her. <span class=\"citation\">Y. Sot. VII, end, 22ᵃ</span>; a. e.</div>","alt":[]},"27355":{"h":"רְצוּעָה ²","r":"T00978","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. XIV, 23</span> <span dir=\"rtl\">ר׳ דסנדלא</span> (not <span dir=\"rtl\">סנדלת ר׳</span>; h. text <span dir=\"rtl\">שרוך נעל</span>).</div>","alt":[]},"27356":{"h":"רָצַח","r":"T00979","html":"<div class=\"sense\"> [<i>to perforate</i>, cmp. <span dir=\"rtl\">הרג</span>; <a href=\"#\" data-headword=\"חָלָל I\">חָלָל</a>,] <i>to slay, murder</i>. <span class=\"citation\">Midr. Till. to Ps. III</span> (ref. to <span dir=\"rtl\">ארבעתים</span>, <span class=\"citation\">II Sam. XII, 6</span>) <span dir=\"rtl\">אתה רָצַחְתָּ אחד שש עשרה נִרְצָחִים יהיו לך</span> thou hast murdered one: there shall be sixteen of thine murdered; <span class=\"citation\">Yalk. Sam. 148</span>. <span class=\"citation\">Macc. 12ᵃ</span> <span dir=\"rtl\">מי כתיב אם ר׳</span> it reads not (<span class=\"citation\">Num. XXXV, 27</span>), ‘if he slew’ (but, ‘he shall slay’); ib. <span dir=\"rtl\">מי כתיב יִרְצַח</span> it reads not, ‘he shall slay’ (but, if he slays he is not punished); a. e.—Part. <a href=\"#\" data-headword=\"רוֹצֵחַ\">רוֹצֵחַ</a> <i>manslayer, murderer</i>. <span class=\"citation\">Shebi. X, 8</span>; <span class=\"citation\">Macc. II, 8</span> <span dir=\"rtl\">ר׳ שגלה … ר׳ אני</span> when an involuntary manslayer comes to his place of refuge, and the citizens desire to honor him, he must say, I am a manslayer. <span class=\"citation\">Snh. 73ᵃ</span> (ref. to <span class=\"citation\">Deut. XXII, 26</span>) <span dir=\"rtl\">מקיש ר׳ … אף ר׳ ניתן להצילו בנפשו</span> the text draws an analogy between the case of one pursued by a murderer and that of the betrothed woman threatened with assault: as it is permitted to save the woman at the cost of the assailant’s life, so it is permitted to save the pursued at the cost of the would-be murderer’s life; <span class=\"citation\">Pes. 25ᵇ</span>; a. fr.—[<span class=\"citation\">Tosef. Sot. XV, 7</span>, read: <a href=\"#\" data-headword=\"רוֹצְחָן\">רוֹצְעָן</a>.]—Pl. <span dir=\"rtl\">רוֹצְחִים</span>, <span dir=\"rtl\">רוֹצְחִין</span>. <span class=\"citation\">Macc. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"זָרַח\">זָרַח</a>. <span class=\"citation\">Ib. 9ᵇ</span> <span dir=\"rtl\">בגלעד שכיחי ר׳</span> in Gilead cases of manslaughter are frequent; a. fr.</div><div class=\"sense\"><b>Nif. נִרְצַח</b> <div class=\"sense\"><i>to be slain, murdered</i>. <span class=\"citation\">Midr. Till. to Ps. III</span>; v. supra; a. e.</div></div><div class=\"sense\"><b>*. הִתְרַצֵּחַ</b> <div class=\"sense\"><i>to commit suicide</i>(?). <span class=\"citation\">Pesik. R. s. 24</span> (ref. to <span dir=\"rtl\">לא תרצח</span> <span class=\"citation\">Ex. XX, 13</span>) <span dir=\"rtl\">לא תִתְרַצֵּחַ</span> thou shalt not murder thyself; [prob. to be read: <span dir=\"rtl\">לא תִצָּרֵחַ לא תעשה הדם צוֹרֵחַ עליך</span> thou shalt not be cried about, make no blood cry out against thee].</div></div>","alt":[]},"27357":{"h":"רַצְחָן","r":"T00980","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָצַח\">preced.</a>) <i>murderer, assassin</i>. <span class=\"citation\">Sot. IX, 9</span> (<span class=\"citation\">47ᵃ</span>) <span dir=\"rtl\">משרבו הרוצחנין … חזרו לקרותו בן הרצ׳</span> (Y. ed. <span dir=\"rtl\">בן הרוצח</span>, read: <span dir=\"rtl\">הרוצחן</span>) when the assassins became numerous, the ceremony of breaking the neck of a heifer (v. <a href=\"#\" data-headword=\"עֶגְלָה\">עֶגְלָה</a>) was abolished; when El. b. Dinai and T. ben P. arose, the section (<span class=\"citation\">Deut. XXI, 7</span>) was read; then they called him (every such assassin) son of a murderer; expl. Y. ib. 24ᵃ top <span dir=\"rtl\">בריה קטולה</span> a murderous creature; <span class=\"citation\">Sifré Deut. 205</span> <span dir=\"rtl\">חזרו לקרותם בן הרצחנים</span>; <span class=\"citation\">Yalk. ib. 923</span> <span dir=\"rtl\">משרבו הרוצחין … בן הרוצחנין</span>—Pl. <span dir=\"rtl\">רַצְחָנִים</span>, <span dir=\"rtl\">רַצְחָנִין</span>, <span dir=\"rtl\">רוֹצְ׳</span>. Ib. Tanḥ. Masʿé 11 (ref. to <span class=\"citation\">Ps. XXV, 8</span>, sq.) <span dir=\"rtl\">אם לר׳ עשה שביל ודרך וכ׳</span> if the Lord made a path and a way for the manslayers that they might flee and be saved, how much more for the righteous &amp;c.; <span class=\"citation\">Yalk. Num. 787</span>. <span class=\"citation\">Gen. R. s. 22</span>, end (ref. to <span class=\"citation\">Gen. IV, 15</span>) <span dir=\"rtl\">עשאו אות לר׳</span> the Lord made him (Cain) a sign (warning) to murderers; a. e.</div>","alt":["רוֹצְחָן"]},"27358":{"h":"רצי","r":"T00981","html":"<div class=\"sense\"> v. <span dir=\"rtl\">רְעֵי II</span>) </div><div class=\"sense\"><b>1)</b> <i>to favor, pardon</i>. <span class=\"citation\">Midr. Till. to Ps. XLIV</span> <span dir=\"rtl\">אף בניו … ולהם רָצִיתָ ולא לנו</span> thou hast also done great things for his (Abraham’s) children in the desert, and to them thou hast been benevolent, but not to us. Sifra Vayikra, N’dab., Par. 3, ch. IV (ref. to <span class=\"citation\">Lev. I, 4</span>) <span dir=\"rtl\">המקום רוֹצֶה לו</span> the Lord will receive his offering with favor (pardon him); <span dir=\"rtl\">ועל מה המקום רוצה וכ׳</span> and for what sins will the Lord pardon him? For sins of omission &amp;c.; Yalk. Lev. 438. <span class=\"citation\">Ab. V, 11</span> <span dir=\"rtl\">נוח לִרְצוֹת</span> easily appeased; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to please, desire, be willing, consent</i>. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">רְצֵה והחליצנו</span>, v. <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a>. <span class=\"citation\">Meg. 29ᵃ</span> (play on <span dir=\"rtl\">תר̇צ̇ד̇וןֹ</span>, <span class=\"citation\">Ps. LXVIII, 17</span>) <span dir=\"rtl\">למה תִרְ֗צ̇וּ ד̇ין̇ עם סיני</span> why do you desire a contest with Sinai?; <span class=\"citation\">Yalk. Jud. 47</span> <span dir=\"rtl\">למה אתם ר̇ו̇צִ֗ים ומד̇יינ̇ים</span> why are you so willing to contest? <span class=\"citation\">Macc. 10ᵇ</span>, a. e. <span dir=\"rtl\">בדרך שאדם רוצה וכ׳</span> on what way a man wants to go, they (heavenly powers) lead him. <span class=\"citation\">Keth. 12ᵇ</span> <span dir=\"rtl\">אם רָצוּ לעשות וכ׳</span> if they wish to follow the usage of priests &amp;c. <span class=\"citation\">Yeb. IV, 5</span> <span dir=\"rtl\">לא ר׳</span> if he declines (to act as <i>yabam</i>). <span class=\"citation\">Ab. Zar. 32ᵃ</span> <span dir=\"rtl\">רוצה בקיומו ע&quot;י דבר אחר</span> if he wants the preservation of an idolatrous object for some other purpose. <span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">כשרָצִיתִי לא רָצִיתָ וכ׳</span> when I was willing (to reveal myself), thou wast unwilling (didst hide thy face) &amp;c.; a. v. fr.</div><div class=\"sense\"><b>Pi. רִצָּה</b> <div class=\"sense\"><b>1)</b> <i>to appease, to procure pardon</i>. <span class=\"citation\">Ex. R. s. 45</span> <span dir=\"rtl\">יהיו פני מְרַצִּין את פניך</span> my countenance shall appease thy countenance, v. <a href=\"#\" data-headword=\"כָּעַס\">כָּעַס</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כשהיה … הקב&quot;ה מְרַצֶּה אותו וכ׳</span> when Moses was angry with Israel, the Lord appeased him &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אהיה מְרַצְּךָ</span> I shall appease thee; (Tanḥ. Ki Thissa 27 <span dir=\"rtl\">אני ברצון</span>, v. <a href=\"#\" data-headword=\"רָצוֹן\">רָצוֹן</a>). <span class=\"citation\">Ab. IV, 18</span> <span dir=\"rtl\">אל תְּרַצֶּה וכ׳</span>, v. <a href=\"#\" data-headword=\"כַּעַס\">כַּעַס</a>. Ber. l. c. <span dir=\"rtl\">מנין שאין מְרַצִּין וכ׳</span> whence do we learn that we must not attempt to appease a man at the moment of his excitement? Sifra l. c. <span dir=\"rtl\">אע&quot;פ שלא סמך הזבח מרצה</span> although he has not put his hand on the victim, the sacrifice produces pardon; Yalk. Lev. l. c. <span dir=\"rtl\">נרצה הזבח</span> the sacrifice is accepted. <span class=\"citation\">Pes. 16ᵇ</span> <span dir=\"rtl\">על מה הציץ מרצה</span> for what (mistake at sacrifices) does the high priest’s plate effect pardon (make the sacrifice acceptable)?; <span class=\"citation\">Men. 25ᵇ</span>. <span class=\"citation\">Ib. III, 3</span>. <span class=\"citation\">Sifré Deut. 32</span> <span dir=\"rtl\">כשם שקרבנות מְרַצִּים וכ׳</span> as sacrifices are the means of atonement, so are sufferings &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make pleasing, acceptable</i>. <span class=\"citation\">Midr. Till. to Ps. LXXXV</span> <span dir=\"rtl\">הקב&quot;ה … עד שתְּרַצֶּה מעשיה להקב&quot;ה</span> the Lord turns around and observes and puts his eye on her (the earth), until she makes her deeds pleasing unto the Lord; <span class=\"citation\">ib.</span> <span dir=\"rtl\">אותה שעה היא מְרַצָּה וכ׳</span> then she makes her deeds pleasing &amp;c.; <span class=\"citation\">Yalk. ib. 833</span>.</div></div><div class=\"sense\"><b>Nif. נִרְצָה</b> <div class=\"sense\"><b>1)</b> <i>to be acceptable, be accepted</i>. Sifra l. c. <span dir=\"rtl\">ונרצה לו לו ולזבחו</span> ‘it shall be accepted for him’ (<span class=\"citation\">Lev. I, 4</span>) he and his sacrifice shall be accepted; Yalk. Lev. l. c. Ib. <span dir=\"rtl\">נ׳ הזבח</span>, v. supra; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be appeased</i>. <span class=\"citation\">Lam. R. to I, 2</span> (ref. to <span class=\"citation\">Ps. LXXVII, 8</span>) <span dir=\"rtl\">לא לְרַצּוֹת ולא לֵירָצוֹת</span> never to appease and never to be appeased; a. e.</div></div><div class=\"sense\"><b>Hif. הִרְצָה</b> <div class=\"sense\"><b>1)</b> <i>to satisfy</i> (a debt), <i>to make up for</i>. <span class=\"citation\">Yalk. Lev. 675</span> (ref. to <span class=\"citation\">Lev. XXVI, 34</span>) the land shall rest of itself <span dir=\"rtl\">עד שתַּרְצֶח לפני … היא חייבת לי</span> until it shall have made up before me for all the Sabbatical years which it owes me. <span class=\"citation\">Sifré Deut. 355</span> (ref. to <a href=\"#\" data-headword=\"רִצּוּי\">רצוי</a>, <span class=\"citation\">Deut. XXXIII, 24</span>) <span dir=\"rtl\">שהיה מִתְרַצֶּה … והן מַרְצִים לו בתבואה</span> he showed himself accommodating to his brethren with oil …, and they settled their account with grain; Yalk. ib. 962.</div><div class=\"sense\"><b>—2)</b>  [<i>to combine</i>,] <i>to assort coins; to count; to pay</i>. <span class=\"citation\">Sabb. 22ᵃ</span> <span dir=\"rtl\">להַרְצוֹת מעות וכ׳</span> to assort coins by the Ḥanuckah lights. <span class=\"citation\">Ber. 61ᵃ</span>; <span class=\"citation\">Erub. 18ᵇ</span> <span dir=\"rtl\">המַרְצֶה מעות לאשה וכ׳</span> he who pays money to a woman counting from his to her hand for the sake of gazing at her. <span class=\"citation\">Snh. 68ᵃ</span> הרבה מעות … שולחני להַרְצוֹתָן I have many coins, but no money-changer to assort them (many questions to ask but none to solve them); a. fr.</div><div class=\"sense\"><b>—3)</b>  (trnsf.) <i>to arrange subjects for debate, to discourse</i>. <span class=\"citation\">Tosef. Nidd. VI, 6</span> <span dir=\"rtl\">כשבאתי והִרְצֵיתִי דברים לפני וכ׳</span> when I came and discussed the subject before R. A. &amp;c.; <span class=\"citation\">Ab. Zar. 36ᵇ</span> <span dir=\"rtl\">והִרְצֵתִי דברי וכ׳</span>; Y. Peah VI, 19ᵇ bot.; <span class=\"citation\">Tosef. Ḥall. I, 6</span>; <span class=\"citation\">Pes. 38ᵇ</span>; Y. Shek. V, 49ᵃ <span dir=\"rtl\">והריציתי</span> (corr. acc.). <span class=\"citation\">Ḥag. 14ᵇ</span> ר׳ יהושע ה׳ דברים וכ׳ R. Joshua discoursed (on theosophy) before &amp;c.; a. e., v. <a href=\"#\" data-headword=\"הַרְצָאָה\">הַרְצָאָה</a>. </div></div><div class=\"sense\"><b>Hof. הוּרְצָה</b> <div class=\"sense\"><i>to be favorably received</i>. <span class=\"citation\">Yoma 7ᵃ</span> <span dir=\"rtl\">דם … ה׳ במזיד לא ה׳</span> if blood became unclean, and one sprinkled it, if by mistake, it is received (and the flesh may be eaten), if wilfully, it is not; <span class=\"citation\">Pes. 16ᵇ</span>; a. fr.</div></div><div class=\"sense\"><b>Hithp. הִתְרַצָּה</b> </div><div class=\"sense\"><b>Nithpa. נִתְרַצָּה</b> <div class=\"sense\"><b>1)</b> <i>to be reconciled, be satisfied; to comply with</i>. <span class=\"citation\">Ex. R. s. 45</span> <span dir=\"rtl\">לך והִתְרַצֶּה להם</span> go and comply with their wish, go back to the camp. <span class=\"citation\">Kidd. 45ᵃ</span> <span dir=\"rtl\">שמא נ׳ האב בקידושי שני</span> perhaps the father was satisfied with (confirmed) the betrothal of the second man. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">שמא נ׳ הבן</span> perhaps the son sanctioned (his father’s action in his behalf). Y. Ber. IV, 7ᵈ top; Y. Taan. IV, 67ᵈ bot. <span dir=\"rtl\">נִתְרַצֵיתֶם אני ואתם וכ׳</span> if you are satisfied, let me and you go early to &amp;c.; (<span class=\"citation\">Ber. 28ᵃ</span> <span dir=\"rtl\">נתפייסת</span>); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be gratified, enjoy</i>. <span class=\"citation\">Ber. 58ᵃ</span> bot. <span dir=\"rtl\">נ׳ להריח</span> if he smelt (the idolatrous frankincense) with enjoyment.</div></div>","alt":["רָצָה"]},"27359":{"h":"רְצֵי","r":"T00982","html":"<div class=\"sense\"> ch. <a href=\"#\" data-headword=\"רצי\">same</a>; v. <a href=\"#\" data-headword=\"רָצְיָא\">next w.</a></div><div class=\"sense\"><b>Pa. רַצֵּי</b> <div class=\"sense\"><i>to appease, to effect atonement</i>. <span class=\"citation\">Ber. 33ᵇ</span> <span dir=\"rtl\">כמה ידע … לרַצּוּיֵי למריה</span> how well that scholar knows how to appease his Master! <span class=\"citation\">Yoma 7ᵃ</span> <span dir=\"rtl\">למה לי לרצויי</span> what need would there be for the atoning power of the priest’s plate?; a. e.—<span class=\"citation\">Erub. 100ᵇ</span>; <span class=\"citation\">Yalk. Gen. 31</span>, v. infra.</div></div><div class=\"sense\"><b>Af. אַרְצֵי</b> <div class=\"sense\"><b>1)</b> <i>to be pleasant</i>. <span class=\"citation\">Erub. 100ᵇ</span> <span dir=\"rtl\">דמַרְצְיָא אַרְצוּיֵי קמיה</span> (Ms. M. <span dir=\"rtl\">דמרצי רַצּוּיֵי</span>, read: <span dir=\"rtl\">דמְרַצְּיָא</span>, <i>Pa.</i>) she makes herself pleasant (attractive) to him; <span class=\"citation\">Yalk. Gen. 31</span> <span dir=\"rtl\">דמְרַצְּיָיא רַצּוּיֵיה</span> she tries to please him.</div><div class=\"sense\"><b>—2)</b>  as <a href=\"#\" data-headword=\"רצי\">preced.</a> <i>Hif.</i> 3. <span class=\"citation\">Ḥag. 14ᵇ</span> <span dir=\"rtl\">דא׳ זאַרְצוּ קמיה וכ׳</span> he mentions only such a one as discoursed (on theosophy), and before whom others discoursed. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דא׳ מיהא קמיה מאן דא׳</span> he at least discoursed before one who again discoursed before others.</div></div><div class=\"sense\"><b>Ithpe. אִיתְרְצֵי  אִירְצֵי</b> <div class=\"sense\"><i>to be appeased</i>. <span class=\"citation\">Taan. 23ᵇ</span> <span dir=\"rtl\">אפשר דמִירְצֵי הקב&quot;ה וכ׳</span> (Ms. M. 2 <span dir=\"rtl\">דמִתְרְצֵי</span>, v. Rabb. D. S. a. l. note 90) peradventure the Lord will be appeased and send rain.</div></div>","alt":["רְצָא"]},"27360":{"h":"רָצְיָא","r":"T00983","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְצֵי\">preced.</a>) <i>peace-maker, advocate</i>. <span class=\"citation\">Targ. Prov. VI, 22</span> <span dir=\"rtl\">היא תיהוי רָצְיָיךְ</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">רָצְיָךְ</span>) she (the Law) will be thy advocate (in the hereafter, v. <span class=\"citation\">Gen. R. s. 35</span>, a. Rashi to Prov. l. c.; h. text <span dir=\"rtl\">תשיחך</span>).</div>","alt":["רָצְיָיא"]},"27361":{"h":"רְצִיחָה","r":"T00984","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָצַח\">רָצַח</a>) <i>case of murder, capital case, capital execution</i>. <span class=\"citation\">Snh. 35ᵃ</span> <span dir=\"rtl\">אין ר׳ דוחה שבת</span> capital punishment does not supersede the Sabbath (v. <a href=\"#\" data-headword=\"דָּחָה\">דָּחָה</a>). Mekh. Mishp. s. 4 (ref. to <span class=\"citation\">Ex. XXI, 14</span>) <span dir=\"rtl\">ללמדך על ר׳ שדוחה וכ׳</span> to intimate that the execution of a culprit supersedes the Temple service; a. fr.</div>","alt":[]},"27362":{"h":"רָצְיָיא","r":"T00985","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָצְיָא\">רָצְיָא</a></div>","alt":[]},"27363":{"h":"רְצִינְתָּא","r":"T00986","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">רצע׳</span>; cmp. <a href=\"#\" data-headword=\"רְצוּעָה\">רְצוּעָה</a>, a. <a href=\"#\" data-headword=\"*אַרְקְתָא III\"><span dir=\"rtl\">אַרְקְתָא</span> III</a>) name of <i>a worm</i> in grain. <span class=\"citation\">B. Bath. 91ᵇ</span> (expl. <span dir=\"rtl\">בלא סלמנטון</span> ib.) <span dir=\"rtl\">בלא ר׳</span> (Ms. H. <a href=\"#\" data-headword=\"רִיצִיתָא\">ריציתא</a>, Ms. R. <a href=\"#\" data-headword=\"רִיצִיתָא\">ריצניתא</a>, v. Rabb. D. S. a. l. note 2) without the grain worm; <span class=\"citation\">Yalk. Lev. 661</span> <a href=\"#\" data-headword=\"רִיצִיתָא\">רִיצְעֲתָא</a>.</div>","alt":[]},"27364":{"h":"רְצִיעָה","r":"T00987","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָצַע\">רָצַע</a>) <i>boring</i>, esp. <i>the boring through of the Hebrew bondsman’s ear</i> (according to <span class=\"citation\">Ex. XXI, 6</span>). <span class=\"citation\">Kidd. I, 2</span> <span dir=\"rtl\">הנרצע נקנה בר׳</span> the slave that has his ear bored through is taken possession of by the act of boring. <span class=\"citation\">Ib. 17ᵇ</span> (ref. to <span class=\"citation\">Deut. XV, 17</span>) <span dir=\"rtl\">אתה … או אינו אלא לר׳</span> you say, ‘and also to thy maid-servant thon shalt do likewise’ refers to the outfit (of the released slave), may it not refer to the boring? Ib. 16ᵇ <span dir=\"rtl\">אין ר׳ באשה</span> the law of boring through the ear does not apply to a woman. Ib. <span dir=\"rtl\">יובל של ר׳</span> the jubilee year for the slave that had his ear bored through (having declined to go free in his seventh year); a. fr.</div>","alt":[]},"27365":{"h":"רְצִיפְתָּא","r":"T00988","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>R’tsifta</i>, near Beth-Shean. Y. Dem. II, 22ᵈ top.</div>","alt":[]},"27366":{"h":"רְצִיצָא","r":"T00989","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְצַץ\">רְצַץ</a>) <i>a crushed pullet in the egg-shell</i>. <span class=\"citation\">Bekh. 8ᵇ</span> Ar., ed. <a href=\"#\" data-headword=\"דָּצוֹצָא\">דָּצוֹצָא</a>.</div>","alt":["רְצִיצָה"]},"27367":{"h":"רָצַם","r":"T00990","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָצַץ\">רָצץ</a>) <i>to press, flatten</i>. <span class=\"citation\">Y. Nidd. III, 50ᵈ</span> <span dir=\"rtl\">אין סנדל אלא שרְצָמוֹ חי</span> a sandal fœtus (v. <a href=\"#\" data-headword=\"סַנְדָּל\">סַנְדָּל</a>) occurs only when a live fœtus has been pressing on it.</div><div class=\"sense\"><b>Nif. נִרְצַם</b> <div class=\"sense\"><i>to be pressed, flattened</i>. Bab. <span class=\"citation\">Nidd. 25ᵇ</span> מתחלתו ולד הוא אלא שנ׳ Ar. (ed. <span dir=\"rtl\">שנרצף</span>) the <i>sandal</i> was originally a normal embryo, but was flattened by pressure, v. supra. <span class=\"citation\">Bets. 28ᵇ</span> <span dir=\"rtl\">שפוד שנ׳</span> a roasting spit which has been crushed (and its point broken off), contrad. to <span dir=\"rtl\">שנרצף</span>, v. <a href=\"#\" data-headword=\"רָצַף\">רָצַף</a>.</div></div>","alt":[]},"27368":{"h":"רָצַע","r":"T00991","html":"<div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"רָצַם\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>to press, flatten</i>; denom. <a href=\"#\" data-headword=\"רְצוּעָה\">רְצוּעָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to bore</i> with the awl, esp. <i>to perforate</i> the ear of a Hebrew bondsman (according to <span class=\"citation\">Ex. XXI, 6</span>). <span class=\"citation\">Kidd. 21ᵇ</span>; <span class=\"citation\">Sifré Deut. 122</span> <span dir=\"rtl\">אין רוֹצְעִים וכ׳</span>, v. <a href=\"#\" data-headword=\"מֵילַת\">מֵילַת</a>; <span class=\"citation\">Bekh. 37ᵇ</span> <span dir=\"rtl\">רוֹצְעִין</span>; a. fr.—Part. pass. <span dir=\"rtl\">רָצוּעַ</span>; f. <a href=\"#\" data-headword=\"רְצוּעָה\">רְצוּעָה</a>; pl. <span dir=\"rtl\">רְצוּעִים</span>; <span dir=\"rtl\">רְצוּעוֹת</span>. <span class=\"citation\">Tosef. Bekh. V, 3</span>; a. e.</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"רְצוּעָה\">רְצוּעָה</a>) <i>to lash</i>. <span class=\"citation\">Kidd. 70ᵃ</span> אליהו כופתו והקב&quot;ה רוֹצְעוֹ Elijah shall bind and the Lord lash him.</div><div class=\"sense\"><b>Nif. נִרְצַע</b> <div class=\"sense\"><i>to be perforated</i>; (of the Hebrew bondsman) <i>to have the ear bored through</i>. Ib. 21ᵇ <span dir=\"rtl\">אין … כהן נ׳ וכ׳</span> a bondsman priest must not have his ear bored through, because it would unfit him for priestly service. Ib. I, 2 <span dir=\"rtl\">הנִרְצָע וכ׳</span>, v. <a href=\"#\" data-headword=\"רְצִיעָה\">רְצִיעָה</a>. Ib. 14ᵇ <span dir=\"rtl\">המוכר עצמו אינו נ׳</span> he that sells himself need not undergo the operation of boring (in order to prolong his service); a. fr.</div></div><div class=\"sense\"><b>Pi. רִיצֵּעַ</b> <div class=\"sense\"><i>to lash</i>. <span class=\"citation\">Tosef. Sot. XV, 7</span> <span dir=\"rtl\">מסרוהו לרוצען ורִיצְּעוֹ</span> (ed. Zuck. incorr.) they handed him over to the strap-bearer, and he attempted to lash him; (Y. ib. IX, 24ᵇ top <span dir=\"rtl\">לבעל הרצועה וסטרו</span>).</div></div>","alt":[]},"27369":{"h":"רְצַע","r":"T00992","html":"<div class=\"sense\"><i>Af</i>. <span dir=\"rtl\">אַרְצַע</span> <a href=\"#\" data-headword=\"רָצַע\">same</a>, <i>to bore through</i>. <span class=\"citation\">Targ. O. Ex. XXI, 6</span>.</div>","alt":[]},"27370":{"h":"רַצְעָן","r":"T00993","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְצַע\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>leather-worker, shoemaker, saddler.</i>—Pl. <span dir=\"rtl\">רַצְעָנִים</span>, <span dir=\"rtl\">רַצְעָנִין</span>, <a href=\"#\" data-headword=\"רוּחְצָן\">רוֹ׳</a>. <span class=\"citation\">Pes. IV, 6</span> (Y. ed. <span dir=\"rtl\">רו׳</span>). Ib. 55ᵇ; Tosef. ib. II (III), 18; a. e.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"זְמוֹרָה\">זְמוֹרָה</a>) = <span dir=\"rtl\">בעל הרצועה</span> <i>strap-bearer</i>. <span class=\"citation\">Tosef. Sot. XV, 7</span>, v. <a href=\"#\" data-headword=\"רָצַע\">רָצַע</a>.</div>","alt":["רוֹצְעָן"]},"27371":{"h":"רַצְעָנָא","r":"T00994","html":"<div class=\"sense\">, <i>shoemaker, saddler</i>. <span class=\"citation\">Sabb. 60ᵇ</span></div>","alt":["רוֹ׳"]},"27372":{"h":"רָצַף","r":"T00995","html":"<div class=\"sense\"><b>1)</b> <i>to press, crush</i>. <span class=\"citation\">Nidd. 14ᵃ</span> <span dir=\"rtl\">שמש רְצָפָהּ</span> the membrum may have crushed it.—Part. pass. <span dir=\"rtl\">רָצוּף</span>; f. <span dir=\"rtl\">רְצוּפָה</span>; pl. <span dir=\"rtl\">רְצוּפִים</span>, <span dir=\"rtl\">רְצוּפִין</span>; <span dir=\"rtl\">רְצוּפוֹת</span>. Ib. <span dir=\"rtl\">מאכולת ר׳</span> a crushed louse.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כָּתַת\">כָּתַת</a> a. denom.) <i>to join closely, to place in rows; to pave with blocks</i>. Ohol. XVIII, 5 <span dir=\"rtl\">הרוֹצֵף … באבנים</span> if one paves an unclean field (v. <a href=\"#\" data-headword=\"פְּרָס\">פְּרָס</a>) with stones. <span class=\"citation\">Y. Orl. I, beg. 60ᶜ</span> <span dir=\"rtl\">במשנה … לעצים ברוצף</span> when he changes the usual order of planting; if he wants to use them for fuel, he plants the trees close together, &amp;c., opp. <span dir=\"rtl\">משפה</span> planting wide apart. <span class=\"citation\">Y. Kil. III, 28ᵈ</span> bot. <span dir=\"rtl\">רוצף</span> he who plants vegetables in a row, opp. <span dir=\"rtl\">עושה קלחים יחידים</span>; a. e.—Part. pass. as ab. <span class=\"citation\">Esth. R. to I, 6</span> <span dir=\"rtl\">היה ביתו ר׳ וכ׳</span> his house was paved with precious stones and jewels. <span class=\"citation\">Neg. XI, 9</span> <span dir=\"rtl\">השתי אם היה ר׳</span> if the warp (on the loom) is close (the threads being properly arranged). <span class=\"citation\">B. Bath. 29ᵃ</span> <span dir=\"rtl\">שלש … שאכלן ר׳</span> by the three years of which they speak is meant that he had the undisturbed usufruct for three years in succession, opp. <span dir=\"rtl\">מפוזרות</span>. <span class=\"citation\">Ib. 37ᵇ</span> <span dir=\"rtl\">אכלן ר׳</span> if he has had the usufruct of trees planted close together in rows (which shows that they were intended to be transplanted when grown older). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מכרן ר׳ וכ׳</span> if he sold closely planted trees, the buyer cannot claim the soil. <span class=\"citation\">Y. M. Kat. I, 80ᶜ</span> top, a. e. <a href=\"#\" data-headword=\"ר׳\">ר׳</a>, opp. <span dir=\"rtl\">מרווחין</span>, v. <a href=\"#\" data-headword=\"רָוַוח\">רָוַוח</a>. <span class=\"citation\">Y. Gitt. VIII, end, 49ᵈ</span> <span dir=\"rtl\">בר׳</span> when the signatures are close together, opp. <span dir=\"rtl\">מסורגין</span>, v. <a href=\"#\" data-headword=\"סָרַג\">סָרַג</a>. <span class=\"citation\">Treat. Sof’rim I, 10</span>, v. <a href=\"#\" data-headword=\"סָרַג\">סָרַג</a>; a. fr.—Trnsf. <i>crowded, stuffed</i>. <span class=\"citation\">Cant. R. to IV, 4</span>; <span class=\"citation\">Gen. R. s. 32</span>; a. fr., v. <a href=\"#\" data-headword=\"רֵיקָן\">רֵיקָן</a>.</div><div class=\"sense\"><b>Nif. נִרְצַף</b> <div class=\"sense\"><i>to be squeezed, crushed</i>. <span class=\"citation\">Nidd. 25ᵇ</span>, v. <a href=\"#\" data-headword=\"רָצַם\">רָצַם</a>. <span class=\"citation\">Bets. 28ᵇ</span> <span dir=\"rtl\">שפוד שנ׳</span> (Ms. M. <span dir=\"rtl\">שנרצם</span>, corr. acc.) a roasting spit which has been squeezed and bent, contrad. to <a href=\"#\" data-headword=\"רָצַם\">נרצם</a>.—[<span class=\"citation\">Tosef. M. Kat. I, 2</span> <span dir=\"rtl\">מרצפין</span> ed. Zuck., read: <span dir=\"rtl\">מרבצין</span> or <span dir=\"rtl\">מרביצין</span>, v. <a href=\"#\" data-headword=\"רָבַץ\">רָבַץ</a>.]</div></div>","alt":[]},"27373":{"h":"רְצַף","r":"T00996","html":"<div class=\"sense\"><b>1)</b> <i>to join</i>.—Part. pass. <span dir=\"rtl\">רָצִיף</span>; pl. <span dir=\"rtl\">רְצִיפִין</span> (Hebr. <span dir=\"rtl\">רְצוּ׳</span>). <span class=\"citation\">Targ. Y. Lev. XII, 4</span>, sq.</div><div class=\"sense\"><b>—2)</b> <i>to weld by hammering</i>. <span class=\"citation\">Zeb. 95ᵃ</span> דרָצֵיף ליה מִירְּצַף Ms. M. (ed. <span dir=\"rtl\">דרציף מרציף</span>) when he closes the hole up by hammering. <span class=\"citation\">Gen. R. s. 7</span> <span dir=\"rtl\">רְצוֹף רצפך וכ׳</span> hammer away thy hammering (strike me), for it is good for learning; [‘Rashi’: (the teacher saying to him that is punished) <i>pave</i> thy paving, i.e. lie down; v. <a href=\"#\" data-headword=\"רָצַף\">רָצַף</a>].</div>","alt":[]},"27374":{"h":"רִצְפָא","r":"T00997","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְצַף\">preced.</a>) <i>hammering</i> [or <i>paving</i>]. <span class=\"citation\">Gen. R. s. 7</span>, v. <a href=\"#\" data-headword=\"רְצַף\">preced.</a></div>","alt":[]},"27375":{"h":"רִצְפָה","r":"T00998","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. Baer to <span class=\"citation\">Ez. XL</span>, </div><div class=\"sense\"><b>1)</b> <i>block pavement</i>. <span class=\"citation\">Meg. 22ᵇ</span> (ref. to <span class=\"citation\">Lev. XXVI, 1</span> <span dir=\"rtl\">אבן משכית</span>) <span dir=\"rtl\">לא אסרה תורה אלא ר׳ של וכ׳</span> the Torah forbids only prostration on a stone pavement (in a synagogue). <span class=\"citation\">Shek. VI, 2</span>; Y. ib. 49ᶜ a priest was splitting wood in the wood cell of the Temple <span dir=\"rtl\">וראה את הר׳ וכ׳</span> and noticed that the pavement there was different from the others. Y. Naz. VII, 56ᵇ bot. <span dir=\"rtl\">הנקבר ערום בארון … או ע&quot;ג רי׳ וכ׳</span> a body buried naked in a marble coffin, or on a paved floor, or on a marble plate; Bab. <span class=\"citation\">Naz. 51ᵃ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ר׳ של לבנים</span> brick pavement. <span class=\"citation\">Yoma I, 7</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (from its resemblance to a block pavement) <i>cobweb.</i>—Pl. <span dir=\"rtl\">רִצְפוֹת</span> <span class=\"citation\">Ukts. I, 2</span> (Ar. <a href=\"#\" data-headword=\"רִצְפִית\">רִצְפִית</a>); Tosef. ib. I, 2 (<span class=\"citation\">T’bul Yom III</span>), v. <a href=\"#\" data-headword=\"סִיג II\"><span dir=\"rtl\">סִיג</span> II</a>.</div>","alt":["רִי׳"]},"27376":{"h":"רִצְפִית","r":"T00999","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִצְפָה\">preced.</a></div>","alt":[]},"27377":{"h":"רִצְפְּתָא","r":"T01000","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"רִצְפָה\">רִצְפָה</a>. <span class=\"citation\">Targ. II Kings XVI, 17</span>. <span class=\"citation\">Targ. Ez. XL, 17</span>, sq.</div>","alt":["רִיצְ׳"]},"27378":{"h":"רָצַץ","r":"T01001","html":"<div class=\"sense\"> (b. h.) <i>to press, squeeze, crush</i>. Tanḥ. Ḥuck. 20 <span dir=\"rtl\">נכנסו … ורָצְצוּ וכ׳</span> the rocks were moved into the caves and crushed all those warriors; <span class=\"citation\">Num. R. s. 19</span>. <span class=\"citation\">Cant. R. to I, 6</span> (play on <a href=\"#\" data-headword=\"רִצְפָה\">רִצְפָּה</a>, <span class=\"citation\">Is. VI, 6</span>) <span dir=\"rtl\">רוֹץ פֶּה רְצוֹץ פה וכ׳</span> <i>ritspah</i> means <i>rots peh</i>, crush the mouth of him (Isaiah) who spoke ill of my children; Tanḥ. Vayishl. 2; <span class=\"citation\">Pesik. R. s. 33</span> <span dir=\"rtl\">רֹץ פה</span>; <span class=\"citation\">Yalk. Num. 764</span>; <span class=\"citation\">Yalk. Is. 273</span> <span dir=\"rtl\">רַצֵּץ</span> (<i>Pi.</i>); <span class=\"citation\">Yalk. Kings 218</span> <span dir=\"rtl\">רצץ</span>. Cant. R. l. c. (play on <span dir=\"rtl\">רְצָפִים</span> <span class=\"citation\">I Kings XIX, 6</span>) [read:] <span dir=\"rtl\">רץ פים רצוץ פיות וכ׳</span> crush the mouths of all who (like Elijah) speak ill of my children. <span class=\"citation\">Y. Ab. Zar. II, 40ᶜ</span> bot. <span dir=\"rtl\">שלא יָרוֹץ את וכ׳</span> lest he (the gentile) break his (the Jew’s) skull. Y. Macc. II, beg. 31ᶜ <span dir=\"rtl\">והושיט … ורְצָצָהּ</span> and a child put forth his hand (under the roller), and he crushed it. <span class=\"citation\">Bets. 34ᵃ</span> <span dir=\"rtl\">רְצָצַתָּהּ בהמה</span> a beast squeezed it (an animal, against a wall); <span class=\"citation\">Ḥull. III, 3</span> (<span class=\"citation\">56ᵃ</span>) Ms. M. (ed. <span dir=\"rtl\">רִיצְּצַתָּהּ</span>, <i>Pi.</i>). <span class=\"citation\">Ex. R. s. 30</span><sup>17</sup> <span dir=\"rtl\">רָצְצוּ גפנים</span> they crushed the vines; a. fr.—<span class=\"citation\">Gen. R. s. 63</span> (ref. to <span class=\"citation\">Gen. XXV, 22</span>) <span dir=\"rtl\">שזה רַץ להרוג וכ׳</span> this one pressed to kill that one &amp;c. Ib. <span dir=\"rtl\">עשו רץ ומפרכס וכ׳</span> Esau pressed and struggled to get out.</div><div class=\"sense\"><b>Pi. רִיצֵּץ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רִצְפְּתָא\">same</a>. Ḥull. l. c., v. supra. Y. Kidd. IV, end, 66ᶜ <span dir=\"rtl\">הטוב … רַצֵּץ את מוחו</span> the best of the serpents—crush its brain. Yalk. Kings l. c.; Yalk. Is. l. c., v. supra. <span class=\"citation\">Midr. Till. to Ps. CXXXVII</span>; Yalk. ib. 884 they put their thumbs into their mouths <span dir=\"rtl\">ומְרַצְּצִים אותם</span> and crushed them (with their teeth); <span class=\"citation\">Pesik. R. s. 31</span> <span dir=\"rtl\">ומרצצים ומקצצים אותם</span> crushed and bit them off; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to push, struggle</i>. <span class=\"citation\">Midr. Till. to Ps. LVIII</span> (ref. to <span dir=\"rtl\">ויתרצצו</span>, <span class=\"citation\">Gen. XXV, 22</span>) <span dir=\"rtl\">שהיה מְרַצֵּץ עם וכ׳</span> he (Esau) struggled with his brother in his mother’s womb.</div></div><div class=\"sense\"><b>Hif. הֵרֵץ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רִצְפְּתָא\">same</a>, </div><div class=\"sense\"><b>1)</b> <i>to crush</i>. Y. Yeb. I, 3ᵃ bot. <span dir=\"rtl\">הרי אתם … בשביל שיָרֵיצּוּ את מוחי</span> you place my head between two high mountains …, that they may crush my brain (you want me to decide between two great authorities); <span class=\"citation\">Tosef. Ohol. XVIII, 18</span>.</div><div class=\"sense\"><b>—2)</b> <i>to press, rush in a crowd</i>. Tanḥ. Balak 4; <span class=\"citation\">Num. R. s. 20</span> like the money-changer <span dir=\"rtl\">שהכל מְרִיצִּים לו</span> to whom all rush (to have their coins examined).</div></div><div class=\"sense\"><b>Hithpol. הִתְרוֹצֵץ</b> <div class=\"sense\">, <i>Nithpol</i>. <span dir=\"rtl\">נִתְרוֹצֵץ</span> <i>to press one another, struggle</i>. Tanḥ. Vayḥi 15 <span dir=\"rtl\">כיון שנתְרוֹצְצוּ וכ׳</span> when the children struggled together within her.</div></div>","alt":[]},"27379":{"h":"רְצַץ","r":"T01002","html":"<div class=\"sense\"><i>Pa.</i> <span dir=\"rtl\">רַצֵּץ</span> <a href=\"#\" data-headword=\"רָצַץ\">same</a>, <i>to squeeze, crush</i>. <span class=\"citation\">Targ. Lam. III, 16</span> <a href=\"#\" data-headword=\"רָצַץ\">רִיצֵּץ</a> (Hebraism; h. text <span dir=\"rtl\">ויגרס</span>). <span class=\"citation\">Targ. Y. II, Ex. XV, 6</span> (ed. Vien. <span dir=\"rtl\">מַרְצְצָא</span>, <i>Af</i>.; h. text <span dir=\"rtl\">תרעץ</span>).</div>","alt":[]},"27380":{"h":"רַק","r":"T01003","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָקַק\">רָקַק</a>, <a href=\"#\" data-headword=\"רְקַק\"><a href=\"#\" data-headword=\"רְקַק\">רְקַק</a>.</a></div>","alt":["רָק"]},"27381":{"h":"רֹק","r":"T01004","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹק\">רוֹק</a></div>","alt":[]},"27382":{"h":"רַק ²","r":"T01005","html":"<div class=\"sense\"><i>only, except.</i>—Pl. <span dir=\"rtl\">רַקִּין</span> <i>use of the word</i> <a href=\"#\" data-headword=\"רַק\">רַק</a>. <span class=\"citation\">Gen. R. s. 1</span>; Y. Ber. IX, 14ᵇ bot., v. <a href=\"#\" data-headword=\"אַךְ I\"><span dir=\"rtl\">אַךְ</span> I</a>.</div>","alt":[]},"27383":{"h":"רֵק","r":"T01006","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵיק\">רֵיק</a>, <a href=\"#\" data-headword=\"רֵיקָא\"><a href=\"#\" data-headword=\"רֵיקָא\">רֵיקָא</a>.</a></div>","alt":["רֵקָא"]},"27384":{"h":"רֻקָּא","r":"T01007","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹק ²\">רוּקָּא</a></div>","alt":[]},"27385":{"h":"רָקֵב I","r":"T01008","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָקֵב II\">next w.</a>) <i>rotten.</i>—Pl. <span dir=\"rtl\">רְקֵבִים</span>, <span dir=\"rtl\">רְקֵי׳</span>. <span class=\"citation\">Gen. R. s. 84</span> <span dir=\"rtl\">שלכם ר׳ וכ׳</span> (I saw in my dream) your crops were rotten and mine preserved; <span class=\"citation\">Yalk. ib. 141</span> <span dir=\"rtl\">מַרְקִיבִים</span>.</div>","alt":[]},"27386":{"h":"רָקֵב II","r":"T01009","html":"<div class=\"sense\"> (b. h.) [<i>to be perforated, hollow</i>; v. <a href=\"#\" data-headword=\"רוּקְבָּא II\"><span dir=\"rtl\">רוּקְבָּא</span> II</a>,] <i>to be worm-eaten, rot, decay</i>. <span class=\"citation\">Tosef. Ter. VI, 3</span> <span dir=\"rtl\">יִרְקְבוּ</span> must be left to rot (cannot be used). <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">תרום ותִרְקוֹב</span> separate the T’rumah, and let it rot; a. e.</div><div class=\"sense\"><b>Hif. הִרְקִיב</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רָקֵב I\">same</a>. <span class=\"citation\">Yalk. Gen. 141</span>, v. <a href=\"#\" data-headword=\"רָקֵב I\">preced.</a> <span class=\"citation\">Tosef. Gitt. III, 2</span> same. <span class=\"citation\">Yalk. Gen. 141</span>, v. <a href=\"#\" data-headword=\"רָקֵב I\">preced.</a> <span class=\"citation\">Tosef. Gitt. III, 2</span> <span dir=\"rtl\">ואיני חושש שמא הִרְקִיבָה תבואה</span> and we need not take into consideration that the grain may have been attacked by worms. Ib. <span dir=\"rtl\">הלך ומצא שהִרְקִיבוּ</span> if he went (to examine) and found that it was ruined <span dir=\"rtl\">הרי זה … עד שתַּרְקִיב וכ׳</span> he must take into consideration (the possibility of having consumed untithed grain) from the time that the grain may have begun to be attacked, or the wine to become sour. Ib. IX (VII), 12 <span dir=\"rtl\">נימוק או שהִירְקִיב</span> if the document is decayed or worm-eaten. Y. Yoma VII, 44ᵇ bot. <span dir=\"rtl\">שם היו מַרְקִיבִין</span> there they were allowed to rot; a. fr.—Esp. <i>to turn into a lump of decayed matter</i> <a href=\"#\" data-headword=\"רָקָב\">(רָקָב</a>). <span class=\"citation\">Naz. 51ᵇ</span> <span dir=\"rtl\">טחנו וחזר וה׳</span> if he powdered the mass taken from the ground, and it turned again into a lump.</div><div class=\"sense\"><b>—2)</b> <i>to cause to rot, to eat through</i>. <span class=\"citation\">Deut. R. s. 2</span> <span dir=\"rtl\">ומַרְקִיבָן</span> and eats them through, v. <a href=\"#\" data-headword=\"מָסַס\">מָסַס</a>.</div></div><div class=\"sense\"><b>Nif. נִרְקַב</b> <div class=\"sense\"><i>to be worm-eaten, rot</i>. <span class=\"citation\">Gen. R. s. 91</span> <span dir=\"rtl\">גוזר … ונִרְקֶבֶת</span> he decrees concerning the grain, and it is worm-eaten; (Yalk. ib. 148 <span dir=\"rtl\">ומַרְקֶבֶת</span>, <i>Hif.</i>).</div></div>","alt":["רָקַב"]},"27387":{"h":"רְקֵב","r":"T01010","html":"<div class=\"sense\">; <i>Ithpe.</i> אִירְקִיב <i>to become</i> <a href=\"#\" data-headword=\"רָקָב\">רָקָב</a> (v. <a href=\"#\" data-headword=\"רָקֵב II\">preced.</a><i>Hif.</i>). <span class=\"citation\">Naz. 51ᵃ</span>, sq.</div>","alt":[]},"27388":{"h":"רָקָב","r":"T01011","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רְקֵב\">preced.</a>) <i>rottenness</i>, esp. <i>raḳab, a mass of earth from a grave containing parts of a decayed human body</i>, which causes uncleanness if of a certain quantity <a href=\"#\" data-headword=\"תַּרְוָד\">(תַּרְוָוד</a>). <span class=\"citation\">Naz. VII, 2</span> <span dir=\"rtl\">מלא תרווד ר׳</span> a spoonful of <i>raḳab</i>. <span class=\"citation\">Tosef. Ohol. II, 2</span> <span dir=\"rtl\">מלא תרווד ר׳ שאמרו וכ׳</span> the spoonful of <i>raḳab</i> of which they speak (as making unclean) means as much as is grabbed with the fingers from their roots and upwards. <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">ואיזהו מת שיש לו ר׳</span> what corpse is it to which the law of <i>raḳab</i> applies?; <span class=\"citation\">Naz. 51ᵃ</span>; Y. ib. VII, 56ᵇ bot.; a. fr.</div>","alt":[]},"27389":{"h":"רִקְבָּא","r":"T01012","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָקָב\">preced.</a>) <i>rot, rust</i>. <span class=\"citation\">Targ. Is. XL, 20</span>.—<span class=\"citation\">Nidd. 36ᵇ</span> a brazen mortar <span dir=\"rtl\">דלא שליט ביה ר׳</span> over which rust has no power.</div>","alt":["רִי׳"]},"27390":{"h":"רַקָּבָא","r":"T01013","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רִקְבָּא\">preced.</a>) <i>wood-worm</i>. <span class=\"citation\">Targ. Hos. V, 12</span>.—V. <a href=\"#\" data-headword=\"רוּקְבָּא I\"><span dir=\"rtl\">רוּקְבָּא</span> I</a>.</div>","alt":[]},"27391":{"h":"רַקְבּוּבִית","r":"T01014","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַקָּבָא\">preced.</a>) <i>decay, decayed matter</i>. <span class=\"citation\">Y. Peah VII, 20ᵇ</span> top, v. <a href=\"#\" data-headword=\"גָּרַף\">גָּרַף</a>. <span class=\"citation\">Y. Sabb. IV, beg. 6ᵈ</span> <span dir=\"rtl\">אם רָבַת רַקְבּוּבִיתָן</span> if the decay in them (from moths) is far advanced. <span class=\"citation\">Yoma 38ᵇ</span> (ref. to <span class=\"citation\">Prov. X, 7</span>); <span dir=\"rtl\">רַקְבִּיבוּת תעלה בשמותן וכ׳</span> rottenness enters their names, none name their children after them.</div>","alt":[]},"27392":{"h":"רַקְבּוּבִית ²","r":"T01015","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רַקְבּוּבִית\">same</a>. <span class=\"citation\">Targ. Job XIII, 28</span>.—2) <i>earth-worm</i>. Ib. XXVII, 18 (h. text <a href=\"#\" data-headword=\"עָשׁ\">עש</a>).</div>","alt":["רַקְבּוּבִיתָא"]},"27393":{"h":"רִקָּבוֹן","r":"T01016","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רַקְבּוּבִית ²\">preced.</a> wds.) <i>decayed matter.</i>—Pl. <span dir=\"rtl\">רִקְבוֹנוֹת</span>. <span class=\"citation\">Tosef. Ter. X, 3</span> (ed. Zuck. <span dir=\"rtl\">רַקְבִּיבִיּוֹת</span>, Var. <a href=\"#\" data-headword=\"רַזְבּוֹנִית\">רַקְבּוֹנִית</a>), v. <a href=\"#\" data-headword=\"נִיצּוֹלֶת\">נִיצּוֹלֶת</a>.</div>","alt":[]},"27394":{"h":"רַקְבִּיבוּת","r":"T01017","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַקְבּוּבִית\">רַקְבּוּבִית</a>.—Pl. <span dir=\"rtl\">רַקְבִּיבִיּוֹת</span>, v. <a href=\"#\" data-headword=\"רִקָּבוֹן\">preced.</a></div>","alt":[]},"27395":{"h":"רָקַד","r":"T01018","html":"<div class=\"sense\"> (b. h.), <i>Pi.</i> <span dir=\"rtl\">רִקֵּד</span> </div><div class=\"sense\"><b>1)</b> <i>to dance</i>. <span class=\"citation\">Bets. V, 2</span> <span dir=\"rtl\">ולא מְרַקְּדִין</span> nor dare you dance (on the Sabbath and Holy Days). <span class=\"citation\">Keth. 16ᵇ</span> <span dir=\"rtl\">רִקְּדוּ לפניה</span> (or <span dir=\"rtl\">רָקְדוּ</span>) if there is evidence that they danced before her (at the wedding procession, which proves that she married a virgin). Ib. bot. <span dir=\"rtl\">כיצד מְרַקְּדִין לפני הכלה</span> what do we sing in her praise when dancing before a bride? <span class=\"citation\">Num. R. s. 20</span><sup>11</sup> <span dir=\"rtl\">בשעה … השטן מְרַקֵּד לו וכ׳</span> when a man plans a sin, Satan dances to him (cheering him), until he has done it; a. fr.—V. <a href=\"#\" data-headword=\"רִיקּוּד\">רִיקּוּד</a>.</div><div class=\"sense\"><b>—2)</b> <i>to sift</i>, v. infra.</div><div class=\"sense\"><b>Hif. הִרְקִיד</b> <div class=\"sense\"><i>to shake</i> (in the sieve), <i>to sift</i>. Y. Ber. IX, 13ᶜ top; Tosef. Ber. VII (VI), 2. Y. Shebi. V, end, 36ᵃ <span dir=\"rtl\">לא … מַרְקִידִין עמו</span> you must not winnow, or grind, or sift flour together with him. <span class=\"citation\">Sabb. VII, 2</span> (<span class=\"citation\">73ᵃ</span>) <span dir=\"rtl\">המְרַקֵּד</span> he who sifts flour (on the Sabbath); a. fr.</div></div>","alt":[]},"27396":{"h":"רְקַד","r":"T01019","html":"<div class=\"sense\"><i>Pa.</i> <span dir=\"rtl\">רַקֵּד</span> <a href=\"#\" data-headword=\"רָקַד\">same</a>, <i>to dance</i>. <span class=\"citation\">Targ. II Sam. VI, 16</span>.—<span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> <span dir=\"rtl\">שרון מטפחין ומְרַקְּדִין</span> (not <span dir=\"rtl\">ומרקדקין</span>) they began to clap and dance. <span class=\"citation\">Koh. R. to III, 2</span> <span dir=\"rtl\">לית … עד דאת מְרַקֵּיד וכ׳</span> thou shalt not move from here, until thou dancest a little for us. <span class=\"citation\">Gen. R. s. 63</span>; a. fr.</div>","alt":[]},"27397":{"h":"רַקָּדָא","r":"T01020","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְקַד\">preced.</a>) <i>dancer</i>. Lam. R. introd. (R. Ḥăn. 1) <span dir=\"rtl\">כל דזמר זמרא … באדניה דר׳</span> (not <a href=\"#\" data-headword=\"(זִימְרָא\">זימרא</a>) whatever the singer may sing, it enters not the ear of the dancer (ref. to <span class=\"citation\">Prov. XXV, 20</span>).</div>","alt":[]},"27398":{"h":"רקדנין","r":"T01021","html":"<div class=\"sense\">, <span class=\"citation\">Targ. II Kings XI, 13</span> <span dir=\"rtl\">דר׳ עמא</span> (ed. Lag. <span dir=\"rtl\">דרדנין</span>, Var. <span dir=\"rtl\">דרכנין</span>, v. Lagarde Prophetae I, p. XXIV) read: <span dir=\"rtl\">דרַהֲטִין עמא</span> those who hurried the people (to the assembly; h. text <span dir=\"rtl\">הרצין העם</span>).</div>","alt":[]},"27399":{"h":"רקדק","r":"T01022","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> <span dir=\"rtl\">מרקדקין</span>, v. <a href=\"#\" data-headword=\"רְקַד\">רְקַד</a></div>","alt":[]},"27400":{"h":"רֵקָה","r":"T01023","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵיק\">רֵיק</a>, a. <a href=\"#\" data-headword=\"רֵיקָא\">רֵיקָא</a>.</div>","alt":[]},"27401":{"h":"רָקוֹב","r":"T01024","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">רְקוֹבוֹת</span>, v. <a href=\"#\" data-headword=\"רוּקְבָּא II\"><span dir=\"rtl\">רוּקְבָּא</span> II</a>.</div>","alt":[]},"27402":{"h":"רִקּוּד","r":"T01025","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיקּוּד\">רִיקּוּד</a></div>","alt":[]},"27403":{"h":"רקודי","r":"T01026","html":"<div class=\"sense\">, <span class=\"citation\">B. Mets. 84ᵃ</span>; <span class=\"citation\">Sabb. 127ᵃ</span> Ar., v. <a href=\"#\" data-headword=\"דְּקוּרָא\">דְּקוּרָא</a></div>","alt":[]},"27404":{"h":"רִקּוּחַ","r":"T01027","html":"<div class=\"sense\"> v. sub <a href=\"#\" data-headword=\"רִיקּוּד\">רִיקּ׳</a>.</div>","alt":["רִקּוּם","רִקּוּעַ"]},"27405":{"h":"רְקוֹעַ","r":"T01028","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְקַע\">רְקַע</a>) [<i>patched</i>,] </div><div class=\"sense\"><b>1)</b> <i>spotted</i>. <span class=\"citation\">Targ. O. Gen. XXX, 32</span> (h. text <span dir=\"rtl\">טלוא</span>).—Pl. <span dir=\"rtl\">רְקוֹעִין</span>, <span dir=\"rtl\">רְקוֹעַיָּא</span>. <span class=\"citation\">Ib. 35</span>; <span class=\"citation\">39</span>.—<i>Fem.</i> <span dir=\"rtl\">רְקוֹעֲתָא</span>. <span class=\"citation\">B. Kam. 118ᵇ</span> <span dir=\"rtl\">בר׳</span> in the case of the theft of a spotted sheep (the presence of which, if returned, I must be noticed).—Pl. <span dir=\"rtl\">רְקוֹעָתָא</span>. Targ. O. l. c. 35.</div><div class=\"sense\"><b>—2)</b>  (trnsf., v. B. Kam. l. c.) <i>well-known, distinguished</i>. <span class=\"citation\">M. Kat. 28ᵃ</span> מאן חשיב … מאן ר׳ Ar. (ed. <a href=\"#\" data-headword=\"רַקִּיעַ\">רַקִּיעַ</a>) who is esteemed, who is I regarded, who is distinguished (before the angel of death)?</div>","alt":[]},"27406":{"h":"רָקַח","r":"T01029","html":"<div class=\"sense\"> (b. h.) <i>to pound</i> spices; <i>to spice, perfume</i>.—Part. <a href=\"#\" data-headword=\"רוֹקֵחַ\">רוֹקֵחַ</a> <i>druggist, apothecary</i>. <span class=\"citation\">Gen. R. s. 10</span>, v. <a href=\"#\" data-headword=\"סַם\">סַם</a>. <span class=\"citation\">Koh. R. to X, 1</span>, v. <a href=\"#\" data-headword=\"נָבַע\">נָבע</a>; a. e.</div><div class=\"sense\"><b>Pi. רִקֵּחַ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רְקוֹעַ\">same</a>. Gen. R. l. c. Y. Bets. I, 60ᵈ <span dir=\"rtl\">חייב משם מְרַקֵּהַ</span> (not <a href=\"#\" data-headword=\"מרקיה\">מרקיה</a>, <a href=\"#\" data-headword=\"מָרֵקָה\">מרקה</a>) is guilty because it comes under the category of doing apothecary’s work.</div></div>","alt":[]},"27407":{"h":"רֶקַח","r":"T01030","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רָקַח\">preced.</a>) <i>apothecary’s preparation</i>. <span class=\"citation\">Cant. R. to VIII, 2</span>, v. <a href=\"#\" data-headword=\"פָּטַם\">פָּטַם</a>.</div>","alt":[]},"27408":{"h":"קְצַצְתָּא I","r":"S01842","html":"<div class=\"sense\"><i>timber.</i>—Pl. <span dir=\"rtl\">קְצַצְיָיתָא</span>, v. <a href=\"#\" data-headword=\"קְצוּצְתָּא\">קְצוּצְתָּא</a>.</div>","alt":[]},"27409":{"h":"קְצַצְתָּא II","r":"S01843","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"קַצְרָא II\"><span dir=\"rtl\">קַצְרָא</span> II</a></div>","alt":["קְצַצְתָּה"]},"27410":{"h":"קָצַר","r":"S01844","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to cut, reap</i>. <span class=\"citation\">Sabb. VII, 2</span> (among the labors forbidden on the Sabbath) <span dir=\"rtl\">הקוֹצֵר</span> cutting plants. Ib. 73ᵇ <span dir=\"rtl\">משום קוצר</span> as an act coming under the category of reaping. <span class=\"citation\">Pes. IV, 8</span> <span dir=\"rtl\">קוֹצְרִין וגודשין וכ׳</span> they reaped (the barley) and piled it before the ʿOmer was offered. <span class=\"citation\">Peah II, 7</span> <span dir=\"rtl\">שדה שקְצָרוּהָ וכ׳</span> a field which gentiles reaped (for themselves) or which robbers reaped. <span class=\"citation\">Ib. 8</span> <span dir=\"rtl\">נותן … שק׳</span> he must give up the poor man’s share from what he reaped. <span class=\"citation\">Ib. III, 6</span> <span dir=\"rtl\">כדי לִקְצוֹר ולשנות</span> large enough for cutting (swinging the sickle) once and a second time; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be short</i>, v. <a href=\"#\" data-headword=\"קָצֵר\">קָצֵר</a>.</div><div class=\"sense\"><b>—3)</b>  (with <span dir=\"rtl\">נפש</span>) <i>to be impatient, vexed; to be sick of</i>. <span class=\"citation\">Gen. R. s. 52</span> <span dir=\"rtl\">אבל היא לא קָצְרָה נפשה וכ׳</span> but she was not vexed (did not suffer from unsatisfied desire) &amp;c.; <span class=\"citation\">Y. Keth. V, 30ᵇ</span>; <span class=\"citation\">Yalk. Jud. 70</span>. Tanḥ. Ḥuck. 19 <span dir=\"rtl\">קצרה נפשם בדרך</span> they were sick of marching.</div><div class=\"sense\"><b>Pi. קִצֵּר</b> <div class=\"sense\"><i>to shorten, be brief in doing</i>. <span class=\"citation\">Ber. I, 4</span> <span dir=\"rtl\">מקום … לקַצֵּר וכ׳</span> where they prescribed a lengthy benediction, one is not permitted to shorten, where they prescribed a short formula &amp;c. Y. Yoma VI, beg. 43ᵇ <span dir=\"rtl\">שלא יהא … קַצֵּר</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<span dir=\"rtl\">דבריך</span> not that one of the contestants be permitted to speak as long as he needs, and the other be told, make thy speech brief; Y. Snh. III, 21ᶜ top. <span class=\"citation\">Ber. 34ᵃ</span> <span dir=\"rtl\">היה מְקַצֵּר וכ׳</span> gave a very brief prayer. Mekh. B’shall., Vayassʿa, s. 1 <a href=\"#\" data-headword=\"ק׳\">ק׳</a> (<a href=\"#\" data-headword=\"ב\">ב</a>)<span dir=\"rtl\">ברכותיו</span> gave short benedictions (prayers); <span dir=\"rtl\">לא ק׳ … ממשה</span> he was not briefer than Moses (in his prayer, <span class=\"citation\">Num. XII, 13</span>). Ib. <span dir=\"rtl\">יש שעה לְקַצֵּר וכ׳</span> there is a time to be brief &amp;c.; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְקַצֵּר</b> </div><div class=\"sense\"><b>Nithpa. נִתְקַצֵּר</b> <div class=\"sense\"><b>1)</b> <i>to be shortened</i>. <span class=\"citation\">Lev. R. s. 21</span> <span dir=\"rtl\">היו … מִתְקַצְּרוֹת</span> their years (of life) were shortened.</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">נפש</span>) <i>to be impatient, sick</i>. Tanḥ. l. c. <span dir=\"rtl\">נִתְקַצְּרָה נפש העם בדרך</span> (not <a href=\"#\" data-headword=\"קָצַר\">נתקצר</a>), v. supra.</div></div>","alt":[]},"27411":{"h":"קְצַר","r":"S01845","html":"<div class=\"sense\"><b>1)</b> <i>to be short</i>. <span class=\"citation\">Targ. Ps. CII, 24</span> קְצָרוּן Ms. (ed. <span dir=\"rtl\">איתקצרון</span>).</div><div class=\"sense\"><b>—2)</b> <i>to shorten</i>, v. infra., v. infra.</div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"קְצִירָא\">קְצִירָא</a>) <i>to be sick</i>. <span class=\"citation\">B. Kam. 91ᵃ</span> למימד גברא כמה מיקצר … לא מִקְצַר וכ׳ Ms. M. (ed. <span dir=\"rtl\">כמה לִיקְצַר</span>) as to estimating how long a person is likely to suffer from such a wound and how long he will not, i.e. as to estimating positively the time needed for recovery, I have no doubt that we can do it.</div><div class=\"sense\"><b>Pa. קַצֵּר</b> <div class=\"sense\"><i>to shorten</i>. <span class=\"citation\">Targ. Ps. LXXXIX, 46</span> Ms. (ed. <a href=\"#\" data-headword=\"כְּרִיסְפָּא\">קְ׳</a>, <i>Pe.</i>).</div></div><div class=\"sense\"><b>Ithpa. אִיתְקַצַּר</b> <div class=\"sense\"><i>to be shortened, reduced</i>. <span class=\"citation\">Targ. II Kings XIX, 26</span>; <span class=\"citation\">Targ. Is. XXXVII, 27</span>. <span class=\"citation\">Ib. XXVIII, 20</span>. <span class=\"citation\">Targ. Y. Gen. XXVIII, 10</span>; a. e.</div></div>","alt":[]},"27412":{"h":"קָצֵר","r":"S01846","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>short</i>. <span class=\"citation\">Ab. II, 15</span> <span dir=\"rtl\">היום ק׳ וכ׳</span> the day (of life) is short, and the work large. <span class=\"citation\">Y. Pes. VII, 35ᵇ</span> bot. <span dir=\"rtl\">ילך לו בק׳</span> let him take the shortest road to it; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"קְצָרָה\">קְצָרָה</a>. Mekh. B’shall., Vayassʿa, s. 1 <span dir=\"rtl\">תפילת הצדיקים ק׳</span> the prayer of the pious is short. <span class=\"citation\">Ber. I, 4</span> <span dir=\"rtl\">אחת … ואחת ק׳</span> one lengthy and one short benediction. <span class=\"citation\">Ib. IV, 2</span> <span dir=\"rtl\">היה … תפלה ק׳</span> used to say a short prayer on entering and on leaving the school-house. <span class=\"citation\">Ib. 4</span>. <span class=\"citation\">Y. Hor. II, 46ᵈ</span> top <span dir=\"rtl\">בא לו … בק׳</span> if he came by the shortest road; a. fr.—<span class=\"citation\">Midr. Till. to Ps. LIII</span> <span dir=\"rtl\">ע&quot;י שהיתה ידו ק׳ במצות</span> because his hand was short (he was wanting) in good deeds; <span class=\"citation\">Yalk. ib. 769</span>; <span class=\"citation\">Yalk. Sam. 135</span> <span dir=\"rtl\">נפשו ק׳</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"קַצְרִים\">קְצָרִים</a>; <a href=\"#\" data-headword=\"קַצְרוּת\">קְצָרוֹת</a>. <span class=\"citation\">Cant. R. to VI, 2</span> <span dir=\"rtl\">ארוכות וק׳</span>, v. <a href=\"#\" data-headword=\"אָרוּךְ\">אָרוּךְ</a>. <span class=\"citation\">Midr. Till. to Ps. LXVIII</span>, <span dir=\"rtl\">ולא היו קִצְרֵי יד בו</span> they were not short-handed with it, i.e. they did not have to economize. <span class=\"citation\">Midr. Till. to Ps. CXIX, 81</span> <span dir=\"rtl\">אתה ארך אפים ואנו קְצֵירֵי רוח</span> thou art long-suffering, but we are hasty of spirit; a. e.—V. <a href=\"#\" data-headword=\"קְצָרָה\">קְצָרָה</a>.</div>","alt":[]},"27413":{"h":"קַצָּר","r":"S01847","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצֵר\">preced.</a> wds.) [<i>one who causes shrinking</i>,] <i>fuller, washer</i>. <span class=\"citation\">Targ. Josh. XV, 7</span>, a. e. <span dir=\"rtl\">עין ק׳</span> (h. text <span dir=\"rtl\">עֵין רֹגֵל</span>) the washer’s well.—<span class=\"citation\">Y. Ber. IV, 7ᵈ</span> top (Bab. <span class=\"citation\">ib. 28ᵃ</span> <a href=\"#\" data-headword=\"כּוֹבֵס\">כובס</a>); a. fr.—<span class=\"citation\">B. Kam. 119ᵇ</span> <span dir=\"rtl\">ק׳ שמיה וק׳ שקיל ליה</span> a fuller is named <i>ḳatsra</i> (a shortener), let the <i>ḳatsra</i> take it (the dark border of a white cloth belongs to the fuller).—Pl. <span dir=\"rtl\">קַצְרַיָּא</span>, <span dir=\"rtl\">קַצְרֵי</span>. <span class=\"citation\">Targ. I Sam. XIII, 21</span>. <span class=\"citation\">Targ. Is. VII, 3</span> (ed. Wil. <span dir=\"rtl\">קציר׳</span>, corr. acc.).—<span class=\"citation\">Snh. 92ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"אוּבְלָא II\"><span dir=\"rtl\">אוּבְלָא</span> II</a>. <span class=\"citation\">Taan. 29ᵇ</span> <span dir=\"rtl\">בטלי ק׳ דבי רב</span> the fullers of the house of Rab are idle (during the week preceding the ninth of Ab); a. e.</div>","alt":["קַצְרָא I"]},"27414":{"h":"קַצְרָא II","r":"S01848","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"קַצָּר\">preced.</a>) pr. n. m. <i>Ḳatsra</i> (<i>Fuller</i>). <span class=\"citation\">Y. Kil. IX, 32ᵇ</span>; <span class=\"citation\">Y. Keth. XII, 35ᵃ</span>; <span class=\"citation\">Koh. R. to VII, 11</span>.—<span class=\"citation\">Esth. R. to I, 13</span> <span dir=\"rtl\">ר׳ יוסי בר ק׳</span> (some ed. <a href=\"#\" data-headword=\"קַצְרַת\">קַצְרַת</a>); <span class=\"citation\">Gen. R. s. 72</span> <span dir=\"rtl\">בן קוצרי</span>; <span class=\"citation\">Cant. R. to VI, 4</span> <span dir=\"rtl\">בר קסרין</span>; Pesik. Vayhi, p. 9ᵃ <span dir=\"rtl\">ר׳ יוסי ובר קצה</span> (corr. acc.). <span class=\"citation\">Y. B. Bath. X, 17ᶜ</span> <span dir=\"rtl\">ר׳ יסא קוצירא</span>. <span class=\"citation\">Sabb. 151ᵇ</span> bot. <span dir=\"rtl\">ר׳ יוסי בן קְצַרְתָּה</span> (Ms. M. <a href=\"#\" data-headword=\"קַצְרַת\">קצרתא</a>). Midr. Sam. ch. XXVI <span dir=\"rtl\">ר׳ יצחק בר קצרתה</span>; <span class=\"citation\">Y. R. Hash. I, 56ᵇ</span> <span dir=\"rtl\">בר קצצתה</span>.</div>","alt":["קַצְרָה I"]},"27415":{"h":"קַצְרָא III","r":"S01849","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"קַסְטְרָא\">קַסְטְרָא</a>, <i>fort, camp</i>. <span class=\"citation\">Arakh. IX, 6</span>, v. <a href=\"#\" data-headword=\"צִיפּוֹרֵי\">צִיפּוֹרֵי</a>; <span class=\"citation\">Y. Sabb. XVI, end, 15ᵈ</span> (not <a href=\"#\" data-headword=\"קיצרה\">קיצרה</a>). <span class=\"citation\">Y. Shek. VIII, beg. 51ᵃ</span> <span dir=\"rtl\">קַצְרָן של גוים היה שם</span> (some ed. <a href=\"#\" data-headword=\"קַצְרִים\">קַצְרִין</a>, v. Rabb. D. S. a. l. note 60) a camp of gentiles (Romans) was there, [comment. <i>a fuller</i>, v. <a href=\"#\" data-headword=\"קַצָּר\">קַצָּר</a>). <span class=\"citation\">Num. R. s. 18</span> (ref. to <span dir=\"rtl\">הקם על</span>, <span class=\"citation\">II Sam. XXIII, 1</span> [read:] <span dir=\"rtl\">שהקים עולה של תורה בעולה של קצרה</span> he (David) restored the yoke (rulership) of the Law through the yoke of the camp (used his military power to restore the government of the Law; Midr. Sam. ch. XXIX <span dir=\"rtl\">קיים … בעילה של מלכות</span>).—Pl. <a href=\"#\" data-headword=\"קַצְרִים\">קַצְרִים</a>, <a href=\"#\" data-headword=\"קַצְרִים\">קַצְרִין</a>; Chald. <span dir=\"rtl\">קַצְרַיָּא</span> (with sing. meaning). Y. Erub. V, 22ᵇ bot. <span dir=\"rtl\">את רואה … והק׳ … לאיצטדין ובית מעון … לק׳</span> consider the ruins (near Tiberias, v. <a href=\"#\" data-headword=\"אִיצְטַדִּין\">אִיצְטַדִּין</a>) as if they were inhabited buildings, and the fort is within seventy odd cubits near the ruins, and Beth Maon is within seventy odd cubits near the fort (by which calculation Beth Maon and Tiberias may be considered one township, v. <a href=\"#\" data-headword=\"עָבַר\">עָבַר</a> <i>Pi.</i> 4). Y. Shek. l. c., v. supra. Y. Shebi. VI, 36ᶜ <span dir=\"rtl\">ק׳ דגליל</span> (not <span dir=\"rtl\">קציריא</span>) the Fort of Gelil (v. Hildesh. Beitr. Geogr. p. 17, sq.); <span class=\"citation\">Tosef. Shebi. IV, 11</span> <a href=\"#\" data-headword=\"קַצְטְרָא\">קַצְטְרָא</a> (Var. <span dir=\"rtl\">קצטרי</span>); <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">קצרא דגלילא</span>; <span class=\"citation\">Yalk. ib. 874</span> <span dir=\"rtl\">ק׳ רגליא</span> (corr. acc.).—Trnsf. <a href=\"#\" data-headword=\"קַצְרִים\">קַצְרִים</a> <i>wax-cells in the honeycomb</i>. <span class=\"citation\">Cant. R. to I, 2</span> <span dir=\"rtl\">מה דבש יש בו ק׳ וכ׳</span> as there are wax-cells (unenjoyable parts) in the honey, so you might think the same was the case with the Law.</div>","alt":["קַצְרָה II"]},"27416":{"h":"קְצָרָה","r":"S01850","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  fem. of <a href=\"#\" data-headword=\"קָצֵר\">קָצֵר</a>.</div><div class=\"sense\"><b>—2)</b> <i>short board, the board at the head and at the foot of the bed</i>, opp. <a href=\"#\" data-headword=\"אֲרוּכָה I\">אֲרוּכָה</a>. <span class=\"citation\">Kel. XVIII, 5</span>; a. e.</div><div class=\"sense\"><b>—3)</b>  <span dir=\"rtl\">רוח ק׳</span>, v. <a href=\"#\" data-headword=\"קַצְרוּת\">next w.</a></div>","alt":[]},"27417":{"h":"קַצְרוּת","r":"S01851","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְצָרָה\">preced.</a>) <span dir=\"rtl\">רוח ק׳</span> <i>asthma</i>, or <i>incubus</i> [or <i>nervous prostration</i>,] believed to be caused by a demon, Ben N’filim. <span class=\"citation\">Bekh. VII, 5</span> (<span class=\"citation\">44ᵇ</span>) <span dir=\"rtl\">רוח קצרית באה עליו</span> Mish. (Bab. ed. <a href=\"#\" data-headword=\"קְצָרָה\">קצרה</a>) a person subject to asthmatic spells (is unfit for priesthood). Ib. 44ᵇ <span dir=\"rtl\">רוח קצרות</span>, v. <a href=\"#\" data-headword=\"נָאלָא I\">נָאלָא</a> II a. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a>.</div>","alt":["קַצְרִית"]},"27418":{"h":"קַצְרִים","r":"S01852","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַצְרָא III\"><span dir=\"rtl\">קַצְרָה</span> II</a></div>","alt":["קַצְרִין","קַצְרָן"]},"27419":{"h":"קַצְרָן","r":"S01853","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָצַר\">קָצַר</a>) <i>one who gives short prayers</i>, opp. <a href=\"#\" data-headword=\"אַרְכָן I\">אַרְכָן</a>. <span class=\"citation\">Ber. 34ᵃ</span>; Mekh. B’shall, Vayassʿa, s. 1.</div>","alt":[]},"27420":{"h":"קצרן","r":"S01854","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Gen. 133</span> <span dir=\"rtl\">והוה ק׳</span>, read: <span dir=\"rtl\">מְקַצֵּץ</span>, v. <a href=\"#\" data-headword=\"קְצוּצְתָּא\">קְצוּצְתָּא</a></div>","alt":[]},"27421":{"h":"קְצִרְקְטוֹן","r":"S01855","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְסִרְקִיטוֹן\">קְסִרְקִיטוֹן</a></div>","alt":["קצרקטין"]},"27422":{"h":"קַצְרַת","r":"S01856","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַצְרָא II\"><span dir=\"rtl\">קַצְרָא</span> II</a>; [prob. pr. n. f. <i>Fuller Woman</i>].</div>","alt":["קְצַרְתָּא","קְצַרְתָּה"]},"27423":{"h":"קְצָת","r":"S01857","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>end.</i>—Pl. <a href=\"#\" data-headword=\"קְצָווֹת\">קְצָווֹת</a>; constr. <a href=\"#\" data-headword=\"קְצָווֹת\">קִצְווֹת</a>. Tanḥ. Vayesheb 2 <span dir=\"rtl\">לק׳ המדבר</span> to the ends of the desert.—V. <a href=\"#\" data-headword=\"מִקְצָת\">מִקְצָת</a>.</div>","alt":[]},"27424":{"h":"קְצַת","r":"S01858","html":"<div class=\"sense\"><b>1)</b> <i>part.</i> <span class=\"citation\">Targ. O. Num. XXII, 41</span>. <span class=\"citation\">Targ. Job IV, 12</span>. <span class=\"citation\">Targ. Gen. XLVII, 2</span> ed. Bon. (oth. ed. <a href=\"#\" data-headword=\"מִקְצָת\">מקצת</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>extreme end</i>. Targ. Y. Num. l. c.</div>","alt":["קְצָת"]},"27425":{"h":"קָקָא","r":"S01859","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"קָאָת\">קָאָת</a>, <i>pelican</i>. <span class=\"citation\">Targ. Y. Lev. XI, 18</span>; <span class=\"citation\">Deut. XIV, 17</span>.—<span class=\"citation\">Targ. Ps. CII, 7</span> <span dir=\"rtl\">קקתא</span> ed. Lag. (oth. ed. <span dir=\"rtl\">קאתא</span>).—[<span class=\"citation\">Ber. 20ᵃ</span>, a. e. <span dir=\"rtl\">קָקֵי</span> Ar., v. <a href=\"#\" data-headword=\"קָאקָא\">קָאקָא</a>.]</div>","alt":["קָקְתָא"]},"27426":{"h":"*קַקָּא","r":"S01860","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">נקק</span>, cmp. <a href=\"#\" data-headword=\"נָקִיק\">נָקִיק</a>) = <a href=\"#\" data-headword=\"קוֹעָא\">קוֹעָא</a>, <i>throat, neck</i>. <span class=\"citation\">Taan. 24ᵃ</span> שדו ליה … בקַקּיה Ar. (ed. <span dir=\"rtl\">רמו … בצואריה</span>) they put a cloth into his throat (or around his neck, to torture him).</div>","alt":[]},"27427":{"h":"קקבטון","r":"S01861","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַקּוּבִּיטוֹן\">אַקּוּבִּיטוֹן</a></div>","alt":["קקבטין"]},"27428":{"h":"קָקוֹ","r":"S01862","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*פְּדִיפְטֵי\">פְּדִיפְטֵי</a></div>","alt":["ק׳ פדיפטי"]},"27429":{"h":"קַקְוַאי","r":"S01863","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> name of an unclean <i>bird</i>. <span class=\"citation\">Ḥull. 63ᵃ</span> (Ms. R. 3 <span dir=\"rtl\">קקנאי</span>, v. Rabb. D. S. a. l. note 10).</div>","alt":[]},"27430":{"h":"קַקְוָאתָא","r":"S01864","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּקְיָיאתָא\">קוּקְיָיאתָא</a></div>","alt":[]},"27431":{"h":"קָקוּזִית","r":"S01865","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָקוּזְתָּא\">next w.</a></div>","alt":["קָקוּזִיתָא"]},"27432":{"h":"קָקוּזְתָּא","r":"S01866","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\">(?) <i>Ḳaḳuzta</i>. <span class=\"citation\">Sabb. 156ᵃ</span> <span dir=\"rtl\">דימי בר ק׳</span> (Ms. O. <a href=\"#\" data-headword=\"קָקוּזִית\">קָקוּזִית</a>; early ed. <a href=\"#\" data-headword=\"קָקוּזִית\">קָקוּזִיתָא</a>; v. Rabb. D. S. a. l. note 20).</div>","alt":[]},"27433":{"h":"קָקוּלָא","r":"S01867","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">קָקוּלֵי</span>, <span dir=\"rtl\">קָקוּלִין</span> (= <span dir=\"rtl\">קלקול׳</span>; <span dir=\"rtl\">קלל</span>) a sort of <i>cress</i> used by the poor (cardamum or nasturtium, Löw, Pfl. 349). <span class=\"citation\">Y. Erub. III, 20ᵈ</span> top; <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> top, expl. <a href=\"#\" data-headword=\"פַּעְפּוּעִין\">פעפועין</a>.—<span class=\"citation\">Pes. 114ᵃ</span> (prov.) <span dir=\"rtl\">דאכיל אליתא טשי בעליתא דאכיל קקולי אקיקלי וכ׳</span> (Ms. M. <span dir=\"rtl\">קילקולא אקילקולי</span>) he that eats fat-tail will have to hide himself (before his creditors) in the loft, who eats cress may rest quietly by the dunghill of the town.</div>","alt":[]},"27434":{"h":"קקונאי","r":"S01868","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּרְקוּנְיָא\">קוּרְקוּנְיָא</a></div>","alt":["קקוניא"]},"27435":{"h":"קקיס","r":"S01869","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to III, 4</span>, v. <a href=\"#\" data-headword=\"*באמי\">באמי</a></div>","alt":[]},"27436":{"h":"קִקְלָא","r":"S01870","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִיקְלָא\">קִיקְלָא</a>, <a href=\"#\" data-headword=\"קִיקֶלְתָּא\"><a href=\"#\" data-headword=\"קִיקֶלְתָּא\">קִיקֶלְתָּא</a>.</a></div>","alt":["קִקְלְתָא"]},"27437":{"h":"קָקְתָא","r":"S01871","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָקָא\">קָקָא</a></div>","alt":[]},"27438":{"h":"קַר","r":"S01872","html":"<div class=\"sense\"><i>to be cold</i>, v. <a href=\"#\" data-headword=\"קָרַר II\"><span dir=\"rtl\">קָרַר</span> II</a>, <a href=\"#\" data-headword=\"קָרַר II\"><span dir=\"rtl\">קְרַר</span> II</a>.—[<span class=\"citation\">Erub. X, 14</span>, a. e. <span dir=\"rtl\"><span dir=\"rtl\">באר</span> (<span dir=\"rtl\">בור</span>) <span dir=\"rtl\">הקר</span></span>, v. <a href=\"#\" data-headword=\"הָקֵר\">הָקֵר</a>.]</div>","alt":[]},"27439":{"h":"קָרָא I","r":"S01873","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְרַר II) <i>pumpkin, gourd</i>. <span class=\"citation\">Succ. 56ᵇ</span>; <span class=\"citation\">Keth. 83ᵇ</span>, a. e. <span dir=\"rtl\">טב מק׳</span>, v. <a href=\"#\" data-headword=\"בּוּצִין\">בּוּצִין</a>. <span class=\"citation\">Yoma 78ᵃ</span> <span dir=\"rtl\">מצטנן בק׳</span> cooled his hands with a pumpkin. <span class=\"citation\">Ker. 6ᵃ</span>; <span class=\"citation\">Hor. 12ᵃ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"קְרֵי I\">קָרֵי</a>, <a href=\"#\" data-headword=\"קַרְיָא I\">קָרַיָּא</a>. <span class=\"citation\">Meg. 12ᵃ</span>, v. <a href=\"#\" data-headword=\"בּוּצִין\">בּוּצִין</a>; <span class=\"citation\">Sot. 10ᵃ</span> <a href=\"#\" data-headword=\"קָאֲרִי\">קָארֵי</a>. <span class=\"citation\">Ned. 51ᵃ</span> Rashi (ed. <span dir=\"rtl\">קרא</span>, corr. acc.). <span class=\"citation\">B. Mets. 64ᵃ</span> <span dir=\"rtl\">ק׳ בני זרתא</span> pumpkins of the size of a fist. <span class=\"citation\">B. Bath. 88ᵃ</span> <a href=\"#\" data-headword=\"קָאֲרִי\">קארי</a>. <span class=\"citation\">Sabb. 129ᵇ</span> <span dir=\"rtl\">מאה ק׳</span>, v. <a href=\"#\" data-headword=\"קְרַן II\"><span dir=\"rtl\">קַרְנָא</span> I</a>; a. e.—<span dir=\"rtl\">קָרַיָּיא וְקָרָוָותָא</span> large and small gourds, <i>all kinds of gourds</i>. <span class=\"citation\">Y. Ned. VII, beg. 40ᵇ</span> (not <span dir=\"rtl\">וכרובתא</span>); <span class=\"citation\">Y. Orl. III, 63ᵇ</span> top <span dir=\"rtl\">קירייא וקרותוא</span> (corr. acc.).</div>","alt":[]},"27440":{"h":"קָרָא II","r":"S01874","html":"<div class=\"sense\"><i>to call</i>, v. <a href=\"#\" data-headword=\"קרי\">קרי</a>.</div>","alt":[]},"27441":{"h":"קְרָא I","r":"S01875","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"קְרֵי I\">קְרֵי</a></div>","alt":[]},"27442":{"h":"קְרָא II","r":"S01876","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרָא I\">preced.</a>) = h. <a href=\"#\" data-headword=\"מִקְרָא\">מִקְרָא</a>, <i>Biblical verse</i>. <span class=\"citation\">Targ. Esth. VI, 1</span>.—<span class=\"citation\">Ber. 2ᵃ</span> <span dir=\"rtl\">אק׳ קאי</span>, v. <a href=\"#\" data-headword=\"קָאֵי\">קָאֵי</a>. <span class=\"citation\">Ib. 27ᵃ</span> <span dir=\"rtl\">אמר ק׳ וכ׳</span> the text reads <i>babboḳer</i> &amp;c. <span class=\"citation\">Ib. 29ᵇ</span> <span dir=\"rtl\">מאי קראה</span> where is the Biblical passage to prove it? <span class=\"citation\">Snh. 45ᵇ</span>; <span class=\"citation\">71ᵃ</span>, a. e. <span dir=\"rtl\">בעינן ק׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"כְּתַב I\"><span dir=\"rtl\">כְּתַב</span> I</a>. <span class=\"citation\">Ker. 11ᵇ</span> bot. <span dir=\"rtl\">ק׳ בעי</span> do we need a Bible verse for it?; a. v. fr.—<span class=\"citation\">Ber. 30ᵇ</span> <span dir=\"rtl\">פוק קרא קְרָאָיךְ לברא</span> go out, read thy verse in the street, i.e. thy authority is not recognized at college; <span class=\"citation\">Keth. 56ᵃ</span>; <span class=\"citation\">Yeb. 40ᵃ</span> <span dir=\"rtl\">קַרְיָיךְ</span>, v. <a href=\"#\" data-headword=\"קַרְיָיא\">קַרְיָיא</a>.—Pl. <a href=\"#\" data-headword=\"קְרָאִי\">קְרָאֵי</a>. <span class=\"citation\">M. Kat. 3ᵇ</span> <span dir=\"rtl\">והני … ק׳ נינהו</span> are these traditional rulings? are they not intimated in the Biblical text? <span class=\"citation\">Pes. 4ᵇ</span> <span dir=\"rtl\">תרי ק׳ כתיבי</span> there are two verses (seemingly contradictory); a. v. fr.</div>","alt":["קְרָאָה"]},"27443":{"h":"קַרָא","r":"S01877","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרָא II\">preced.</a>) <i>a Biblical scholar, Bible teacher</i>. <span class=\"citation\">Kidd. 49ᵃ</span> <span dir=\"rtl\">אבל אמר לה ק׳ אנא וכ׳</span> but if he said to her, (thou art betrothed unto me under the condition that) I am a Biblical scholar, she is not betrothed unless he can read the Pentateuch, Prophets and Hagiographa correctly (understandingly), contrad. to <a href=\"#\" data-headword=\"קַרְיָנָא\">קַרְיָנָא</a>. <span class=\"citation\">Ber. 30ᵇ</span>, a. e. <span dir=\"rtl\">ר׳ חנינא ק׳</span> R. Ḥanina, the Bible teacher.—<i>Pl.</i> (h. form) <span dir=\"rtl\">קַרָאִים</span>; (ch.) <a href=\"#\" data-headword=\"קְרָאִי\">קַרָאֵי</a>. Pesik. Shubah, p. 165ᵇ <span dir=\"rtl\">ק׳ טובים וכ׳</span> good Bible teachers, good preachers, like Levi &amp;c.; <span class=\"citation\">Yalk. Hos. 533</span>. <span class=\"citation\">Ab. Zar. 40ᵃ</span> <span dir=\"rtl\">מתלתא ק׳ שמיע לי</span> (Ar. <span dir=\"rtl\">קיראי</span>) I have it from three authorities (as reliable as the Scriptures, Rashi).—V. <a href=\"#\" data-headword=\"קַרָיָיא\">קַרָיָיא</a>.—[<span class=\"citation\">Meg. 24ᵇ</span> in Mish. <span dir=\"rtl\">דרך הקראים</span>, a censorial change for <span dir=\"rtl\">המינות</span>, as in Mish. ed. IV, 8, a. Ms. M., v. Rabb. D. S. a. l.—In later literature <span dir=\"rtl\">קראים</span> <i>Karaites</i>, a Jewish sect recognizing the Bible as sole authority.]</div>","alt":[]},"27444":{"h":"קְרָאָה","r":"S01878","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרָא II\"><span dir=\"rtl\">קְרָא</span> II</a></div>","alt":[]},"27445":{"h":"קְרָאוֹי","r":"S01879","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרָיָיא\">קַרָיָיא</a></div>","alt":[]},"27446":{"h":"קראות","r":"S01880","html":"<div class=\"sense\">, <span class=\"citation\">Y. Meg. IV, 74ᵈ</span>, v. <a href=\"#\" data-headword=\"קְרוּיוֹת\">קְרוּיוֹת</a></div>","alt":[]},"27447":{"h":"קראטוסם","r":"S01881","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרָטִיסִין\">קְרָטִיסִין</a></div>","alt":["קראטיסים"]},"27448":{"h":"קְרָאִי","r":"S01882","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶקְרָאִי\">אֶקְרָאִי</a>. <span class=\"citation\">R. Hash. 29ᵇ</span> דק׳ Ar.</div>","alt":["קְרַאי"]},"27449":{"h":"קָרֵב","r":"S01883","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to join, come near, be near; to be offered as</i> <a href=\"#\" data-headword=\"קָרְבָּן\">קָרְבָּן</a>. <span class=\"citation\">Zeb. VIII, 2</span> <span dir=\"rtl\">יִקְרַב לשם מי שהוא</span> let it be offered in behalf of him to whom it may belong. <span class=\"citation\">Ib. 5</span> <span dir=\"rtl\">אם ק׳ … יִקְרְבוּ וכ׳</span> if one of the heads has been offered, let all of them be offered. <span class=\"citation\">Ib. 67ᵇ</span>; <span class=\"citation\">Ḳinnim III, 3</span> <span dir=\"rtl\">חטאת קְרֵיבָה למעלה וכ׳</span> the sin-offering may have been offered on top and the burnt-offering beneath it. <span class=\"citation\">Men. VI, 1</span> <span dir=\"rtl\">הקומץ ק׳ … קְרֵבִים לעצמן</span> the handful (of the priests’ meal-offering) is offered separately and the remainder separately; <span class=\"citation\">Y. Sot. III, 19ᵇ</span> top <span dir=\"rtl\">קְרֵיבִין</span>. <span class=\"citation\">Sifré Num. 29</span> <span dir=\"rtl\">קבע זמן לקריבים … למקריבים</span> a time is fixed for the things to be offered (<span class=\"citation\">Lev. XXII, 27</span>), and a time for those who offer (<span class=\"citation\">Num. VI, 10</span>); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to come before court; to sue, complain</i>. <span class=\"citation\">Gen. R. s. 96</span> (ref. to <span dir=\"rtl\">ויקרבו</span>, <span class=\"citation\">Gen. XLVII, 29</span>) <span dir=\"rtl\">כאדם … ק׳ על וכ׳</span> as one says, that man has brought suit against his neighbor, v. <a href=\"#\" data-headword=\"קָבַל II\"><span dir=\"rtl\">קָבַל</span> II</a>; Yalk. ib. 156 <span dir=\"rtl\">קבל</span> (corr. acc.).</div><div class=\"sense\"><b>Pi. קֵירֵב</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"קְרָאִי\">same</a>, <a href=\"#\" data-headword=\"קְרָאִי\">same</a>, <i>to come near</i>. <span class=\"citation\">Ex. R. s. 20</span>, beg. <span dir=\"rtl\">לא קי׳ אצל וכ׳</span> he had not come near Sarah.—Esp. <i>to approach; to pray, intercede, mediate, conciliate</i>. Y. Ber. IV, 8ᵇ top <span dir=\"rtl\">זה שעובר … בא וקָרֵב עשה קרבנינו וכ׳</span> we do not say to him who is to pass before the ark (v. <a href=\"#\" data-headword=\"תֵּיבָה\">תֵּיבָה</a></div><div class=\"sense\"><b>—2)</b> <i>to bring near; to befriend, attract, invite</i>. <span class=\"citation\">B. Kam. 24ᵃ</span> <span dir=\"rtl\">ק׳ נגיחותיו</span> if the ox did his gorings in near intervals (of less than three days). <span class=\"citation\">Eduy. VIII, 7</span> אין אליהו … לרחק ולְקָרֵב … המְקוֹרָבִין בזרוע וכ׳ Elijah shall come not to decide between clean and unclean, nor to expel (declare genealogically degraded) and to receive (reinstate), but to expel those who have been received by force, and to reinstate those who have been expelled by force. Ib. <span dir=\"rtl\">משפחת … וקֵרְבָהּ בן וכ׳</span> there was a family … which Ben-Zion expelled by force, and another which they received by force (Bab. ed. <span dir=\"rtl\">וקֵרְבוּהָ בני וב׳</span>; v. Rabb. D. S. a. l. note 40); Tosef. ib. III, 4; <span class=\"citation\">Kidd. 71ᵃ</span>. Eduy. l. c. <span dir=\"rtl\">לא לרחק ולא לקרב וכ׳</span> neither to expel nor to reinstate, but to make peace &amp;c. <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">קֵירְבָנוּ תחת וכ׳</span>, v. <a href=\"#\" data-headword=\"עִנְוְתָנוּת\">עִנְוְתָנוּת</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שקֵרַבְתַּנִי וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">שהקרבתני</span>) thou hast brought us near &amp;c. Tanḥ. Tsav 8 (ref. to <span class=\"citation\">Ps. LXV, 5</span>) <span dir=\"rtl\">אשרי מי שבחרו … קֵרְבוֹ</span> blessed he whom the Lord has chosen, although he did not bring him near; <span class=\"citation\">Num. R. s. 3</span> <span dir=\"rtl\">הקריבו</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ את עצמו</span> he brought himself near (to God, through his own deeds); <span class=\"citation\">ib.</span> <span dir=\"rtl\">יתרו קרבו הקב&quot;ה</span> the Lord brought Jethro near (caused him to be converted); <span class=\"citation\">Yalk. Ex. 379</span>; a. fr.—<span class=\"citation\">Sifré Num. 94</span> (expl. <span dir=\"rtl\">לזרא</span>, <span class=\"citation\">Num. XI, 20</span>, cmp. <a href=\"#\" data-headword=\"זָר\">זָר</a>) <span dir=\"rtl\">שתהיו מרחיקים … מְקָרְבִים אותו</span> you will keep it at a distance (loathe it) more than you have been inviting (wishing for) it; Lev. R. s. 48.—Part. pass. <a href=\"#\" data-headword=\"מְקוֹרָא\">מְקוֹרָב</a>; pl. <span dir=\"rtl\">מְקוֹרָבִין</span>, v. supra.</div></div><div class=\"sense\"><b>Hif. הִקְרִיב</b> <div class=\"sense\"><b>1)</b> <i>to bring near, receive</i>. Y. Dem. II, 23ᵃ top <span dir=\"rtl\">מַקְרִיבִין לכנפים</span>, v. <a href=\"#\" data-headword=\"כָּנָף\">כָּנָף</a>. Num. R. l. c.; Sabb. l. c., v. supra; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to offer, sacrifice</i>. <span class=\"citation\">Men. XIII, 10</span> <span dir=\"rtl\">יַקְרִיבֶנָּה במקדש</span> he must offer it in the Temple (of Jerusalem), <span dir=\"rtl\">ואם הִקְרִיבָהּ וכ׳</span> but if he offered it in the Temple of Ḥonyo (in Egypt). <span class=\"citation\">Zeb. 67ᵇ</span> <span dir=\"rtl\">ותַקְרִיבֶנָּה למעלה</span> and let her offer it on top, (v. supra Kal); <span class=\"citation\">Kinn. III, 6</span> ויַקְרִיבֶנָּה וכ׳ Mish. (Bab. ed. <span dir=\"rtl\">ויקרבנה</span>, corr. acc.) and he (the priest) must offer it &amp;c. <span class=\"citation\">Ber. 6ᵇ</span> <span dir=\"rtl\">כאילו ה׳ תודה</span> as if he had offered a thank-offering. <span class=\"citation\">Ib. 17ᵃ</span> as long as the Temple stood <span dir=\"rtl\">אדם חוטא ומַקְרִיב וכ׳</span> a man sinned and brought a sacrifice; <span dir=\"rtl\">ואין מקריבין וכ׳</span> yet only its fat and its blood were offered; <span dir=\"rtl\">כאילו הִקְרַבְתִּיו לפניך וכ׳</span> as if I had offered it (my fat and blood) on the altar before thee; a. v. fr.</div></div><div class=\"sense\"><b>Nif. נִקְרַב</b> <div class=\"sense\"><i>to be offered</i>. Y. Meg. I, 70ᶜ top <span dir=\"rtl\">ונִקְרְבוּ מהן וכ׳</span> and from their contributions was taken the wood for sacrifices; (Y. Taan. IV, 68ᵇ; Y. Shek. IV, beg. 47ᵈ <span dir=\"rtl\">וקרבו</span>).</div></div><div class=\"sense\"><b>Hithpa. הִתְקָרֵב</b> </div><div class=\"sense\"><b>Nithpa. נִתְקָרֵב</b> <div class=\"sense\"><b>1)</b> <i>to be brought near, be received</i>. <span class=\"citation\">Num. R. s. 3</span> <span dir=\"rtl\">יש נבחר ונדחה ונ׳ וכ׳</span> some are chosen and repelled (disgraced) and received again &amp;c. Sifra Tsav, Milluïm <span dir=\"rtl\">ידע משה שנ׳ אהרן</span> Moses learned that Aaron was received again (in grace); <span class=\"citation\">Yalk. Lev. 515</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be offered, sacrificed</i>. Y. Taan. l. c. <span dir=\"rtl\">שלא יהא קרבן מִתְקָרֵב וכ׳</span> that none but their contributions should be offered first. <span class=\"citation\">Pirké d’R. El. ch. XXXI</span> <span dir=\"rtl\">אותו האיל … ובא להִתְקָרֵב וכ׳</span> that ram … ran and came to offer himself as a sacrifice in place of Isaac &amp;c.; <span class=\"citation\">Yalk. Gen. 101</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to claim relationship</i>. <span class=\"citation\">Deut. R. s. 2</span> <span dir=\"rtl\">אם קרובו עני … פלוני מתקרב לי</span> if a man’s relative is poor, he makes himself the main person and him subordinate, saying, this man claims relationship to me; Y. Ber. IX, 13ᵇ (in mutilated text) <span dir=\"rtl\">ההן פלן מתקרב לן</span>.</div></div>","alt":[]},"27450":{"h":"קְרֵב","r":"S01884","html":"<div class=\"sense\"><b>1)</b> <i>to be near, come near, touch</i>. <span class=\"citation\">Targ. Num. XXVII, 1</span>. <span class=\"citation\">Targ. Ex. XXXVI, 2</span>. <span class=\"citation\">Targ. I Kings II, 1</span>; a. fr.—Pesik. Zakhor, p. 24ᵇ <span dir=\"rtl\">קריב לגביה</span>, v. <a href=\"#\" data-headword=\"בָּלַם II\"><span dir=\"rtl\">בָּלַם</span> II</a>. <span class=\"citation\">Eduy. VIII, 4</span> <span dir=\"rtl\">דיִקְרַב במיתא</span> he who touches a corpse; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to intercede, protect</i>. <span class=\"citation\">Y. Dem. I, 22ᵃ</span> <span dir=\"rtl\">בני קרתי קוֹרְבִין לי</span> (not <span dir=\"rtl\">קרתיה</span>) fellow-citizens, protect me!; <span dir=\"rtl\">בני דודי קורבין לי</span> (not <span dir=\"rtl\">דידי</span>) children of my friend (the Lord), protect you me!; <span class=\"citation\">Y. Taan. III, 66ᶜ</span> top <span dir=\"rtl\">בני דילי וכ׳</span> (corr. acc.).</div><div class=\"sense\"><b>—3)</b> <i>to complain, sue</i>. Y. B. Bath. IX, beg. 16ᵈ <span dir=\"rtl\">אתון בנוי קַרְבוּן וכ׳</span> his sons came and complained before R. E. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אתת וקְרֵיבָה וכ׳</span></div><div class=\"sense\"><b>—4)</b> <i>to bring near; to offer</i>, v. infra.</div><div class=\"sense\"><b>Pa. קָרֵיב  קָרֵב</b> <div class=\"sense\"><b>1)</b> <i>to bring near; to offer</i>. <span class=\"citation\">Targ. Gen. XLVIII, 9</span>, sq. <span class=\"citation\">Ib. 13</span> (Y. ed. Vien. <a href=\"#\" data-headword=\"קְרֵיב\">קְריב</a>; h. text <span dir=\"rtl\">ויַּגֵּשׁ</span>). <span class=\"citation\">Targ. Is. LVIII, 3</span> (h. text <span dir=\"rtl\">תִּנְגּשׁוֹּ</span>!). <span class=\"citation\">Targ. O. Lev. I, 2</span> <span dir=\"rtl\">יְקָרֵיב</span> (Y. <span dir=\"rtl\">יִקְרַב</span>). Ib. 3 (Y. <span dir=\"rtl\">יַקְרִיב</span> <i>Af.</i>). Ib. 14 (Y. also <span dir=\"rtl\">יַקְרִיב</span>); a. fr.—<span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">סבור רבנן לקָרוּבֵיה</span> the rabbis were of the opinion that it should be offered. Y. Ber. IX, 13ᵈ top <span dir=\"rtl\">הוה … אתי למִיקָרְבָה וכ׳</span> (or <span dir=\"rtl\">למִיקְרְבָה</span>) when a man came to offer, to the idol, an ox &amp;c. Y. Snh. X, 29ᵇ <span dir=\"rtl\">מְקָרְבָא לגיחזי</span> to bring Gehazi near (befriend him again). <span class=\"citation\">Num. R. s. 3</span> <span dir=\"rtl\">אלהכון מאן הוא בעי מְקָרֵיב</span> does your God bring near him (grace) whomever he chooses to? <span class=\"citation\">B. Bath. 168ᵃ</span> <span dir=\"rtl\">אפי׳ צורבא … לְקָרוּבֵיה</span> even in the case of a young scholar whom it may be supposed his intended father-in-law likes to bring into his family; a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְקָרַב</span>; f. <a href=\"#\" data-headword=\"מִקְרְבָא\">מְקָרְבָא</a>, <span dir=\"rtl\">מְקָרְבָה</span>; pl. <span dir=\"rtl\">מְקָרְבִין</span>; <span dir=\"rtl\">מְקָרְבָן</span> <i>near, friendly</i>. <span class=\"citation\">Sabb. 104ᵃ</span> <span dir=\"rtl\">מ&quot;ט שקר ק׳ מיליה אמת וכ׳</span> why are the letters of <a href=\"#\" data-headword=\"שְׁקַר I\">שקר</a> (falsehood) near together (in the order of the alphabet), and those of <a href=\"#\" data-headword=\"אֱמֶת\">אמת</a> (truth) far apart? <span class=\"citation\">Snh. 29ᵃ</span> <span dir=\"rtl\">מק׳ דעתיה</span> he is friendly, v. <a href=\"#\" data-headword=\"רָחַק\">רְחַק</a>.—3) <i>to intercede, lead in prayer</i>. <span class=\"citation\">Midr. Till. to Ps. XIX</span> <span dir=\"rtl\">חזיוה לחזנא דקָרֵיב וכ׳</span></div></div><div class=\"sense\"><b>Af. אַקְרֵיב</b> <div class=\"sense\"><i>to bring near; to offer</i>. <span class=\"citation\">Targ. Mal. II, 12</span>; a. fr.—Gitt. l. c. <span dir=\"rtl\">אי מַקְרְבִין ליה</span> (or <span dir=\"rtl\">מְקָרְבִין</span> <i>Pa.</i>), v. <a href=\"#\" data-headword=\"קָרְבַּן\">קָרְבַּן</a>. <span class=\"citation\">Ḥag. 8ᵇ</span> <span dir=\"rtl\">האי דלא אַקְרְבִינְהוּ וכ׳</span> the reason why they did not offer them was &amp;c.; a. fr.—<span class=\"citation\">Yeb. 39ᵇ</span> <span dir=\"rtl\">איקרבת ית וכ׳</span> (read: <span dir=\"rtl\">אַקְרִיבַת</span></div></div><div class=\"sense\"><b>Ithpa. אִתְקָרֵיב</b> </div><div class=\"sense\"><b>Ithpe. אִתְקְרִיב  אִיקְּרִיב</b> <div class=\"sense\"><b>1)</b> <i>to approach, come near</i>. <span class=\"citation\">Targ. Y. Deut. XX, 3</span>; O. ib. ed. Berl. (oth. ed. <span dir=\"rtl\">קריבין</span>). Ib. XXV, 9; a. fr.—<span class=\"citation\">Keth. 56ᵃ</span> <span dir=\"rtl\">משום אִיקָּרוּבֵי דעתא הוא והא אִיקָּרְבָא דעתא</span> (when a man promises his bride an additional jointure,) it is in order that an attachment be formed; well, now, the attachment has been formed (and we have a right to assume that he wanted his bride to get that addition, even if he should die before the wedding).</div><div class=\"sense\"><b>—2)</b> <i>to claim relationship</i>, v. <a href=\"#\" data-headword=\"קָרֵב\">preced.</a></div></div>","alt":["קְרֵיב"]},"27451":{"h":"קֶרֶב","r":"S01885","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קְרֵב\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>inside, intestine.</i>—<i>Du.</i> <span dir=\"rtl\">קְרָבַיִם</span>, <span dir=\"rtl\">קְרָבַיִים</span>; constr. <span dir=\"rtl\">קִרְבֵּי</span>, <a href=\"#\" data-headword=\"קוּרְטְמֵי\">קִירְ׳</a>. <span class=\"citation\">Num. R. s. 7</span> (ref. to <span class=\"citation\">Num. XIV, 11</span> <span dir=\"rtl\">בקרבו</span>) <span dir=\"rtl\">אטר אעשה עמו … בקרבו כמה … עשיתי בקִרְבֵּיהֶן וכ׳</span> it does not read, ‘which I do with them’, but ‘which I do within them’:… how many signs and wonders have I done in their intestines (that the manna was entirely resorbed in their bowels) &amp;c. (with ref. to <a href=\"#\" data-headword=\"קֶרֶב\">קֶרֶב</a> <span class=\"citation\">Lev. VIII, 21</span>). <span class=\"citation\">Tam. IV, 2</span>. <span class=\"citation\">Ḥull. 16ᵇ</span> <span dir=\"rtl\">קירבי דגים</span> entrails of fish. <span class=\"citation\">Y. Sabb. II, 4ᵈ</span> <span dir=\"rtl\">ק׳ דגים כל זמן וכ׳</span> the fat of fish entrails (used as oil) has no bad odor as long as it burns. <span class=\"citation\">B. Mets. 60ᵇ</span>, v. <a href=\"#\" data-headword=\"נָפַח\">נָפַח</a>; a. fr.—<span class=\"citation\">Ned. 54ᵇ</span> <span dir=\"rtl\">ק׳ לאו בשר וכ׳</span> entrails are no meat and he who eats them is no man; Y. ib. VII, beg. 40ᵇ <a href=\"#\" data-headword=\"קִרְבַּיָּיא\">קרבייא</a> (ch. form). <span class=\"citation\">Ber. 10ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>innermost</i>; <span dir=\"rtl\">בְּקֶרֶב</span> <i>within</i>. <span class=\"citation\">Pesik. R. s. 13</span> <span dir=\"rtl\">בְּקִרְבַּנוּ</span>, v. <a href=\"#\" data-headword=\"רָחַשׁ\">רָחַשׁ</a>; a. e.</div>","alt":[]},"27452":{"h":"קָרֵב ²","r":"S01886","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"קָרֵיב\">קָרֵיב</a></div>","alt":[]},"27453":{"h":"קְרָב","r":"S01887","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קָרֵב ²\">preced.</a> wds.) <i>hostile contact, attack, war</i>. Y. Sot. VIII, 21ᶜ top <span dir=\"rtl\">רומי לק׳</span> the Roman (Latin) language is adapted for military affairs; <span class=\"citation\">Y. Meg. I, 71ᵇ</span> bot.; <span class=\"citation\">Esth. R. to I, 22</span>. <span class=\"citation\">Sabb. 59ᵃ</span> <span dir=\"rtl\">בשעה שבורח מן הק׳ וכ׳</span> when he flees from the battle, he puts it on &amp;c.; a. e.</div>","alt":[]},"27454":{"h":"קְרָב ²","r":"S01888","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. II Sam. XXI, 15</span>. <span class=\"citation\">Targ. Ps. XXVII, 3</span>. <span class=\"citation\">Ib. XXXV, 1</span>; a. fr.—Ib. <span dir=\"rtl\">קְרַבְתִּי</span>, v. <a href=\"#\" data-headword=\"קְרָבוּ\">קְרָבוּ</a>.—<span class=\"citation\">Tosef. Sot. XIII, 5</span>, v. <a href=\"#\" data-headword=\"נְגַח\">נְגַח</a>; Y. ib. IX, 24ᵇ; Bab. <span class=\"citation\">ib. 33ᵃ</span>. <span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">דעבד ק׳ עם וכ׳</span> who wages war with a king &amp;c. <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">ניפוק … ק׳ בהדייהו</span> let us go out and offer them (the Romans) battle; a. fr.—Pl. <span dir=\"rtl\">קְרָבִין</span>, <span dir=\"rtl\">קְרָבַיָּא</span>. <span class=\"citation\">Targ. Num. XXI, 14</span>. <span class=\"citation\">Targ. I Chr. XXVIII, 3</span>; a. e.</div>","alt":["קְרָבָא"]},"27455":{"h":"קְרֵבָה","r":"S01889","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"קְרֵבוּת\">קְרֵבוֹת</a> or <span dir=\"rtl\">קְרָבוֹת</span>, v. <a href=\"#\" data-headword=\"קְרֵיבָה\">קְרֵיבָה</a>.—<span class=\"citation\">Lev. R. s. 20</span> <span dir=\"rtl\">ועל הקרבה</span>, read: <a href=\"#\" data-headword=\"הַקְרָבָה\">ההַקְרָבָה</a>.</div>","alt":[]},"27456":{"h":"קְרָבוּ","r":"S01890","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"קְרָב\">קְרָב</a>. <span class=\"citation\">Targ. Ps. XXXV, 1</span> קְרָבוּתִי Ms. (ed. <span dir=\"rtl\">קְרֵבְתִּי</span>, <span dir=\"rtl\">קְרַבְתִּי</span>).</div>","alt":["קְרָבוּתָא"]},"27457":{"h":"קְרֵבוּת","r":"S01891","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרֵיבוּת\">קְרֵיבוּת</a></div>","alt":[]},"27458":{"h":"קרבות","r":"S01892","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ab. Zar. IV</span> (<span class=\"citation\">V), 9</span>, read with ed. Zuck. <span dir=\"rtl\">רקובות</span>, v. <a href=\"#\" data-headword=\"רוּקְבָּא II\"><span dir=\"rtl\">רוּקְבָּא</span> II</a></div>","alt":[]},"27459":{"h":"קְרָבוּתָא","r":"S01893","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרָבוּ\">קְרָבוּ</a></div>","alt":[]},"27460":{"h":"קַרְבִיטִין","r":"S01894","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (formed like <a href=\"#\" data-headword=\"שַׁרְבִיט\">שַׁרְבִיט</a>; <span dir=\"rtl\">קבט</span>, cmp. <a href=\"#\" data-headword=\"חֶבֶט I\">חֶבֶט</a>) <i>thongs</i>. <span class=\"citation\">M. Kat. 27ᵃ</span> <span dir=\"rtl\">מתיר קַרְבִיטָיו וכ׳</span> (<a href=\"#\" data-headword=\"קוּרְבִיטִין\">קוּרְבִיטָיו</a>) you untie its thongs, and it (the couch) falls down of itself; <span class=\"citation\">Ned. 56ᵇ</span>; <span class=\"citation\">Snh. 20ᵃ</span>.—[<span class=\"citation\">Y. Ber. III, 5ᵈ</span> bot. ed. Lehm., v. <a href=\"#\" data-headword=\"*קְלִיבִּינִטִירִין\">קְלִבִּינְטִירִין</a>.]</div>","alt":[]},"27461":{"h":"קִרְבַּיָּיא","r":"S01895","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֶרֶב\">קֶרֶב</a></div>","alt":[]},"27462":{"h":"קָרְבָּן","r":"S01896","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>gift, offering, sacrifice</i>. <span class=\"citation\">Ber. 15ᵃ</span> <span dir=\"rtl\">מעלה … והקריב עליו ק׳</span> it is accredited to him, as if he had built an altar and offered a sacrifice on it; <span class=\"citation\">Succ. 45ᵃ</span>. Sifra Vayikra, N’dab., ch. II, Par. 2 <span dir=\"rtl\">כל מקום שנאמר ק׳ אמור ביו&quot;ד ה&quot;א</span> wherever in the Scriptures ‘sacrifice’ is used in connection with the divine name, the latter is written with Yod He (<span dir=\"rtl\">יהוה</span>, never <a href=\"#\" data-headword=\"אֱלֹהִים\">אלהים</a>). <span class=\"citation\">Ned. I, 4</span> <span dir=\"rtl\">האומר ק׳ … שאני וכ׳</span> if one making a vow says, <i>ḳorban</i> … that I will (not) eat &amp;c. <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">כינויין לק׳</span> substitutes for <i>ḳorban</i>. <span class=\"citation\">Ib. II, 5</span> <span dir=\"rtl\">בק׳ וכ׳</span> (<a href=\"#\" data-headword=\"נְדַר I\">נדר</a>) if a man in making a vow uses the word <i>ḳorban</i>, and then says, I vowed only by the gifts to kings; a. fr.—Pl. <span dir=\"rtl\">קָרְבָּנוֹת</span>. Ib. <span dir=\"rtl\">ק׳ של מלכים</span>. <span class=\"citation\">Zeb. XIV, 10</span> <span dir=\"rtl\">קָרְבְּנוֹת הצבור</span> congregational sacrifices, <span dir=\"rtl\">ק׳ היחיד</span> sacrifices offered by individuals. <span class=\"citation\">Taan. 27ᵇ</span> כבר תקנתי להם סדר ק׳ וכ׳ I have arranged the order of sacrifices for them (in the Torah), and when they read these sections, I will account it to them as if they offered them. <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">בקש הקב&quot;ה … ועבודת ק׳ וכ׳</span> the Lord wanted to give them (the generation of the flood) four things (to purify them), the Law, sufferings, the sacrificial service, and prayer, but they refused; a. fr.</div>","alt":[]},"27463":{"h":"קָרְבַּן","r":"S01897","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Hos. XII, 2</span>. <span class=\"citation\">Targ. O. Gen. IV, 3</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"תִּקְרֻבְתָּא\">תקרבתא</a>, v. Berl. Mass., p. 73); Y. ib. Ib. 4; a. fr.—<span class=\"citation\">Ḥull. 8ᵃ</span> <span dir=\"rtl\">דקיימין לק׳</span> are designated to be sent as gifts. <span class=\"citation\">Zeb. 116ᵇ</span> the mother of king Shabur <span dir=\"rtl\">שדרה ק׳ וכ׳</span> sent a sacrifice to Raba, sending word, ‘offer it to the Lord.’ <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">שדר להו ק׳ וכ׳</span> send them a sacrifice and see whether they will offer it (in the Temple); a. fr.—Pl. <span dir=\"rtl\">קָרְבָּנִין</span>, <span dir=\"rtl\">קָרְבָּנַיָּא</span>, <a href=\"#\" data-headword=\"קִירְקָנוֹת\">קוּרְ׳</a>. <span class=\"citation\">Targ. Am. V, 22</span>. <span class=\"citation\">Targ. Lev. VII, 35</span>; a. fr.—<span class=\"citation\">Lam. R. to IV, 2</span> <span dir=\"rtl\">כל אילין ק׳ וכ׳</span> all those sacrifices which you send them, they eat themselves &amp;c. <span class=\"citation\">Gen. R. s. 91</span>; <span class=\"citation\">Y. Naz. V, end, 54ᵇ</span>; a. fr.</div>","alt":["קָרְבָּנָא","קוּרְ׳"]},"27464":{"h":"קרבניטא","r":"S01898","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְבַרְנִיטָא\">קְבַרְנִיטָא</a></div>","alt":[]},"27465":{"h":"קָרַד","r":"S01899","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"גָּרַד\">גָּרַד</a>), <i>Pi.</i> קֵירֵד <i>to scrape; to curry</i> (with a small-toothed strigil), v. <a href=\"#\" data-headword=\"קֵירוּד\">קֵירוּד</a>. <span class=\"citation\">Bets. II, 8</span> <span dir=\"rtl\">מְקָרְדִין את וכ׳</span> you may curry an animal on the Holy Day. Ib. <span dir=\"rtl\">אין מקרדין … אבל מקרצפין</span> you must not curry … with small-toothed strigils …, but you may do so with large-toothed ones. <span class=\"citation\">Yalk. Deut. 938</span> <span dir=\"rtl\">מְקָרְדוֹ והוא בולם</span> (<a href=\"#\" data-headword=\"זֶה\">את</a>) thou curriest him, and he kicks, v. <a href=\"#\" data-headword=\"בָּלַם II\"><span dir=\"rtl\">בָּלַם</span> II</a>; a. e.—<span class=\"citation\">Y. Sabb. IV, end, 7ᵃ</span> <span dir=\"rtl\">שיקרדם</span>, v. <a href=\"#\" data-headword=\"קִרְדֵּס\">קִרְדֵּס</a>.]</div>","alt":[]},"27466":{"h":"קַרְדָּא","r":"S01900","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַד\">preced.</a>; cmp. Arab. <i>ḳurd</i>, ricinus) [<i>scraping</i>,] <i>abdominal pain caused by a parasitic worm</i>. <span class=\"citation\">Lev. R. s. 18</span>; <span class=\"citation\">Num. R. s. 7</span> (ref. to <span dir=\"rtl\">לזרא</span>, <span class=\"citation\">Num. XI, 20</span>) [read:] <span dir=\"rtl\">לק׳ שאהיה נותן דורא במעיהן</span> (some ed. <span dir=\"rtl\">לקדרא</span>) it will cause <i>ḳurda</i>, as I will put a parasite (<i>dura</i>) in their bowels; v. <a href=\"#\" data-headword=\"דְּרַרְיָא\">דְּרַרְיָא</a>.</div>","alt":[]},"27467":{"h":"קַרְדּוּ I","r":"S01901","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Ḳardu, Ḳardun</i>, the district of <i>Cordyene</i> (corresponding to b. h. <span dir=\"rtl\">אררט</span>; v. Schr. KAT<sup>2</sup>, p. 53). <span class=\"citation\">Targ. O. Gen. VIII, 4</span> (Y. <span dir=\"rtl\">קרדון</span>, some ed. <a href=\"#\" data-headword=\"קַדְרוֹן\">קַדְרוֹן</a>). <span class=\"citation\">Targ. II Kings XIX, 37</span>; <span class=\"citation\">Targ. Is. XXXVII, 38</span>. <span class=\"citation\">Targ. Jer. LI, 27</span>.</div>","alt":["קַרְדּוּן"]},"27468":{"h":"קַרְדּוּ II","r":"S01902","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḳardu</i> in Babylonia (cmp. Kardunias, Schr. KAT<sup>2</sup>, p. 348; KGF, p. 534). <span class=\"citation\">B. Bath. 91ᵃ</span> <span dir=\"rtl\">עשר … ושבע בק׳</span> (Ar. <span dir=\"rtl\">בכַרְדּוּ</span>) Abraham was ten years in prison, three in Cuthi and seven in Ḳardu; <span class=\"citation\">Yalk. Gen. 77</span> <span dir=\"rtl\">בקדרו</span>; <span class=\"citation\">Pirké d’R. El. ch. XXVI</span> <a href=\"#\" data-headword=\"קרדי\">קרדי</a>.—<span class=\"citation\">Yeb. 115ᵇ</span> <a href=\"#\" data-headword=\"קוּרְטְבָא\">קוּרְטְבָא</a>.</div>","alt":[]},"27469":{"h":"קַרְדּוּט","r":"S01903","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"כַּרְדּוּט\">כַּרְדּוּט</a>, <i>a tunic with sleeves.</i>—Pl. <a href=\"#\" data-headword=\"קַרְדּוּיִים\">קַרְדּוּטִין</a>. <span class=\"citation\">Ab. d’R. N., ch. VI</span> ed. Schechter (ed. <a href=\"#\" data-headword=\"קרדמין\">קרדמין</a>, corr. acc.).</div>","alt":[]},"27470":{"h":"קַרְדּוּיֵי","r":"S01904","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְדּוּיִים\">next w.</a></div>","alt":[]},"27471":{"h":"קַרְדּוּיִים","r":"S01905","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (קַרְדּוּ I) <i>Cordyenians</i>. <span class=\"citation\">Y. Kidd. IV, 65ᶜ</span> bot.; <span class=\"citation\">Y. Yeb. I, 3ᵇ</span> top <span dir=\"rtl\">מקבלין גרים מן הק׳ וכ׳</span> we may accept proselytes from the Cordyenians and the Tadmorites; Bab. <span class=\"citation\">ib. 16ᵃ</span>. <span class=\"citation\">Ib.</span> <a href=\"#\" data-headword=\"קַרְדּוּיֵי\">קַרְדּוּיֵי</a> (ch. form), contradist. from <a href=\"#\" data-headword=\"קַרִתּוּיֵי\">קרתויי</a>, v. <a href=\"#\" data-headword=\"קַרְתּוּיִים\">קַרְתּוּיִים</a>.</div>","alt":["קַרְדּוּיִין"]},"27472":{"h":"רְחֵשׁ","r":"T00543","html":"<div class=\"sense\">, <i>worm, reptile, insect</i>. <span class=\"citation\">Targ. Gen. I, 20</span> (h. text <span dir=\"rtl\">שרץ</span>). <span class=\"citation\">Targ. O. Ex. XVI, 20</span> (h. text <span dir=\"rtl\">תולעים</span>). Targ. ib. 24 (h. text <a href=\"#\" data-headword=\"רָמָה I\">רמה</a>). <span class=\"citation\">Targ. Lev. XI, 20</span>, sq. <span class=\"citation\">Ib. V, 2</span> (O. ed. Vien. <span dir=\"rtl\">רָחִיש</span>); a. fr.—<span class=\"citation\">B. Mets. 84ᵇ</span> חזאי ר׳ דקא וכ׳ I saw a worm come out of his ear. <span class=\"citation\">Y. Yeb. XV, 14ᵈ</span> <span dir=\"rtl\">דר׳ שכיח</span> at a season when the bite of a reptile is of frequent occurrence; a. e.—In gen. a <i>living thing, noxious animal</i>. <span class=\"citation\">Sabb. 146ᵃ</span> sq. <span dir=\"rtl\">לא אתי לאוסופי משום ר׳</span> one will not enlarge the hole for fear that an animal may creep in.—Pl. <span dir=\"rtl\">רַחֲשִׁין</span>, <span dir=\"rtl\">רַחֲשֵׁי</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Targ. Y. Gen. I, 24</span>. <span class=\"citation\">Targ. Y. Deut. XVIII, 11</span>.</div>","alt":["רְחִישׁ","רַחֲשָׁא","רִו׳"]},"27473":{"h":"רַחֲשׁוּשׁ","r":"T00544","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַשׁ\">רָחַשׁ</a>) <i>moving</i> (<i>of lips</i>), <i>emotion</i> (<i>of the heart</i>).—Pl. constr. <span dir=\"rtl\">רַחְשׁוּשֵׁי</span>. <span class=\"citation\">Men. 63ᵃ</span> מרחשת דאתיא אר׳ הלב Ar. a. ed. Ven. (v. Rabb. D. S. a. l. note 100; ed. <span dir=\"rtl\">ארְחוּשֵׁי</span>) the meal offering of the <i>marḥesheth</i> intimates that it comes to atone for the emotions of the heart (evil thoughts). Ib. <span dir=\"rtl\">אר׳ הפה</span> ed. Ven. (ed. only <span dir=\"rtl\">ארחושי</span>; Ms. M. <span dir=\"rtl\">ארחושי הפה</span>) for the movements of the lips, as people say, his lips are moving, v. <a href=\"#\" data-headword=\"רְחַשׁ\">רְחַשׁ</a>.</div>","alt":[]},"27474":{"h":"רַחַת","r":"T00545","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>winnowing shovel</i>. <span class=\"citation\">Kel. XV, 5</span> <span dir=\"rtl\">ר׳ של גרוסות</span> the grist-grinders’ shovel. <span class=\"citation\">Sabb. XVII, 2</span>; Y. ib. 16ᵇ top; a. e.</div>","alt":[]},"27475":{"h":"רִחֲתָא","r":"T00546","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XXX, 24</span>.</div>","alt":["רִי׳"]},"27476":{"h":"רֵחְתָנָא","r":"T00547","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיחְתָנָא\">רֵיחְתָנָא</a></div>","alt":[]},"27477":{"h":"רחתת","r":"T00548","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> bot. <span dir=\"rtl\">ר׳ ענת׳</span>, read with ed. Lehm.: <span dir=\"rtl\">כיון דאתת ענתא</span> (v. Tosaf. to <span class=\"citation\">Sot. 31ᵃ</span>).</div>","alt":[]},"27478":{"h":"רָטַב","r":"T00549","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to drip, be moist, juicy, green</i>.</div><div class=\"sense\"><b>—2)</b> <i>to moisten, v.</i> <a href=\"#\" data-headword=\"רָטָה\">רָטָה</a>.—Part. pass. <a href=\"#\" data-headword=\"רָטוֹב\">רָטוּב</a> (b. h. <a href=\"#\" data-headword=\"רְטַב I\">רָטֹב</a>); f. <span dir=\"rtl\">רְטוּבָה</span>; pl. <span dir=\"rtl\">רְטוּבִים</span>, <span dir=\"rtl\">רְטוּבִין</span>; <span dir=\"rtl\">רְטוּבוֹת</span> (interch. with <a href=\"#\" data-headword=\"רוֹטֶב\">רוֹטֵב</a> &amp;c.). <span class=\"citation\">Koh. R. to VI, 6</span>; <span class=\"citation\">Lev. R. s. 4</span>, v. <a href=\"#\" data-headword=\"סִילּוֹן I\"><span dir=\"rtl\">סִילּוֹן</span> I</a>. <span class=\"citation\">Num. R. s. 3</span>, beg. <span dir=\"rtl\">תמרים רטובים</span> (some ed. <span dir=\"rtl\">רוֹטְבִין</span>) juicy (good) dates, opp. <span dir=\"rtl\">נובלות</span>; <span class=\"citation\">Midr. Till. to Ps. XCII, 13</span>. <span class=\"citation\">T’bul Yom III, 6</span> <span dir=\"rtl\">תמרים רטובות</span> (Ar. ed. pr. <span dir=\"rtl\">רוֹטְבוֹת</span>); a. fr.—[<span class=\"citation\">Num. R. s. 10</span><sup>21</sup> <span dir=\"rtl\">ונוטל את הרטוב</span> some ed., read: <span dir=\"rtl\">הרוֹטֶב</span>.]</div><div class=\"sense\"><b>Hif. הִרְטִיב</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רחתת\">same</a>, <a href=\"#\" data-headword=\"רחתת\">same</a>, <i>to be green, succulent; to thrive</i>. <span class=\"citation\">Lev. R. s. 23</span> <span dir=\"rtl\">וישראל מַרְטִיבִין והולכים</span> and Israel shall thrive more and more; <span class=\"citation\">Cant. R. to II, 2</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כשושנת … שמַרְטֶבֶת והולכת</span> like the lily of the valleys, which is continually green; a. e.—ה׳ מעשים טובים <i>to be succulent with good deeds</i>. <span class=\"citation\">Ib. 1</span> הִרְטַבְתִּי מ׳ ט׳ כשושנה I became filled with the sap of good deeds like the lily; <span class=\"citation\">Midr. Till. to Ps. I, 3</span> <span dir=\"rtl\">ה׳ במעשים וכ׳</span>. <span class=\"citation\">Gen. R. s. 81</span>, end (ref. to <a href=\"#\" data-headword=\"לוּז\">לוז</a>, <span class=\"citation\">Gen. XXXV, 6</span>) <span dir=\"rtl\">כל מי … ה׳ מצות ומ׳ ט׳ כלוז</span> whosoever entered it became filled with pious acts and good deeds like a nut-tree; (ib. s. 69, a. e. <a href=\"#\" data-headword=\"טָרַף\">הטריף</a>, v. <a href=\"#\" data-headword=\"טָרַף\">טָרַף</a>); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to cover with green foliage, to improvise a cover with foliage</i>. Ib. s. 68 <span dir=\"rtl\">מה רטיבה ה׳ וכ׳</span> what was the cover which he (Jacob) prepared? ‘The beams of our house are cedars’ (<span class=\"citation\">Cant. I, 17</span>); <span class=\"citation\">Cant. R. to I, 17</span> <span dir=\"rtl\">ומה הרטבה ה׳ מהן</span> (strike out <a href=\"#\" data-headword=\"מַהָן\">מהן</a>); (<span class=\"citation\">Yalk. Gen. 119</span> <span dir=\"rtl\">ומה טריפה הטריף</span>, Var. <span dir=\"rtl\">רטיבה ה׳</span>, v. <a href=\"#\" data-headword=\"טָרַף\">טָרַף</a>).—[<span class=\"citation\">Cant. R. to VI, 10</span> <span dir=\"rtl\">מרטבת</span>, v. <a href=\"#\" data-headword=\"שָׁבָה\">שָׁבַה</a> <i>Hithpa.</i>]</div></div>","alt":[]},"27479":{"h":"רְטַב I","r":"T00550","html":"<div class=\"sense\"> ch. <a href=\"#\" data-headword=\"רָטַב\">same</a>; v. <a href=\"#\" data-headword=\"רַטִּיב\">רַטִּיב</a></div><div class=\"sense\"><b>Af. אַרְטִב</b> <div class=\"sense\"><i>to moisten, give sap to</i>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 23</span>.</div></div><div class=\"sense\"><b>Ithpe. אִרְטִיב  אִירְטַב</b> <div class=\"sense\"><i>to be green, moist</i>. <span class=\"citation\">Targ. Y. II, Ex. III, 2</span> <span dir=\"rtl\">מִרְטִיב</span> (some ed. <a href=\"#\" data-headword=\"מַרְכְּבָא\">מֵרְ׳</a>). <span class=\"citation\">Ib. 3</span> (ed. Vien. <span dir=\"rtl\">מַרְטִיב</span> <i>Af.</i>).—<span class=\"citation\">Succ. 53ᵇ</span> <span dir=\"rtl\">כמה דמידלי טפי מִירְטַב עלמא</span> (differ. in Ms. M., v. Rabb. D. S. a. l. note) the higher the waters of the deep rise, the more is vegetation moistened.</div></div>","alt":[]},"27480":{"h":"רְטַב II","r":"T00551","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְטַב I\">preced.</a>) <i>juice, broth</i> (v. <a href=\"#\" data-headword=\"רוֹטְבָא\">רוֹטְבָא</a>). <span class=\"citation\">Targ. Is. LXV, 4</span> ed. Wil., a. Ar. Var. (ed. Lag. a. oth. <a href=\"#\" data-headword=\"רְטַף\">רְטַף</a>; h. text <span dir=\"rtl\">מרק</span>).</div>","alt":[]},"27481":{"h":"רֶטֶב","r":"T00552","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְטַב II\">preced.</a> wds.; v. <a href=\"#\" data-headword=\"רוֹטֶב\">רוֹטָב</a>) <i>green fruit</i>, esp. <i>dates</i>. <span class=\"citation\">Y. Maasr. I, 48ᵈ</span> bot. <span dir=\"rtl\">ניקורי ר׳ באביהן</span> fruit during development showing bites of serpents; <span class=\"citation\">Tosef. Kel. B. Bath. V, 6</span> <a href=\"#\" data-headword=\"רוֹטֶב\">רוטב</a>.</div>","alt":[]},"27482":{"h":"רָטָה","r":"T00553","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רטי\">רטי</a></div>","alt":[]},"27483":{"h":"רָטוֹב","r":"T00554","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>) <i>a basket made of green twigs</i>, used as a bird’s trap. <span class=\"citation\">Kel. XXIII, 5</span>.—[<a href=\"#\" data-headword=\"רָטוֹב\">רָטוֹב</a> or <a href=\"#\" data-headword=\"רָטוֹב\">רָטוּב</a>, v. <a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>.]</div>","alt":[]},"27484":{"h":"רָטוֹנָא","r":"T00555","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְטַן\">רְטַן</a>) <i>charmer.</i>—Pl. constr. <span dir=\"rtl\">רָטוֹנֵי</span>. <span class=\"citation\">Targ. Ps. LVIII, 6</span> (ed. Wil. <span dir=\"rtl\">רָטְנֵי</span>).</div>","alt":[]},"27485":{"h":"רָטוּשׁ","r":"T00556","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְטַשׁ\">רָטַשׁ</a>; v. <a href=\"#\" data-headword=\"רְטַשׁ\">רְטַשׁ</a>) <i>an emigrant</i> or <i>fugitive whose estate is abandoned</i>, v. <a href=\"#\" data-headword=\"נָטוּשׁ\">נָטוּשׁ</a>.—Pl. <span dir=\"rtl\">רְטוּשִׁים</span>, <a href=\"#\" data-headword=\"רְחוּשִׁין\">רְטוּשִׁין</a>. <span class=\"citation\">Tosef. Keth. VIII, 3</span> אלו הן ר׳ כל שאינו יודע וכ׳ <i>r’ṭushin</i> (in law) are those whose whereabouts is unknown, contrad. to <span dir=\"rtl\">נטושין</span>; Y. ib. IV, 29ᵃ <span dir=\"rtl\">אלו הן נכסי ר׳ כל שהלך אביו וכ׳</span> estate of <i>r’ṭushin</i> is, if one’s father, or … any of those whom he would be entitled to succeed, have gone abroad &amp;c.; <span class=\"citation\">Y. Yeb. XV, 15ᵃ</span> top; <span class=\"citation\">B. Mets. 38ᵇ</span>. <span class=\"citation\">Ib. 39ᵃ</span> ר׳ דמדעתן <i>r’ṭushin</i> are those who leave (or run away) of their own accord (ref. to <span class=\"citation\">Hos. X, 14</span>; differ. in Y. l. c. <span dir=\"rtl\">נטוש זה שיצא לדעת</span>). <span class=\"citation\">Arakh. VII, 4</span> (<span class=\"citation\">25ᵇ</span>) (of a field dedicated to the sanctuary) <span dir=\"rtl\">הגיע היובל … נקראת שְׂדֵה ר׳</span> if the year of jubilee arrives, and it is not redeemed …, it is called a field of the absentees until the next jubilee; <span dir=\"rtl\">הגיע … נקראת רְטוּשֵׁי ר׳</span> (Bab. ed. <span dir=\"rtl\">רטושה</span>, corr. acc.) if the second jubilee comes, and it is not redeemed, it is called a field of the absentees in the second degree, until the third jubilee; Tosef. ib. IV, 15 <span dir=\"rtl\">רטושין ר׳</span> (corr. acc.); Sifra B’ḥuck., Par. 4, ch. XI; <span class=\"citation\">Yalk. Lev. 677</span>.—[רְטוּשִׁין Chald., v. <a href=\"#\" data-headword=\"רְטַשׁ\">רְטַשׁ</a>.]</div>","alt":[]},"27486":{"h":"*רָטַט","r":"T00557","html":"<div class=\"sense\">, <i>Pi.</i> רִטֵּט <i>to run, leap</i>. <span class=\"citation\">Cant. R. to I, 9</span> (ref. to <span class=\"citation\">Ps. CVI, 20</span>) <span dir=\"rtl\">חרטומי … כמְרַטֵּט לפניהם</span> the Egyptian magicians made sorcery before them, and it (the golden calf) appeared as if it were leaping before them; [v., however, <a href=\"#\" data-headword=\"קִרְטֵעַ\">קִרְטֵעַ</a>].</div>","alt":[]},"27487":{"h":"רְטַט","r":"T00558","html":"<div class=\"sense\">(cmp. <span dir=\"rtl\">רתת</span>) <i>to tremble, shake</i>. <span class=\"citation\">Targ. Job VII, 5</span> (Ms. <a href=\"#\" data-headword=\"רְטַט\">רַטֵּיט</a> <i>Pa.</i>).</div><div class=\"sense\"><b>Pa. רַטֵּיט</b> <div class=\"sense\"><i>to shake, cause to tremble</i>. <span class=\"citation\">Targ. Ps. XXIX, 8</span> (ed. Wil. <span dir=\"rtl\">מרטש</span>).</div></div><div class=\"sense\"><b>Ithpe. אִתְרְטֵיט  אִתְרְטַט</b> <div class=\"sense\"><i>to be shaken, tremble</i>. Targ. II Esth. V, 4. <span class=\"citation\">Targ. Ps. XVIII, 8</span> אִתְרְטִיטוּ Ms. (ed. <span dir=\"rtl\">אתרטישו</span>; h. text <span dir=\"rtl\">ויתגעשו</span>).</div></div>","alt":[]},"27488":{"h":"רטי","r":"T00559","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>) <i>to moisten, sprinkle, soften</i>. <span class=\"citation\">Tosef. Toh. V, 16</span> <span dir=\"rtl\">הרוֹטֶה פשתנו</span> (ed. Zolk. <span dir=\"rtl\">הרוטב</span>) he who wets (squirts) his flax (to make it soft for spinning). <span class=\"citation\">Ib. IV, 11</span> <span dir=\"rtl\">אף הרוֹטֵיהוּ וכ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">הסוטיהו</span>, corr. acc.; ed. Zolk. <span dir=\"rtl\">הרטיבין</span>, read: <span dir=\"rtl\">הרוֹטְבוֹ</span>) he who wets it (the flax spun by a menstruant) is likewise unclean on account of his mouth (coming in contact with it through the medium of the liquid in squirting).</div><div class=\"sense\"><b>Hif. הִרְטָה</b> <div class=\"sense\"> [<i>to cause dripping</i>,] <i>to wring, press</i>. <span class=\"citation\">Ex. R. s. 21</span> <span dir=\"rtl\">ה׳ אותי בידו</span> he caused me to be wrong out in his (Satan’s) hand (with ref. to <span dir=\"rtl\">יִרְטֵנִי</span>, <span class=\"citation\">Job XVI, 11</span>).</div></div>","alt":["רָטָה"]},"27489":{"h":"רָטַיָּא","r":"T00560","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָהֲטָא\">רָהֲטָא</a></div>","alt":[]},"27490":{"h":"רַטִּיב","r":"T00561","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְטַב I\">רְטַב</a>) <i>moist, succulent, fresh, green</i>. <span class=\"citation\">Targ. Job VIII, 16</span>. <span class=\"citation\">Targ. Ez. XVII, 24</span>. <span class=\"citation\">Ib. XXI, 3</span>.—<span class=\"citation\">Gitt. 69ᵇ</span>, v. <a href=\"#\" data-headword=\"אִיצָא I\"><span dir=\"rtl\">אִיצָא</span> I</a>.—Pl. <span dir=\"rtl\">רַטִּיבִין</span>, <a href=\"#\" data-headword=\"רָגִיג\">רְ׳</a>. <span class=\"citation\">Targ. Num. VI, 3</span>. <span class=\"citation\">Targ. Is. VI, 13</span>; a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"רַטִּיב\">רטִּיבָא</a>, <span dir=\"rtl\">רְטִ׳</span>. Gitt. l. c., v. <a href=\"#\" data-headword=\"סִיסִין I\"><span dir=\"rtl\">סִיסִין</span> I</a>; a. e.—Pl. <span dir=\"rtl\">רַטִּיבַן</span>. <span class=\"citation\">Targ. O. Gen. XXX, 37</span> ed. Berl. (oth. ed. <span dir=\"rtl\">בִין …</span>).</div>","alt":["רָטִיב","רְ׳","רְטִיבָא I"]},"27491":{"h":"רְטִיבָא II","r":"T00562","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַטִּיב\">preced.</a>) <i>meadow</i>. <span class=\"citation\">Targ. Y. I Num. XXII, 30</span> <span dir=\"rtl\">שרי בר׳</span> (ed. Vien. <span dir=\"rtl\">שדי</span>) it dwells (I sent it to pasture) in the meadow; <span class=\"citation\">Snh. 105ᵇ</span> אשראי בר׳ Ar. (ed. <span dir=\"rtl\">שדא להו בר׳</span>, read: <span dir=\"rtl\">שדאי ליה</span>; Ms. K. <span dir=\"rtl\">בר׳ שדאי</span>; v. Rabb. D. S. a. l. note 30).</div>","alt":[]},"27492":{"h":"רְטִיבָא III","r":"T00563","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רוֹטֶב\">רוֹטָב</a>, <i>soft, green date</i>. <span class=\"citation\">Erub. 40ᵇ</span>, v. <a href=\"#\" data-headword=\"רִפְסָא\">רִפְסָא</a>.</div>","alt":[]},"27493":{"h":"רְטִיבָה","r":"T00564","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>, <i>Hif.</i>) <i>a cover of foliage, improvised cover</i> in the field. <span class=\"citation\">Gen. R. s. 68</span>, v. <a href=\"#\" data-headword=\"רְטַב I\">רָטב</a>; <span class=\"citation\">Cant. R. to I, 17</span> <a href=\"#\" data-headword=\"הַרְטָבָה׳\">הַרְטָבָה</a>.</div>","alt":[]},"27494":{"h":"רְטִיבִי","r":"T00565","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>R’ṭibi</i>. <span class=\"citation\">Sot. 22ᵃ</span>, v. <a href=\"#\" data-headword=\"יוֹחָנִי\">יוֹחָנִי</a>.</div>","alt":[]},"27495":{"h":"רִטִיבְתָּא","r":"T00566","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Pund’ḳa R’ṭibta</i> (Green Inn), near Cæsaræa in Palestine. Y. Dem. II, 22ᶜ bot. (Hildesh., Beitr. p. 9, reads <span dir=\"rtl\">דטיבתא</span>).</div>","alt":["פּוּנְדְּקָא רְ׳"]},"27496":{"h":"רְטִיָּה","r":"T00567","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָטָה\">רָטָה</a>) <i>emollient, plaster, compress</i>. <span class=\"citation\">Ex. R. s. 26</span> <span dir=\"rtl\">אין מידתי … מכה באזמל ומרפא בר׳ וכ׳</span> my (God’s) way is not like the way of man (surgeon), who wounds with a knife and heals with a plaster, but I &amp;c.; <span class=\"citation\">ib. 50</span>; <span class=\"citation\">Lev. R. s. 18</span>, end; Mekh. B’shall., s. 5; Tanḥ. <span class=\"citation\">B’shall. 23</span>; Tanḥ. Vayesheb 9. <span class=\"citation\">Cant. R. to IV, 5</span> <span dir=\"rtl\">בו&quot;ד אין מקדים ר׳ וכ׳</span> a human being does not prepare the plaster before he sees the wound, but not so the Lord, he prepares the plaster &amp;c.; <span class=\"citation\">Yalk. Jer. 312</span>. <span class=\"citation\">Tosef. Pes. II</span> (<span class=\"citation\">III), 3</span>; a. v. fr.—Pl. <span dir=\"rtl\">רְטִיּוֹת</span>. <span class=\"citation\">Ex. R. s. 27</span> <span dir=\"rtl\">ונמצא כולו ר׳</span> finally his body is covered all over with plasters.</div>","alt":["רְטִיָּיה"]},"27497":{"h":"רְטֵישׁ","r":"T00568","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְטַשׁ\">רְטַשׁ</a></div>","alt":[]},"27498":{"h":"רָטַן","r":"T00569","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָטָה\">רָטָה</a>, <a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>) [<i>to drip, run</i>; cmp. <a href=\"#\" data-headword=\"דָּבַב I\">דָּבַב</a>,] <i>to mumble, grumble</i>; denom. <a href=\"#\" data-headword=\"רוֹטְנָנִית\">רוֹטְנָנִית</a>.</div>","alt":[]},"27499":{"h":"רְטַן","r":"T00570","html":"<div class=\"sense\">, <i>to mumble</i> (a charm). Part. <span dir=\"rtl\">רָטֵין</span>; pl. constr. <span dir=\"rtl\">רָטְנֵי</span>. <span class=\"citation\">Targ. O. Deut. XVIII, 11</span>. <span class=\"citation\">Targ. Ps. LVIII, 6</span> ed. Wil., v. <a href=\"#\" data-headword=\"רָטוֹנָא\">רָטוֹנָא</a>.—<span class=\"citation\">Sot. 22ᵃ</span>, v. <a href=\"#\" data-headword=\"מָגוֹשָׁא\">מָגוֹשָׁא</a>.</div>","alt":[]},"27500":{"h":"רְטָן","r":"T00571","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְטַן\">preced.</a>) <i>mumbling, charm</i>. <span class=\"citation\">Targ. O. Deut. XVIII, 11</span>. <span class=\"citation\">Targ. Ps. LVIII, 6</span> (some ed. <span dir=\"rtl\">רֶטֶן</span>).</div>","alt":[]},"27501":{"h":"רָטָן","r":"T00572","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">רהטן</span>; <a href=\"#\" data-headword=\"רָהַט\">רָהַט</a>) <i>runner.</i>—Pl. <span dir=\"rtl\">רְטַנִּין</span>. <span class=\"citation\">Tosef. Sabb. V</span> (<span class=\"citation\">VI), 11</span> <span dir=\"rtl\">הר׳ יוצאין וכ׳</span> runners may go out (on the Sabbath) with their scarf (over their shoulder); <span class=\"citation\">Sabb. 147ᵃ</span></div>","alt":[]},"27502":{"h":"רטסקאות","r":"T00573","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ohol. V, 5</span> Var., v. <a href=\"#\" data-headword=\"טְרַקְסָאוֹת\">טְרַקְסָאוֹת</a></div>","alt":[]},"27503":{"h":"*רָטַע","r":"T00574","html":"<div class=\"sense\">, <i>Hif.</i> <span dir=\"rtl\">הִרְטִיעַ</span> or <i>Pi.</i> <a href=\"#\" data-headword=\"*רָטַע\">רִטֵּעַ</a> (= <span dir=\"rtl\">רתע</span>) <i>to be excited</i>. Y’lamd. beg., quot. in Ar. <span dir=\"rtl\">מַרְטַעַת וצווחת</span> (or <span dir=\"rtl\">מְרַטַּעַת</span>) she is excited and cries.</div>","alt":[]},"27504":{"h":"רְטַף","r":"T00575","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"רְטַב II\"><span dir=\"rtl\">רְטַב</span> II</a></div>","alt":[]},"27505":{"h":"רְטַשׁ","r":"T00576","html":"<div class=\"sense\"><i>to let run, abandon; to drive out, banish</i>. <span class=\"citation\">Targ. I Sam. XVII, 28</span> (h. text <a href=\"#\" data-headword=\"נָטַשׁ I\">נטש</a>). <span class=\"citation\">Targ. Jer. XII, 7</span>. <span class=\"citation\">Targ. Ez. XXVIII, 17</span> (h. text <span dir=\"rtl\">השלכ׳</span>). <span class=\"citation\">Ib. XXXI, 12</span>. <span class=\"citation\">Targ. Jer. XIV, 19</span> (h. text <span dir=\"rtl\">מאס</span>). <span class=\"citation\">Ib. XXIII, 39</span> (h. text <span dir=\"rtl\">נשׁא</span>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"רְטֵישׁ\">רְטִישׁ</a>; f. <span dir=\"rtl\">רְטִישָׁא</span>; pl. <span dir=\"rtl\">רְטִישִׁין</span>. <span class=\"citation\">Targ. Ez. XVI, 4</span>. <span class=\"citation\">Targ. Hos. II, 5</span>. <span class=\"citation\">Targ. Is. V, 6</span>. <span class=\"citation\">Targ. Y. II, Deut. XXXII, 36</span>. <span class=\"citation\">Targ. Lam. III, 45</span> <a href=\"#\" data-headword=\"רְחוּשִׁין\">רְטוּשִׁין</a> (h. text <a href=\"#\" data-headword=\"מָאוּס\">מָאוֹס</a>); a. e.—Y. Pes. III, 30ᵇ top <span dir=\"rtl\">דאינון רטישין</span> (sub. <span dir=\"rtl\">מיכל</span>) for they (the barley cakes) are the food of the exiles (homeless poor, cmp. <span class=\"citation\">Ez. IV, 12</span>), opp. <span dir=\"rtl\">חַטְיָן</span> those living in luxury (v. <span dir=\"rtl\">חטי I</span>; differ. in comment).</div><div class=\"sense\"><b>Af. אַרְטֵישׁ</b> <div class=\"sense\"><i>to abandon, renounce ownership of</i>. <span class=\"citation\">Targ. O. Ex. XXIII, 11</span> (h. text <a href=\"#\" data-headword=\"נָטַשׁ I\">נטש</a>).</div></div><div class=\"sense\"><b>Pa. רַטֵּישׁ</b> <div class=\"sense\"><b>1)</b> <i>to abandon, forsake; to banish</i>. <span class=\"citation\">Targ. Jud. VI, 13</span> (h. text <a href=\"#\" data-headword=\"נָטַשׁ I\">נטש</a>). <span class=\"citation\">Targ. Jer. VII, 29</span>. <span class=\"citation\">Targ. Ez. XXXII, 4</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to scatter; to dash to pieces</i> (cmp. b. h. <span dir=\"rtl\">נפץ</span>). <span class=\"citation\">Targ. Ps. CXXXVII, 9</span>; a. e.—<span class=\"citation\">Ib. XXIX, 8</span> ed. Wil. v. <a href=\"#\" data-headword=\"רְטַט\">רְטט</a>.—Part. pass. <span dir=\"rtl\">מְרַטַּשׁ</span>; f. <span dir=\"rtl\">מְרַטְּשָׁא</span>; pl. <span dir=\"rtl\">מְרַטְּשָׁן</span>. Targ. II Esth. VI, 11 <span dir=\"rtl\">אודנוי מ׳</span> his ears shattered (?); [prob. to be read: <span dir=\"rtl\">מְטַרְשָׁן</span> <i>obstructed, deaf</i>, v. <a href=\"#\" data-headword=\"טְרַשׁ II\"><span dir=\"rtl\">טְרַשׁ</span> II</a>].</div></div><div class=\"sense\"><b>Ithpa. אִתְרַטֵּשׁ</b> </div><div class=\"sense\"><b>Ithpe. אִתְרְטִישׁ</b> <div class=\"sense\"><b>1)</b> <i>to be abandoned, deserted; to be made homeless</i>. Targ. O. a. Y. I <span class=\"citation\">Lev. XXVI, 43</span> (h. text <span dir=\"rtl\">תעזב</span>). <span class=\"citation\">Targ. Hos. IV, 14</span> (h. text <span dir=\"rtl\">ולבט</span>, v. <a href=\"#\" data-headword=\"לָבַט\">לָבַט</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be scattered; to be dashed</i>. <span class=\"citation\">Targ. Am. V, 2</span> (h. text <span dir=\"rtl\">נטשה</span>). <span class=\"citation\">Targ. Is. XIV, 12</span> (h. text <a href=\"#\" data-headword=\"גָּדַע\">נגדע</a>). <span class=\"citation\">Targ. I Sam. IV, 2</span> (h. text <span dir=\"rtl\">ותטש</span>). <span class=\"citation\">Targ. Jud. XV, 9</span>; a. e.—<span class=\"citation\">Targ. Ps. XVIII, 8</span> ed., v. <a href=\"#\" data-headword=\"רְטַט\">רְטַט</a>.</div></div>","alt":["רְטֵישׁ"]},"27506":{"h":"רִי","r":"T00577","html":"<div class=\"sense\"> a portion of the word <a href=\"#\" data-headword=\"שַׁבְרִירֵי\">שַׁבְרִירִי</a>, used in an incantation. <span class=\"citation\">Ab. Zar. 12ᵇ</span>; <span class=\"citation\">Pes. 112ᵃ</span></div>","alt":[]},"27507":{"h":"ריאגיסו","r":"T00578","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. XXXIV</span> <span dir=\"rtl\">הר׳</span> ed. Warsaw, oth. ed. <span dir=\"rtl\">הרי אגיסו</span>, ed. Bub. <span dir=\"rtl\">היה אגיסו</span>, read: <span dir=\"rtl\"><span dir=\"rtl\">וי&quot;א אגיסו</span> (<span dir=\"rtl\">ויש אומרים</span>) <a href=\"#\" data-headword=\"הוי\">היה</a></span>, a misplaced gloss to <span dir=\"rtl\">ואחיו של גלית וכ׳</span>.</div>","alt":[]},"27508":{"h":"רֵיאָה","r":"T00579","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָוָה\">רָוָה</a>, v. quot.) <i>lungs</i>. <span class=\"citation\">Ber. 61ᵇ</span> <span dir=\"rtl\">ר׳ שואבת וכ׳</span> the lungs draw (resorb) all liquids. <span class=\"citation\">Lev. R. s. 4</span> <span dir=\"rtl\">הר׳ לשתיה</span> the lungs are the organ for drinking (resorbing liquids). <span class=\"citation\">Lev. R. s. 18</span>; <span class=\"citation\">Koh. R. to XII, 3</span>; <span class=\"citation\">Ḥull. 45ᵃ</span>, v. <a href=\"#\" data-headword=\"כָּנָף\">כָּנָף</a>. <span class=\"citation\">Ib. III, 1</span>; a. fr.</div>","alt":[]},"27509":{"h":"רִיב I","r":"T00580","html":"<div class=\"sense\"> (b. h.) <i>to contend, strive; to plead</i>. <span class=\"citation\">Meg. 21ᵇ</span> <span dir=\"rtl\">הרָב את ריבנו</span> who pleaded our cause.</div><div class=\"sense\"><b>Hif. הֵרִיב</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רֵיאָה\">same</a>. Tanḥ. Naso 12 <span dir=\"rtl\">כל זמן … אינה מְרִיבָה</span> as long as she was engaged in it, she did not quarrel, v. <a href=\"#\" data-headword=\"רָנַן\">רָנַן</a>. Y. Taan. IV, 68ᵈ, v. <a href=\"#\" data-headword=\"מְסַרְבַּיי\">מְסַרְבַּיי</a>. Mekh. B’shall., Vayassʿa, s. 6 <span dir=\"rtl\">כל … מְרִיבִין וכ׳</span> whenever you strive with me, you tempt God. Tanḥ. Mick. 10 <span dir=\"rtl\">עד … מֵרִיב עמו</span> while he was yet in his mother’s womb, Esau was contending with him. <span class=\"citation\">Num. R. s. 5</span> <span dir=\"rtl\">שלא יָרִיבוּ זה עם זה</span> that they might not quarrel with one another; <span dir=\"rtl\">היה זה מריב וכ׳</span> this one contended and said, I want to load here &amp;c.; a. fr.</div></div>","alt":["רוּב"]},"27510":{"h":"רִיב II","r":"T00581","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רִיב I\">preced.</a>) <i>strife, contest, cause</i>. <span class=\"citation\">Meg. 21ᵇ</span> <span dir=\"rtl\">רִיבֵנוּ</span>, v. <a href=\"#\" data-headword=\"רִיב I\">preced.</a>; a. e.—Pl. <span dir=\"rtl\">רִיבוֹת</span>, <span dir=\"rtl\">רִיבִים</span>. <span class=\"citation\">Lev. R. s. 9</span> <span dir=\"rtl\">מַצּוּת ור׳</span> ed. Wil. (oth. ed. only <a href=\"#\" data-headword=\"מַצּוּת\">מצות</a>) strife and lawsuits. <span class=\"citation\">Snh. 34ᵇ</span>; <span class=\"citation\">Nidd. 50ᵃ</span>; <span class=\"citation\">Sifré Deut. 208</span> (ref. to <span class=\"citation\">Deut. XXI, 5</span>) <span dir=\"rtl\">מקיש ר׳ לנגעים וכ׳</span> the text puts lawsuits on a level with plagues, as the former must be transacted in day-time &amp;c.; <span class=\"citation\">Yeb. 104ᵃ</span></div>","alt":[]},"27511":{"h":"רִיבָא","r":"T00582","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רִיבָה\">רִיבָה</a>, <i>maiden, young woman</i>. <span class=\"citation\">Targ. Y. Gen. XXIV, 14</span> (Ar. <span dir=\"rtl\">רביתא</span>). Ib. 16. Ib. XVIII, 21. <span class=\"citation\">Targ. Y. I Ex. XXIV, 10</span>; a. e.—Pl. <span dir=\"rtl\">רִיבָתָא</span>. <span class=\"citation\">Targ. Y. Gen. XXIV, 61</span> (ed. Vien. <span dir=\"rtl\">רִבְתָ׳</span>).</div>","alt":[]},"27512":{"h":"רִיבְדָּא","r":"T00583","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבְדָּא\">רִבְדָּא</a></div>","alt":[]},"27513":{"h":"רִיבָה","r":"T00584","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבָה\">רָבָה</a>) <i>young woman, maiden</i>. <span class=\"citation\">Yeb. 59ᵇ</span> <span dir=\"rtl\">מעשה בר׳ אחת וכ׳</span> it happened to a girl in Hithlu; <span class=\"citation\">Tosef. Nidd. I, 9</span>; <span class=\"citation\">Nidd. 9ᵇ</span>; Y. ib. I, beg. 48ᵈ; ib. 49ᵇ bot. <span class=\"citation\">Gen. R. s. 49</span> (play on <a href=\"#\" data-headword=\"רַבָּה I\">רבה</a>, <span class=\"citation\">Gen. XVIII, 20</span>) <span dir=\"rtl\">דינה של ר׳ אינו מניח וכ׳</span> the case of the girl (that was put to death by fire because she performed a charitable deed) lets me not be silent; <span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">על עיסקי ר׳</span> on account of the affairs concerning that girl; a. e.—Pl. <span dir=\"rtl\">רִיבוֹת</span>. <span class=\"citation\">Shek. VIII, 5</span> Var., v. <a href=\"#\" data-headword=\"רִבּוֹא\">רִבּוֹא</a> h.</div>","alt":[]},"27514":{"h":"רִיבּוֹא","r":"T00585","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבּוֹא\">רִבּוֹא</a></div>","alt":[]},"27515":{"h":"רִיבּוּי","r":"T00586","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבָה\">רָבָה</a>) </div><div class=\"sense\"><b>1)</b> <i>increase, plenty</i>. Esth. R. end <span dir=\"rtl\">מדות … בשפע בפירוי ובר׳</span> the good dispensations of the Lord come with liberality, fruitfulness, and plenty.</div><div class=\"sense\"><b>—2)</b>  (sub. <span dir=\"rtl\">בגדים</span>) <i>larger number of garments, investment of the high priest with the eight official garments</i>. <span class=\"citation\">Yoma 5ᵃ</span> (ref. to <span class=\"citation\">Ex. XXIX, 29</span> sq.) <span dir=\"rtl\">איתקש משיחה לר׳ מה ר׳ וכ׳</span> the anointing is put on a level with the investment, as the investment is continued for seven days, so is the anointing &amp;c. Ib. <span dir=\"rtl\">ר׳ שבעה … איכא בינייהו</span> they differ as to the seven days of investment and the seven days of anointment; a. e.</div><div class=\"sense\"><b>—3)</b> <i>extension of scope, widening qualification, amplification</i>, opp. <a href=\"#\" data-headword=\"מִיעוּט\">מִיעוּט</a>. <span class=\"citation\">Shebu. III, 5</span> (<span class=\"citation\">25ᵃ</span>) <span dir=\"rtl\">מר׳ הכתוב</span> I derive it from the amplification of the text (the addition of a general rule <span dir=\"rtl\">לכל אשר וכ׳</span>, <span class=\"citation\">Lev. V, 4</span>); ib. 26ᵃ. <span class=\"citation\">Men. 89ᵃ</span> <span dir=\"rtl\">אין ר׳ אחר ר׳ אלא למעט</span> an amplification following an amplification (as <span dir=\"rtl\">בשמן</span> in <span class=\"citation\">Lev. II, 4</span>) intimates a restriction; a. fr.—Pl. <span dir=\"rtl\">רִיבּוּיִין</span>, <a href=\"#\" data-headword=\"רִיבּוּי\">רִבּ׳</a>. <span class=\"citation\">Tosef. Shebu. I, 7</span>, v. <a href=\"#\" data-headword=\"מִיעוּט\">מִיעוּט</a>. <span class=\"citation\">Gen. R. s. 1</span>, a. e. <span dir=\"rtl\">אתין וגמין ר׳</span>, v. <a href=\"#\" data-headword=\"גַּם I\"><span dir=\"rtl\">גַּם</span> I</a>. <span class=\"citation\">Y. Sabb. XIX, 17ᵃ</span>, v. <a href=\"#\" data-headword=\"לָשׁוֹן\">לָשׁוֹן</a>; a. e.</div>","alt":["רִבּ׳"]},"27516":{"h":"רִיבּוּיָא","r":"T00587","html":"<div class=\"sense\">, <i>amplification</i>. <span class=\"citation\">Nidd. 33ᵃ</span> <span dir=\"rtl\">וכל ר׳ הוא</span> and the word <i>kol</i> (<span class=\"citation\">Lev. XV, 4</span>) is an amplification (and not a specification, <span dir=\"rtl\">פרט</span>). <span class=\"citation\">Zeb. 8ᵇ</span> <span dir=\"rtl\">לזבח ר׳ הוא</span> the word <i>l’zebaḥ</i> (<span class=\"citation\">Lev. III, 6</span>) is merely an amplification (and not a generalization <span dir=\"rtl\">כלל</span>). <span class=\"citation\">Shebu. 25ᵇ</span> <span dir=\"rtl\">דמר׳ דקראי אתו</span> which are derived from the amplification of Scriptural expressions, i.e. which are only implied, not explicitly stated. <span class=\"citation\">Yoma 6ᵃ</span> <span dir=\"rtl\">נדה וכל דאתי מר׳</span> the menstruant and all that is implied (all persons made unclean by contact with her); a. fr.—Pl. <a href=\"#\" data-headword=\"רִיבּוּיָא\">רִיבּוּיֵי</a>, <a href=\"#\" data-headword=\"רִיבּוּי\">רִבּ׳</a>. <span class=\"citation\">Shebu. 26ᵃ</span>; <span class=\"citation\">Snh. 45ᵇ</span>, v. <a href=\"#\" data-headword=\"מִיעוּטָא\">מִיעוּטָא</a>.</div>","alt":["רִיבּוּיָיא","רִבּ׳"]},"27517":{"h":"רִיבּוֹן","r":"T00588","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִיבּוּי\">רִבּ׳</a>.</div>","alt":["רִיבּוֹנָא","רִיבּוּנָא","רִיבּוֹנְתָּא"]},"27518":{"h":"רִיבּוּעַ","r":"T00589","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבַע\">רָבַע</a>) <i>a square</i>. <span class=\"citation\">Zeb. 62ᵃ</span> <span dir=\"rtl\">קרן … ור׳ מעכבין</span> the horn, the ascent, the foundation, and the square shape are indispensable conditions for the altar. <span class=\"citation\">Ib. 108ᵇ</span>; a. fr.—ר׳ עולם <i>the cardinal points of the world</i>. <span class=\"citation\">Tosef. Erub. VI (V), 3; Erub. 56</span><span class=\"citation\">Erub. 56ᵃ</span> <span dir=\"rtl\">בא לרבעה מרבעה בר׳ ע׳ וכ׳</span> when you square a town (for Sabbath limits, v. <a href=\"#\" data-headword=\"רָבַע\">רָבַע</a>), you must square it in accordance with the cardinal points, and the marks are Charles’s Wain in the north &amp;c. Ib. <span dir=\"rtl\">אם אינו … בר׳ וכ׳</span> if you do not know how to square it in accordance with the cardinal points &amp;c.; a. e.</div>","alt":["רִבּ׳"]},"27519":{"h":"רִיבּוּעַ ²","r":"T00590","html":"<div class=\"sense\"> <span class=\"citation\">Succ. 8ᵃ</span>, v. <a href=\"#\" data-headword=\"עִיגּוּל ²\">עִיגּוּלָא</a>. <span class=\"citation\">Erub. 57ᵃ</span>; <span class=\"citation\">B. Bath. 101ᵇ</span>, a. e. <span dir=\"rtl\">כל אמתא בר׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"אֲלַכְסוֹן\">אֲלַכְסוֹן</a>. <span class=\"citation\">Erub. 23ᵇ</span> <span dir=\"rtl\">איכא … ר׳ דרבעוה רבנן</span> (Ms. M. <span dir=\"rtl\">ר׳ דרבנן</span>) the difference between them refers to their attitude concerning the square which the (other) Rabbis adopt as a standard (seventy and a fraction by seventy and a fraction, Mish. <span class=\"citation\">ib. II, 5</span>); [differ. interpret. in Tosaf. a. l.; reference to Mish. ib. IV, 8].</div>","alt":["רִיבּוּעָא","רִבּ׳"]},"27520":{"h":"רֵיבוּתָא","r":"T00591","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*רְבֵי\">רְבֵי</a>) <i>youth, childhood</i>. <span class=\"citation\">Targ. Job XXXIII, 25</span> (some ed. <a href=\"#\" data-headword=\"רִיבּוּתָא\">רִיבְוָתָא</a>, corr. acc.; ed. Wil. <a href=\"#\" data-headword=\"רְבוּתָא\">רְבוּתָא</a>, read: <span dir=\"rtl\">רֵ׳</span>).</div>","alt":[]},"27521":{"h":"רִיבּוּתָא","r":"T00592","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבּוֹא\">רִבּוֹא</a> ch.</div>","alt":["רִיבּוֹתָא"]},"27522":{"h":"רִיבִּית","r":"T00593","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִיבּוּי\">רִבּ׳</a>.</div>","alt":["רִיבִּיתָא"]},"27523":{"h":"רִיבְעָא","r":"T00594","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבְעָא\">רִבְעָא</a></div>","alt":[]},"27524":{"h":"רִיבְעָה","r":"T00595","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְבַע\">רְבַע</a>) <i>sleeping accommodation</i>. <span class=\"citation\">Y. Sabb. XX, 17ᶜ</span> <span dir=\"rtl\">הוה ר׳ בבי מדרשא וכ׳</span> beds were improvised in the college hall (to be partitioned off in daytime by curtains).</div>","alt":[]},"27525":{"h":"רִיבְקָא","r":"T00596","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִיבּוּי\">רִבְ׳</a>.</div>","alt":["רִיבְקָה"]},"27526":{"h":"רִיגְגָא","r":"T00597","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְגָגָא\">רְגָגָא</a></div>","alt":[]},"27527":{"h":"רִיגּוּג","r":"T00598","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְגַג\">רְגַג</a>) <i>desire, desirable thing</i>. <span class=\"citation\">Targ. Y. Deut. XII, 20</span> (not <a href=\"#\" data-headword=\"רִגּוּג\">רְגוּג</a>), sq. <span class=\"citation\">Targ. II Chr. XII, 9</span>. <span class=\"citation\">Ib. XXXII, 27</span>. <span class=\"citation\">Targ. Ps. X, 3</span>; a. fr.—[<span class=\"citation\">Ib. V, 2</span> read: <span dir=\"rtl\">רנוני</span>, v. <a href=\"#\" data-headword=\"רִינּוּנָא\">רִינּוּנָא</a>.]—Pl. <span dir=\"rtl\">רִיגּוּגִין</span>, <span dir=\"rtl\">רִיגּוּגַיָּא</span>. <span class=\"citation\">Ib. CXL, 9</span>. <span class=\"citation\">Targ. Koh. XII, 11</span>. <span class=\"citation\">Targ. II Chr. XX, 25</span> (some ed. <span dir=\"rtl\">דגרוגין</span>, read: <span dir=\"rtl\">רִגְרוּגִין</span>); a. fr.</div>","alt":["רִיגּוּגָא","רִגְּ׳","רִגְרוּגָא"]},"27528":{"h":"רִיגּוּשׁ","r":"T00599","html":"<div class=\"sense\"> m. h., v. <a href=\"#\" data-headword=\"רֶגֶשׁ\">רֶגֶשׁ</a></div>","alt":[]},"27529":{"h":"רִיגּוּשׁ ²","r":"T00600","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"רְגַשׁ\">רְגַשׁ</a>) <i>commotion, excitement</i>. <span class=\"citation\">Targ. Is. XXII, 5</span> (ed. Wil. <a href=\"#\" data-headword=\"רִגּוּשׁ\">רְגוּשׁ</a>). <span class=\"citation\">Ib. X, 3</span>. <span class=\"citation\">Targ. Job XXXIX, 7</span>; v. <a href=\"#\" data-headword=\"רְגוֹשׁ\">רְגוֹשׁ</a>.</div>","alt":["רִיגּוּשָׁא","רִגּ׳"]},"27530":{"h":"רִיגְלָא","r":"T00601","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִיגּוּג\">רִגְ׳</a>.</div>","alt":["רִיגְלָאָה"]},"27531":{"h":"ריגלותא","r":"T00602","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּגָּלוּתָא\">דּגָּלוּתָא</a></div>","alt":[]},"27532":{"h":"*רִיגְלוּתָיָה","r":"T00603","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רְגִילָה II\"><span dir=\"rtl\">רְגִילָה</span> II</a>) <i>an inhabitant of lowlands</i>(?). <span class=\"citation\">Y. Bicc. III, 65ᵈ</span></div>","alt":[]},"27533":{"h":"רִיגְמָא","r":"T00604","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִגְמָא\">רִגְמָא</a></div>","alt":[]},"27534":{"h":"רידא","r":"T00605","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to VII, 9</span> <span dir=\"rtl\">לית את סגיד … דר׳ ליה וכ׳</span>, read: <span dir=\"rtl\">לית את סגיד לצלמא דידי אמר ליה וכ׳</span> wilt thou not bow to my idol? Said he (Daniel) to him, is there any reality in it?</div>","alt":[]},"27535":{"h":"רִידְוָותָא","r":"T00606","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (רְדֵי III) [<i>ploughers</i>,] <i>chariots armed with shears</i> or <i>scythes</i>. <span class=\"citation\">Targ. Y. I Ex. XIV, 25</span>; Y. II (some ed. <span dir=\"rtl\">ריתוו׳</span>, corr. acc.).</div>","alt":[]},"27536":{"h":"רַקִּיעַ","r":"T01031","html":"<div class=\"sense\">, v. <span dir=\"rtl\">רְּקוֹע</span></div>","alt":[]},"27537":{"h":"רָקִיעַ","r":"T01032","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>expanse, sky</i>, esp. <i>Raḳiʿa</i>, name of one of the seven heavens. <span class=\"citation\">Pes. 94ᵃ</span>, sq. <span class=\"citation\">Gen. R. s. 4</span>. <span class=\"citation\">Gen. R. s. 38</span>.—<span class=\"citation\">Ḥag. 12ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">רְקִיעִים</span>. Ib.</div>","alt":[]},"27538":{"h":"רְקִיעַ","r":"T01033","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. I, 6</span>, sq.; a. fr.—<span class=\"citation\">Ber. 58ᵇ</span> the Curtain (<a href=\"#\" data-headword=\"וִילוֹן\">וִילוֹן</a>) is rolled up, <span dir=\"rtl\">ומתחזי נהורא דר׳</span> and the light of the Raḳi‘a is seen. <span class=\"citation\">Ib.ᵃ</span>, v. <a href=\"#\" data-headword=\"מַלְכוּתָא\">מַלְכוּתָא</a>. <span class=\"citation\">Pes. 94ᵃ</span> <span dir=\"rtl\">סומכא דר׳</span> the thickness (depth) of the sky; a. fr.—Pl. <a href=\"#\" data-headword=\"רְבִיעִין\">רְקִיעִין</a>. <span class=\"citation\">Targ. Y. I Num. XXIV, 6</span>.</div>","alt":["רְקִיעָא I"]},"27539":{"h":"רְקִיעָא II","r":"T01034","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְקַע\">רְקַע</a>, v. <a href=\"#\" data-headword=\"רְקוֹעַ\">רְקוֹעַ</a>) <i>patch, rag.</i> <i>—Pt.</i> constr. <span dir=\"rtl\">רְקִיעֵי</span>. <span class=\"citation\">Targ. Ez. XIII, 18</span> <span dir=\"rtl\">ר׳ חשוך</span> (ed. Lag. <span dir=\"rtl\">רִקְעֵי</span>) dark rags (h. text <span dir=\"rtl\">כסתות</span>). <span class=\"citation\">Ib. 20</span> <span dir=\"rtl\">ר׳ חשוככן</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">חשיכין</span>, corr. acc.).</div>","alt":[]},"27540":{"h":"רָקִיק","r":"T01035","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> רקק <i>to beat, flatten</i>, <i>wafer</i>. <span class=\"citation\">B. Bath. 19ᵇ</span>, opp. <a href=\"#\" data-headword=\"עָבָה I\">עבה</a> thick cake; a. e.—Pl. <span dir=\"rtl\">רְקִיקִים</span>, <span dir=\"rtl\">רְקִיקִין</span>. <span class=\"citation\">Men. VI, 3</span> (<span class=\"citation\">74ᵇ</span>) <span dir=\"rtl\">הר׳ משוחים</span> (Bab. ed. <span dir=\"rtl\"><span dir=\"rtl\">ור׳</span> (<span dir=\"rtl\">טעונים</span>) <a href=\"#\" data-headword=\"מְשִׁיחָה I\">משיחה</a>)</span> wafers as sacrifices must be ointed. Ib. 75ᵃ; a. fr.</div>","alt":[]},"27541":{"h":"רְקִיקָה","r":"T01036","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָקַק\">רָקַק</a>) <i>spitting</i>. Tosef. Ber. VII (VI), 19 <span dir=\"rtl\">ור׳ מקל וחומר</span> and spitting (on the Temple mount is forbidden) a fortiori; ib. <span dir=\"rtl\">ר׳ … בזיון</span> spitting, which is an act of contempt; Y. ib. IX, 14ᶜ. <span class=\"citation\">Yeb. 105ᵃ</span> <a href=\"#\" data-headword=\"ר׳\">ר׳</a> the spitting by the <i>y’bamah</i> (<span class=\"citation\">Deut. XXV, 9</span>). <span class=\"citation\">Snh. 101ᵃ</span>, v. <a href=\"#\" data-headword=\"רָקַק\">רָקַק</a>; a. fr.</div>","alt":[]},"27542":{"h":"רְקִיתָא","r":"T01037","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. b. h. <a href=\"#\" data-headword=\"רֵקָה\">רַקָּה</a>) <i>temple</i>. <span class=\"citation\">Targ. Y. Deut. XVIII, 3</span> <span dir=\"rtl\">לוחייא דר׳</span> (Ar. <a href=\"#\" data-headword=\"דְּרוּקֶרֶת\">דדק׳</a>, incorr.) the upper jaws.</div>","alt":[]},"27543":{"h":"רַקִּיתָא","r":"T01038","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רְקִיתָא\">preced.</a>) [<i>the shining</i>,] <i>chameleon</i>, v. <a href=\"#\" data-headword=\"זָקִיתָא\">זָקִיתָא</a>.</div>","alt":[]},"27544":{"h":"רָקַם","r":"T01039","html":"<div class=\"sense\"> (b. h.) <i>to variegate, embroider</i>. <span class=\"citation\">Yoma 72ᵇ</span> <span dir=\"rtl\">רוֹקְמִין</span>, v. <a href=\"#\" data-headword=\"חָשַׁב\">חָשַׁב</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">רוֹקֵם מעשה וכ׳</span> the embroiderer’s is needle work, therefore it has only one face; a. e.</div><div class=\"sense\"><b>Pi. רִיקֵּם</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רַקִּיתָא\">same</a>, trnsf. (v. <span class=\"citation\">Ps. CXXXIX, 15</span>) <i>to form the limbs of an embryo, shape</i>. <span class=\"citation\">Lev. R. s. 29</span>, beg.; <span class=\"citation\">Pesik. R. s. 46</span> <span dir=\"rtl\">שלישית ביום צבר … רִיקְּמוֹ</span> at three hours of the day he gathered his (Adam’s) dust, at four he kneaded him, at five he shaped him; <span class=\"citation\">Midr. Till. to Ps. XCII</span> <span dir=\"rtl\">חמשית … ששית רקמו</span> at five he made him a shapeless body, at six he articulated him. Y. Bets. I, 60ᵃ <span dir=\"rtl\">בצים שרִיקֵּימוּ גוזלים שלא העלו עליהן וכ׳</span> (not <span dir=\"rtl\">העליהן</span>) eggs which developed chicks without a formation of wings. <span class=\"citation\">Ḥull. 64ᵃ</span> <span dir=\"rtl\">אם רִיקְּמָה וניקבה</span> if the egg had developed a distinct embryo, and was perforated; a. e.—Part. pass. <span dir=\"rtl\">מְרוּקָּם</span>; f. <span dir=\"rtl\">מְרוּקֶּמֶת</span>. <span class=\"citation\">Esth. R. to III, 1</span> <span dir=\"rtl\">עשה לו צלם מר׳ וכ׳</span> he (Haman) made himself an image embroidered on his garment over his breast. <span class=\"citation\">Nidd. III, 3</span> (<span class=\"citation\">24ᵇ</span>) <span dir=\"rtl\">ואם היה מר׳</span> and if the fœtus was articulated. Y. ib. 50ᵈ top, v. <a href=\"#\" data-headword=\"רָשׁוֹן\">רָשׁוֹן</a>. Tosef. ib. IV, 12. <span class=\"citation\">Ḥull. IX, 6</span> (<span class=\"citation\">126ᵇ</span>) <span dir=\"rtl\">ביצת השרץ המר׳</span> the egg of a creeping thing (serpent &amp;c.) in a developed state; a. e.</div></div>","alt":[]},"27545":{"h":"רֶקֶם I","r":"T01040","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָקַם\">preced.</a>) <i>embroidery.</i>—Pl. <span dir=\"rtl\">רְקָמִים</span>, constr. <span dir=\"rtl\">רִקְמֵי</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Ab. Zar. 24ᵇ</span> (in an apostrophe to the Ark of the Covenant) <span dir=\"rtl\">המחושקת בר׳ זהב</span> who art lovely in gold-embroidered garments (gold-plated); <span class=\"citation\">Gen. R. s. 54</span>; <span class=\"citation\">Yalk. Sam. 103</span>; Midr. Sam. ch. XII <span dir=\"rtl\">כרומי</span> (corr. acc.).</div>","alt":[]},"27546":{"h":"רֶקֶם II","r":"T01041","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Rekem</i>, in Benjamin. <span class=\"citation\">Targ. Josh. XVIII, 27</span>.</div>","alt":[]},"27547":{"h":"רְקָם I","r":"T01042","html":"<div class=\"sense\">) pr. n. pl. <i>R’ḳam</i> (or <i>Reḳem</i>); </div><div class=\"sense\"><b>1)</b>  also <span dir=\"rtl\">ר׳ דחגרא</span> <i>Sela</i> (Petra) in Edom (v. Hildesh. Beitr. p. 52 sq.) <span class=\"citation\">Targ. Gen. XIV, 7</span> (Y. ed. Vien. <a href=\"#\" data-headword=\"רֵיקָם\">רֵיקָם</a>; h. text <span dir=\"rtl\">קדש</span>). Ib. XX, 1; a. e.—<span class=\"citation\">Gitt. I, 1</span> <span dir=\"rtl\">המביא מן הר׳ ומן החגר</span> if a messenger brings a letter of divorce from the district of R. or of Ḥagar. <span class=\"citation\">Nidd. VIII, 3</span>; a. e.—<span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">ר׳ תחגרא</span> (read: <span dir=\"rtl\">דחגרא</span>); <span class=\"citation\">Yalk. ib. 874</span> <span dir=\"rtl\">רגם דח׳</span>; <span class=\"citation\">Tosef. Shebi. IV, 11</span> ed. Zuck. (Var. <span dir=\"rtl\">ורכה דדוגרא</span>, corr. acc.).</div><div class=\"sense\"><b>—2)</b>  רְקַם גֵּיאָה <i>R’ḳam Geah</i> = Kadesh Barnea. <span class=\"citation\">Targ. Num. XXXIV, 4</span>. <span class=\"citation\">Targ. Josh. XV, 3</span>; a. e.—Sifré l. c.; Yalk. l. c. (not <a href=\"#\" data-headword=\"גַּאֲוָה\">גאוה</a>); Tosef. l. c. (Var. <span dir=\"rtl\">נאה</span>, corr. acc.); Y. Shebi. V, 36ᶜ <span dir=\"rtl\">ר׳ דגועה</span>.</div>","alt":["רֶקֶם"]},"27548":{"h":"רְקָם II","r":"T01043","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רֶקֶם I\"><span dir=\"rtl\">רֶקֶם</span> I</a>, <i>embroidered garment</i>. <span class=\"citation\">Targ. Ez. XXVII, 16</span> (h. text <a href=\"#\" data-headword=\"רִקְמָה\">רקמה</a>).</div>","alt":[]},"27549":{"h":"רִקְמָא","r":"T01044","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְקָם II\">preced.</a>) <i>checker, spot.</i>—Pl. <span dir=\"rtl\">רִקְמֵי</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Sabb. 107ᵇ</span> (ref. to <span class=\"citation\">Jer. XIII, 23</span>) <span dir=\"rtl\">מאי … דקאי ר׳ ר׳ וכ׳</span> what does <i>ḥăbharbarothav</i> mean? shall I say, it means checkered? Then it ought not to read <i>ḥăb</i>., but <i>gavvanav</i> (its colors).—V. <a href=\"#\" data-headword=\"רִקְמְתָא\">רִקְמְתָא</a>.</div>","alt":["רִי׳"]},"27550":{"h":"רִקְמָה","r":"T01045","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) = <a href=\"#\" data-headword=\"רֶקֶם I\"><span dir=\"rtl\">רֶקֶם</span> I</a>, <i>embroidered garment</i>. <span class=\"citation\">Lam. R. to I, 1</span>, a. e., v. <a href=\"#\" data-headword=\"אַפִּיקִילְטָא\">אַפִּיקִילְטָא</a>.</div>","alt":[]},"27551":{"h":"רִקְמְתָא","r":"T01046","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רִקְמָה\">preced.</a> wds.) <i>checkers, spots</i>. <span class=\"citation\">Targ. Jer. XIII, 23</span>, v. <a href=\"#\" data-headword=\"רִקְמָא\">רִקְמָא</a>.</div>","alt":[]},"27552":{"h":"רקן","r":"T01047","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיקֵן I\">רִיקֵן</a>, <a href=\"#\" data-headword=\"רוֹקֵן\"><a href=\"#\" data-headword=\"רוֹקֵן\">רוֹקן</a>.</a></div>","alt":[]},"27553":{"h":"רָקַע","r":"T01048","html":"<div class=\"sense\"> (b. h.) [<i>to beat</i>,] <i>to stretch, spread</i>.</div><div class=\"sense\"><b>Hif. הִרְקִיעַ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רקן\">same</a>. <span class=\"citation\">Midr. Till. to Ps. CXLVI, 5</span> <span dir=\"rtl\">משמתחתי … והִרְקַעְתִּי הארץ וכ׳</span> since I stretched the heaven and spread the land (over the water), have they ever moved from their position?</div><div class=\"sense\"><b>—2)</b>  (in enigmatic speech, denom. of <a href=\"#\" data-headword=\"רָקִיעַ\">רָקִיעַ</a>) <i>to make to look blue</i>. <span class=\"citation\">Erub. 53ᵇ</span> הַרְקִיעוּ Ms. M. (ed. <span dir=\"rtl\">אַרְקִיעוּ</span>), v. <a href=\"#\" data-headword=\"זָהָב\">זָהָב</a>; [Rashi: <i>spread</i> the glowing coals].—[<span class=\"citation\">Tosef. B. Bath. XI, 9</span> <span dir=\"rtl\">שהרקיע</span> ed. Zuck., read: <span dir=\"rtl\">שהִרְקִיב</span>.]</div></div>","alt":[]},"27554":{"h":"רְקַע","r":"T01049","html":"<div class=\"sense\"><i>Af</i>. <span dir=\"rtl\">אַרְקַע</span> <a href=\"#\" data-headword=\"רָקַע\">same</a>. <span class=\"citation\">Targ. Job XXXVII, 18</span> <span dir=\"rtl\">תַּרְקַע</span> (ed. Wil. <a href=\"#\" data-headword=\"תִּירְיָיקָא\">תִּרְ׳</a>).</div><div class=\"sense\"><b>Pa. רַקּעַ</b> <div class=\"sense\"><i>to patch</i>.—Part. pass. <a href=\"#\" data-headword=\"מַרְקַע\">מְרַקַּע</a>. <span class=\"citation\">Targ. Josh. IX, 5</span> ed. Wil. <span dir=\"rtl\">מְרַקְּעִין</span> (Ar. <span dir=\"rtl\">מְרַקְּעָן</span>; ed. Lag. <span dir=\"rtl\">מרקיעין</span>, corr. acc.; some ed. <span dir=\"rtl\">מְרוּקָּעִין</span> Hebraism; h. text <span dir=\"rtl\">מטלאות</span>).—V. <a href=\"#\" data-headword=\"מַרְקוֹעַ II\"><span dir=\"rtl\">מַרְקוֹעַ</span> II</a>.</div></div>","alt":[]},"27555":{"h":"רָקַק","r":"T01050","html":"<div class=\"sense\"> (b. h.) <i>to spit</i>. <span class=\"citation\">B. Kam. VIII, 6</span> <span dir=\"rtl\">ר׳ והגיע בו רוקו</span> if a person spat (at his neighbor), and his spittle touched him. <span class=\"citation\">Snh. 101ᵃ</span> <span dir=\"rtl\">וברוֹקֵק בה … על הרקיקה</span> that is when he spits at it (while reciting a Bible verse as a charm for a wound), for the name of God must not be pronounced in connection with spitting. <span class=\"citation\">Y. Ber. III, 6ᵈ</span> bot. <span dir=\"rtl\">הרוקק … כרוקק וכ׳</span> he that spits in the synogogue is considered as if spitting at the pupil of his eye (euphem. for God). <span class=\"citation\">Yeb. 105ᵃ</span> <span dir=\"rtl\">שרָקְקָה דם</span> who (in spitting before the <i>yabam</i>) spat blood; Y. ib. XII, end, 13ᵃ <a href=\"#\" data-headword=\"רֵקָה\">רַקָּה</a> (or <a href=\"#\" data-headword=\"רֵקָה\">רָקָה</a>, fr. <a href=\"#\" data-headword=\"רוּק\">רוּק</a>). <span class=\"citation\">Ḥag. 5ᵃ</span> (ref. to <span class=\"citation\">Koh. XII, 14</span>) <span dir=\"rtl\">זה הרָק בפני חבירו וכ׳</span> this refers to one who spits in his neighbor’s presence and becomes disgusting (v. <a href=\"#\" data-headword=\"מָאַס\">מָאַס</a>). <span class=\"citation\">Tosef. B. Kam. IX, 31</span>, v. <a href=\"#\" data-headword=\"טוּשׁ\">טוּשׁ</a> h.; a. fr.</div><div class=\"sense\"><b>Pi. רִקֵּק</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רְקַע\">same</a>. <span class=\"citation\">Yalk. Is. 339</span> (ref. to <span class=\"citation\">Ps. IV, 3</span>) <span dir=\"rtl\">עד מתי  … מְרַקְּקִין בו וכ׳</span></div></div><div class=\"sense\"><b>Nif. נָרוֹק</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָקָק\">רָקָק</a>) <i>to be miry</i>. <span class=\"citation\">Mikv. VII, 1</span> <span dir=\"rtl\">חטיט הנ׳</span> soft, miry clay (in the bath reservoir); <span class=\"citation\">Zeb. 22ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">הנדוק</span>); <span class=\"citation\">Succ. 19ᵇ</span> (v. Rabb. D. S. a. l. note 40).</div></div>","alt":["רוּק"]},"27556":{"h":"רְקַק","r":"T01051","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Lev. XV, 8</span> <a href=\"#\" data-headword=\"יָרוֹק\">יְרוֹק</a> (Y. <span dir=\"rtl\">יְרִיק</span>). <span class=\"citation\">Targ. Deut. XXV, 9</span>.—Part. <a href=\"#\" data-headword=\"רָקִיק\">רָקֵיק</a>; pl. <span dir=\"rtl\">רְקִיקִין</span>. Targ. II Esth. III, 8.—<span class=\"citation\">Koh. R. to VII, 9</span> <span dir=\"rtl\">כל דר׳ לעיל וכ׳</span> if a person spits upward, it will fall in his face (an angry person hurts himself). Y. Yeb. XII, end, 13ᵃ top <span dir=\"rtl\">ורַקַּת קדמנא וכ׳</span> she spat before us &amp;c., v. <a href=\"#\" data-headword=\"רוֹק ²\">רוּקָּא</a>; Bab. <span class=\"citation\">ib. 39ᵇ</span> <span dir=\"rtl\">וירקת</span>. <span class=\"citation\">Ib. 106ᵃ</span> <span dir=\"rtl\">אכלה תומא ורַקְּתָה</span> if she ate garlic and had to spit. <span class=\"citation\">Lev. R. s. 9</span> <span dir=\"rtl\">עד דאזלת ורוּקַּת וכ׳</span> until thou goest and spittest in that preacher’s (R. Meir’s) face; <span class=\"citation\">ib.</span> <span dir=\"rtl\">רוּקִי באנפי וכ׳</span> spit in my face seven times; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ואנא רַקִּית וכ׳</span> and I spat &amp;c.; <span class=\"citation\">Num. R. s. 9</span><sup>20</sup>; <span class=\"citation\">Y. Sot. I, 16ᵈ</span> bot. <span dir=\"rtl\">ורוֹקְקִין בגויה וכ׳</span> spit into it (my eye) &amp;c.; a. e.</div>","alt":["רוּק","רִיק"]},"27557":{"h":"רָקָק","r":"T01052","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְקַק\">preced.</a> wds.) <i>diluvium, pool, shallow</i>. <span class=\"citation\">Sabb. XI, 4</span> <span dir=\"rtl\">אם היה רְקַק מים וכ׳</span> if there is a pool (on the shore), and the public road crosses it; <span dir=\"rtl\">וכמה הוא ר׳ מים</span>, and how deep must it be to be called a pool? <span class=\"citation\">Erub. 43ᵃ</span> <span dir=\"rtl\">במהלכת בר׳</span> when the ship moves in diluvial water. <span class=\"citation\">Ḥull. 27ᵇ</span> <span dir=\"rtl\">מן הר׳ נבראו</span> birds were created out of alluvial mud; <span class=\"citation\">Erub. 28ᵃ</span>; <span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">דגי ר׳</span>, v. <a href=\"#\" data-headword=\"לִוְיָתָן\">לִוְיָתָן</a>; a. e.</div>","alt":[]},"27558":{"h":"רְקָקָא","r":"T01053","html":"<div class=\"sense\">—Pl. constr. <span dir=\"rtl\">רְקָקֵי</span>. <span class=\"citation\">Targ. Y. Gen. I, 20</span>.</div>","alt":[]},"27559":{"h":"רקקה","r":"T01054","html":"<div class=\"sense\">, <span class=\"citation\">Y. Snh. I, 18ᶜ</span> bot., v. <a href=\"#\" data-headword=\"דְּקָקָה\">דְּקָקָה</a></div>","alt":[]},"27560":{"h":"רַקְרַק","r":"T01055","html":"<div class=\"sense\"><i>raḳraḳ</i>, imitation of a bird’s shriek. <span class=\"citation\">Ḥull. 63ᵃ</span> Ar., v. <a href=\"#\" data-headword=\"שְׁרַק II\"><span dir=\"rtl\">שְׁרַק</span> I</a>.</div>","alt":[]},"27561":{"h":"רַקַּת","r":"T01056","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Rakkath</i>, a fortified town of Naftali. <span class=\"citation\">Meg. 6ᵃ</span> ר׳ זו ציפורי … כרקתא וכ׳ R. is Sepphoris, and its name was Rakkath, because it lies high like the banks of a river. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ר׳ זו טבריא</span> R. is Tiberias. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">איכא … ר׳ לאו טבריא היא וכ׳</span> is there any one that can say, R. is not Tiberias? when one dies here (in Babylonia), do they not eulogize him there in (Tiberias): <span dir=\"rtl\">גרול הוא בששך ושם לו בר׳</span> he was great in Sheshakh (Babylonia), and had a name in Rakkath? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יושבי ר׳ צאו וכ׳</span> citizens of R., go forth and receive the dead of the valley (Babylonia); a. e.</div>","alt":[]},"27562":{"h":"רַקְּתָא","r":"T01057","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָקָק\">רָקָק</a>) <i>alluvial ground, bank</i>. <span class=\"citation\">Meg. 6ᵃ</span> v. <a href=\"#\" data-headword=\"רַקַּת\">preced.</a> <span class=\"citation\">B. Mets. 108ᵃ</span> <span dir=\"rtl\">האי מאן דאחזיק בר׳ דנהרא וכ׳</span> he who takes possession of the alluvial ground of a river (or canal) is considered an impudent man, but cannot be removed. <span class=\"citation\">Succ. 26ᵃ</span> <span dir=\"rtl\">הוו גנו אר׳ דסורא</span> they used to sleep on a bank of Sura. <span class=\"citation\">Bets. 32ᵇ</span> <span dir=\"rtl\">ר׳ דפרת</span> the clayey alluvium of the Euphrates; a. e.—[<span class=\"citation\">B. Bath. 26ᵃ</span> top <a href=\"#\" data-headword=\"רַקְּתָא\">רקתא</a>, v. <a href=\"#\" data-headword=\"דַּקְתָּא\">דַקְתָּא</a>.]</div>","alt":[]},"27563":{"h":"רָר","r":"T01058","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיר\">רִיר</a></div>","alt":[]},"27564":{"h":"רְרַב","r":"T01059","html":"<div class=\"sense\">, <i>Ithpa.</i> <span dir=\"rtl\">אִתְרָרַב</span>, v. <a href=\"#\" data-headword=\"רַבְרֵב\">רַבְרֵב</a>.</div>","alt":[]},"27565":{"h":"רְרַם","r":"T01060","html":"<div class=\"sense\">, <i>Part.</i> <i> Pa.</i> <a href=\"#\" data-headword=\"מְרָמַם\">מְרָרַם</a>, v. <a href=\"#\" data-headword=\"רוּם\">רוּם</a> ch.</div>","alt":[]},"27566":{"h":"רָשׁ","r":"T01061","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>dispossessed</i>, cmp. <a href=\"#\" data-headword=\"דַּל I\">דַּל</a>,] <i>poor</i>. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">רש מן הנכסים</span> the poor man is called <i>râsh</i>, because he is dispossessed of property. <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">Prov. XXIX, 13</span>) <span dir=\"rtl\">זהו רש בתורה</span> this means one bare of learning. Ib. (ref. to ib. XXII, 2) <span dir=\"rtl\">אמר אותו רש לאותו עשיר</span> that poor (ignorant) man says to the rich man, teach me &amp;c. <span class=\"citation\">Deut. R. s. 9</span> <span dir=\"rtl\">אתמול … ועכשיו הוא מסיח כרש וכ׳</span> yesterday he (Moses) spoke like a rich man (ref. to <span class=\"citation\">Ex. XXXII, 12</span>; <span class=\"citation\">Num. XIV, 19</span>), but now he speaks like a poor man (begging, ref. to <span class=\"citation\">Deut. III, 23</span>); a. e.—Pl. <span dir=\"rtl\">רָשִׁים</span>, <span dir=\"rtl\">רָשִׁין</span>. <span class=\"citation\">Lev. R. s. 31</span> (ref. to <span class=\"citation\">Cant. VII, 6</span> <span dir=\"rtl\">ודלת</span>) <span dir=\"rtl\">הר׳ שבכם וכ׳</span> the poorest (in mind) among you are as precious to me as Elijah &amp;c.; Cant. R. l. c. <span class=\"citation\">Meg. 11ᵃ</span> (play on <span dir=\"rtl\">אחשורוֹשׁ</span>, <span class=\"citation\">Esth. I, 1</span>) <span dir=\"rtl\">שהכל נעשו רשין בימיו</span> Ms. M. (ed. <span dir=\"rtl\">רָאשִׁין</span>) all became poor in his days (with ref. to <span class=\"citation\">Esth. X, 1</span>). <span class=\"citation\">Koh. R. to V, 7</span>, v. <a href=\"#\" data-headword=\"עֵשָׂו\">עֵשָׂו</a>; a. fr.</div>","alt":[]},"27567":{"h":"רֵשָׁא","r":"T01062","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵישׁ II\">רֵישָׁא</a></div>","alt":[]},"27568":{"h":"רְשָׁא","r":"T01063","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְשֵׁי\">רְשֵׁי</a></div>","alt":[]},"27569":{"h":"רַשָּׁאָה","r":"T01064","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַשַּׁאי\">next w.</a></div>","alt":[]},"27570":{"h":"רַשַּׁאי","r":"T01065","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָשָׁה\">רָשָׁה</a>) </div><div class=\"sense\"><b>1)</b> <i>having power, empowered, entitled to, permitted</i>. <span class=\"citation\">Sabb. 104ᵃ</span> <span dir=\"rtl\">אין הנביא ר׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"חָדַשׁ\">חָדַשׁ</a>. <span class=\"citation\">Peah VII, 5</span> <span dir=\"rtl\">בשלו הוא ר׳ ואינו ר׳ וכ׳</span> he has power of disposal over that which belongs to him, but not over that which belongs to the poor. <span class=\"citation\">Arakh. VIII, 4</span> <span dir=\"rtl\">אין אדם ר׳ להחרים וכ׳</span> no man has a right to vow &amp;c., v. <a href=\"#\" data-headword=\"חָרַם\">חָרַם</a>; a. fr.—Pl. <span dir=\"rtl\">רַשָּׁאִים</span>, <span dir=\"rtl\">רַשָּׁאִין</span>. <span class=\"citation\">Ab. IV, 8</span> <span dir=\"rtl\">אל תאמר קבלו דעתי שהן ר׳ וכ׳</span> say not (to your fellow judges) accept my opinion, for theirs is the power (as a majority), not thine. <span class=\"citation\">B. Bath. 8ᵇ</span>; a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"רַשָּׁאָה\">רַשָּׁאָה</a>. <span class=\"citation\">Tosef. Yeb. VIII, 4</span> <span dir=\"rtl\">האשה ר׳ שתינשא וכ׳</span> a woman is permitted to marry even a eunuch. Ib. <span dir=\"rtl\">האשה רשאי</span> (corr. acc.).</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"רְשֵׁי\">רְשֵׁי</a>) <i>owing, bound to</i>. <span class=\"citation\">Arakh. VIII, 7</span> <span dir=\"rtl\">אומדים … עולה שאינו ר׳</span> we estimate how much a man would pay for it to offer it as a burnt-offering which he is not bound to offer.</div>","alt":[]},"27571":{"h":"רַשַּׁאי ²","r":"T01066","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ruth IV, 4</span> (ed. Vien. <span dir=\"rtl\">רְשָׁאִי</span>).—<span class=\"citation\">Esth. R. to I, 4</span> <span dir=\"rtl\">בנפשי אנא רשיי … לית אנא יכיל ולא ר׳</span> over what concerns myself I have a right (of disposal as I please), but over that which is commanded by my Creator (charity) I have no power or authority.—Pl. <span dir=\"rtl\">רַשָּׁאִין</span>. <span class=\"citation\">Targ. Y. Ex. XXIII, 19</span> (ed. Vien. <a href=\"#\" data-headword=\"רְשָׁא\">רְשָׁ׳</a>); a. fr.</div>","alt":["רַשַּׁיי"]},"27572":{"h":"רִשַּׁאי","r":"T01067","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Rishshai</i>. <span class=\"citation\">Ḥull. 80ᵃ</span> Ar. (Ms. H. <span dir=\"rtl\">רִישַׁאי</span>, v. Rabb. D. S. a. l. note 90; ed. <span dir=\"rtl\">דושאי</span>).</div>","alt":[]},"27573":{"h":"רָשָׁאנָא","r":"T01068","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רַשַּׁאי\">רַשַּׁאי</a>) <i>ruler, officer</i>. <span class=\"citation\">Targ. Prov. XXV, 15</span> (ed. Lag. <a href=\"#\" data-headword=\"רֵאשָׁנָא\">רֵאשָׁנָא</a>, fr. <a href=\"#\" data-headword=\"רֹאשׁ ²\">רֵאשָׁא</a>; Var. <span dir=\"rtl\">רשא׳</span>; Levita <a href=\"#\" data-headword=\"רָשָׁאנָא\">רַשְׁאָנָא</a>, Bxt. <a href=\"#\" data-headword=\"רֵישָׁנָא\">רֵישָׁנָא</a>; h. text <a href=\"#\" data-headword=\"קָצִין\">קָצִין</a>).</div>","alt":[]},"27574":{"h":"רִשְׁבָּא","r":"T01069","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">רשב</span>, cmp. <a href=\"#\" data-headword=\"רֶשֶׁף\">רשף</a>, v. <a href=\"#\" data-headword=\"נִשְׁבִּים\">נִשְׁבִּים</a>) <i>trap;</i> trnsf. (sub. <span dir=\"rtl\">בעל</span>) <i>fowler</i>; also surname of a family, <i>Rishba</i>. <span class=\"citation\">Sabb. 130ᵃ</span>; <span class=\"citation\">Ḥull. 116ᵃ</span> יוסף ר׳ Joseph the fowler.—<span class=\"citation\">Sabb. 146ᵇ</span>; <span class=\"citation\">Taan. 10ᵃ</span> Taboth Rishba (the fowler, Rashi; oth. opin. = <span dir=\"rtl\">ריש בי אבא</span> chief of the family). <span class=\"citation\">B. Bath. 126ᵇ</span> <span dir=\"rtl\">מר זוטרא מדר׳</span> (Ms. M. <span dir=\"rtl\">מר בר רושבא</span>; Ms. H. <span dir=\"rtl\">מידרוּשְׁבָּנָא</span>; Ms. R. <span dir=\"rtl\">מדרשיכא</span>; Alf. <span dir=\"rtl\">מדרישכא</span>; Ms. Alf. <span dir=\"rtl\">מדרישבא</span>) Mar Zutra of the house of R.</div>","alt":["רִישְׁ׳"]},"27575":{"h":"רִשְׁבִּין","r":"T01070","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"רִשְׁבָּא\">preced.</a>) <i>traps</i>. <span class=\"citation\">B. Kam. VII, 7</span> (<span class=\"citation\">79ᵇ</span>), quot. in Rashi to <span class=\"citation\">Ḥull. 116ᵃ</span> (Mish. ed. <a href=\"#\" data-headword=\"נִישְׁבָּא\">נישבים</a>; Bab. ed. <span dir=\"rtl\">נישובין</span>, v. <a href=\"#\" data-headword=\"נִישְׁבָּא\">נִישְׁבִּים</a>).</div>","alt":["רִישְׁ׳"]},"27576":{"h":"רָשָׁה","r":"T01071","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רשי\">רשי</a></div>","alt":[]},"27577":{"h":"רָשׁוּ","r":"T01072","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְשׁוּתָא\">רָשׁוּתָא</a></div>","alt":["רְשׁוּ"]},"27578":{"h":"רָשׁוּם","r":"T01073","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹשַׁם\">רוֹשַׁם</a></div>","alt":[]},"27579":{"h":"רִשּׁוּם","r":"T01074","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִשְׁבָּא\">רִישּׁ׳</a>.</div>","alt":["רִשּׁוּמָא"]},"27580":{"h":"רָשׁוֹן","r":"T01075","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָשַׁשׁ\">רשש</a>) <i>rashon</i>, a species of <i>locusts</i> (= b. h. <a href=\"#\" data-headword=\"סָלְעָם\">סָלְעָם</a>). <span class=\"citation\">Ḥull. 65ᵃ</span>; Sifra Sh’mini, Par. 3, ch. V; <span class=\"citation\">Yalk. Lev. 537</span>. <span class=\"citation\">Ḥull. 65ᵇ</span> חרגול זה ר׳ <i>ḥargol</i> (<span class=\"citation\">Lev. XI, 22</span>) means <i>rashon</i>. Ib. 66ᵃ. <span class=\"citation\">Y. Nidd. III, 50ᵈ</span> top <span dir=\"rtl\">איזהו … כל שתחלת ברייתו דומה לר׳</span> what is the articulated embryo of which they speak? One that in its early stage resembles the shape of a <i>rashon</i>; <span class=\"citation\">Tosef. Nidd. IV, 10</span> <span dir=\"rtl\">ברושם</span> (Var. <span dir=\"rtl\">בראשו</span>, corr. acc.); Bab. <span class=\"citation\">Nidd. 25ᵃ</span> כר׳ Ar. (ed. <span dir=\"rtl\">מראשו</span>, corr. acc.); <span class=\"citation\">Lev. R. s. 14</span> <span dir=\"rtl\">צורת … דומה לר׳</span> how is the embryo formed? At first it resembles &amp;c.; <span class=\"citation\">Yalk. ib. 547</span>.</div>","alt":[]},"27581":{"h":"רָשׁוֹנָא","r":"T01076","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Lev. XI, 22</span> ed. Berl. (Ms. I <span dir=\"rtl\">רַשּׁוֹ׳</span>; ed. Vien. a. oth. <span dir=\"rtl\">דש׳</span>; Y. ed. Vien. <a href=\"#\" data-headword=\"רִשּׁוּם\">רִשּׁוּ׳</a>). <span class=\"citation\">Targ. Ps. CV, 34</span> (ed. Wil. <a href=\"#\" data-headword=\"רָגִיג\">רְ׳</a>; h. text <a href=\"#\" data-headword=\"יֶלֶק\">ילק</a>).</div>","alt":[]},"27582":{"h":"רָשׁוֹשׁ","r":"T01077","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָשַׁשׁ\">רָשַׁשׁ</a>) <i>wheat-stamper, groats-maker.</i>—Pl. <span dir=\"rtl\">רָשׁוֹשׁוֹת</span>, constr. <span dir=\"rtl\">רָשׁוֹשֵׁי</span>. <span class=\"citation\">M. Kat. II, 5</span> (<span class=\"citation\">13ᵇ</span>, v. Rabb. D. S. a. l. note 70). Ib. 13ᵇ <span dir=\"rtl\">ר׳ ציפורי</span>; v. <a href=\"#\" data-headword=\"דָּשֹׁושׁ\">דָּשׁוֹשׁ</a>.</div>","alt":[]},"27583":{"h":"רְשׁוּשִׁין","r":"T01078","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְשָׁשִׁין\">רְשָׁשִׁין</a></div>","alt":[]},"27584":{"h":"רָשׁוּת I","r":"T01079","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"רָשׁ\">רָשׁ</a>) <i>poverty</i>. <span class=\"citation\">Midr. Till. to Ps. XXIV</span> <span dir=\"rtl\">יש רש ואין שמו לפי רָשׁוּתוֹ</span> (ed. Bub. <span dir=\"rtl\">עניותו</span>) many a man is poor, but his reputation is not in harmony with his poverty (it being that he is wealthy). <span class=\"citation\">Yalk. Gen. 147</span> (ref. to <span class=\"citation\">Koh. IV, 14</span>) <span dir=\"rtl\">במלכותו … נולדה רָשׁוּתוֹ וכ׳</span> with Joseph’s elevation to governorship Potiphar’s poverty was born; <span class=\"citation\">Gen. R. s. 89</span> <span dir=\"rtl\">רִשְׁתּוֹ</span>; <span class=\"citation\">Yalk. Koh. 971</span> <span dir=\"rtl\">רשתו</span>.</div>","alt":[]},"27585":{"h":"רָשׁוּת II","r":"T01080","html":"<div class=\"sense\">, f. (<a href=\"#\" data-headword=\"רָשָׁה\">רָשָׁה</a>) </div><div class=\"sense\"><b>1)</b> <i>power, authority, control</i>. <span class=\"citation\">Ned. X, 2</span>, v. <a href=\"#\" data-headword=\"רוֹקֵן\">רוֹקֵן</a>. <span class=\"citation\">Gen. R. s. 67</span> <span dir=\"rtl\">ששה … ברְשׁוּתוֹ שלשה אינן ברשותו</span> six things (organs) serve man, three of which are under his control, and three are not; <span dir=\"rtl\">העין … ורשותו וכ׳</span> the eye, the ear, and the nose are not under his control &amp;c. <span class=\"citation\">Bets. V, 2</span> <span dir=\"rtl\">משום ר׳</span> as an exercise of authority (judging, betrothal &amp;c.; differ. interpret. in comment.); a. fr.—Esp. <i>secular government</i>, (mostly) <i>the Roman government in Palestine, Roman officials, Roman party</i>. <span class=\"citation\">Ab. I, 10</span>, v. <a href=\"#\" data-headword=\"יָדַע\">יָדַע</a>. <span class=\"citation\">Ib. II, 3</span>, v. <a href=\"#\" data-headword=\"זָהִיר\">זָהִיר</a>. <span class=\"citation\">Sabb. 11ᵃ</span>, v. <a href=\"#\" data-headword=\"חָלָל III\"><span dir=\"rtl\">חָלָל</span> III</a>. <span class=\"citation\">Ab. Zar. 17ᵃ</span> (ref. to <span class=\"citation\">Prov. XXX, 15</span>) <span dir=\"rtl\">קול שתי בנות … ומאי נינהי מינות והר׳</span> Ms. M. the voice of two daughters that cry from Gehenna, and say in this world, ‘bring, bring’; and who are they? Heresy and Government. <span class=\"citation\">Makhsh. II, 5</span> <span dir=\"rtl\">אם יש בה ר׳</span> if it is the residence of Roman officials (for whom the baths are always kept in readiness). <span class=\"citation\">Yoma 86ᵇ</span> <span dir=\"rtl\">והר׳ מקברת וכ׳</span> and high office buries its occupant (causes premature death). <span class=\"citation\">Erub. 41ᵇ</span> <span dir=\"rtl\">שלשה אין רואין … חולי מעיין והר׳</span> three persons shall not see Gehenna (expiate their sins in this world): those who suffer from extreme poverty, from bowel diseases, and from governmental exactions (Rashi: from <i>creditors</i>). <span class=\"citation\">Y. Snh. VI, 23ᵈ</span> sq. <span dir=\"rtl\">ר׳ של מטן</span> the earthly government; <span dir=\"rtl\">ר׳ של מעלן</span> the divine government; a. fr.—Pl. <span dir=\"rtl\">רְשׁוּיוֹת</span>. <span class=\"citation\">Ḥag. 15ᵃ</span> <span dir=\"rtl\">שמא … שתי ר׳ הן</span> are there, God forbid! two powers (governing the universe)? <span class=\"citation\">Gen. R. s. 1</span> (ref. to <a href=\"#\" data-headword=\"בָּרָא I\">ברא</a>, <span class=\"citation\">Gen. I, 1</span>) <span dir=\"rtl\">אין כל … שתי ר׳ וכ׳</span> none can say, two powers created the world (the verb <a href=\"#\" data-headword=\"בָּרָא I\">ברא</a> being in the singular) &amp;c. <span class=\"citation\">Ber. 33ᵇ</span> <span dir=\"rtl\">דמיחזי כשתי ר׳</span> (saying <a href=\"#\" data-headword=\"מוֹדִים\">מודים</a> twice) has the appearance of a belief in a duality; a. e.</div><div class=\"sense\"><b>—2)</b>  (trad. pronunc. <a href=\"#\" data-headword=\"רָשׁוּת I\">רְשׁוּת</a>) <i>dominion, domain, territory</i>. <span class=\"citation\">B. Kam. I, 2</span> <span dir=\"rtl\">ר׳ המיוחדת למזיק</span> a territory exclusively belonging to the owner of the animal that did the damage; <span dir=\"rtl\">ר׳ הניזק והמזיק</span> a space belonging to both owners. Ib. 13ᵇ (in Chald. dict.) <span dir=\"rtl\">תורך ברְשׁוּתִי מאי בעי</span> what had thy ox to do in my ground. Ib. 81ᵃ; <span class=\"citation\">Taan. 6ᵇ</span> <span dir=\"rtl\">שבילי הר׳</span> the paths (short cuts) through private property. <span class=\"citation\">B. Mets. 5ᵇ</span> <span dir=\"rtl\">משביעין אותו שבועה שאינו ברשותו</span> we make him swear that it is not in his possession; a. v. fr.—<span dir=\"rtl\">ר׳ היחיד</span> (abbrev. <span dir=\"rtl\">רהי֞</span>) <i>private ground</i>; <span dir=\"rtl\">ר׳ הרבים</span> (abbrev. <span dir=\"rtl\">רהר֞</span>, <span dir=\"rtl\">רה֞</span>) <i>public road</i>. <span class=\"citation\">Sabb. 6ᵃ</span>; a. v. fr.—<span class=\"citation\">Ib. 9ᵃ</span> <span dir=\"rtl\">הרי זו ר׳ לעצמה</span> this forms a territory for itself (with regard to Sabbath movements). Ib. VII, 2 <span dir=\"rtl\">המוציא מר׳ לר׳</span> he who carries things (on the Sabbath) from one territory to another; a. fr.—<i>Pl.</i> as ab. Ib. 6ᵃ <span dir=\"rtl\">ארבע ר׳ לשבת וכ׳</span> there are four classes of territories with regard to Sabbath laws &amp;c.; Tosef. ib. I, 1. Ib. 6; Sabb. l. c. <span dir=\"rtl\">אסקופה … שתי ר׳</span> the threshold stands for two territories; when the door is open, it is classified with the interior &amp;c. Ib. 9ᵃ <span dir=\"rtl\">כל … מוצא שתי ר׳ וכ׳</span> wherever you find two territories belonging to the same class; a. fr.—<span class=\"citation\">Y. Kidd. III, 64ᶜ</span> top; <span class=\"citation\">Y. Ned. VIII, 40ᵈ</span> bot. (ref. to R. Jose’s opinions <span class=\"citation\">Kidd. III, 9</span>, a. <span class=\"citation\">Ned. VIII, 2</span>) <span dir=\"rtl\">תמן הוא אמר עד שיצאו כל הרשויות הגדולות עד שיצאו כל הר׳ הקטנות וכ׳</span> there, he says, the terms, ‘the oldest’, ‘the youngest’, tend to exclude all the older daughters, and all the younger daughters respectively (so that only the oldest of the daughters of his first wife, and respectively the youngest of the daughters of his second wife are meant), and here he says so (that the widest scope is adopted)?</div><div class=\"sense\"><b>—3)</b> <i>permission, option; optional act</i>. <span class=\"citation\">Ber. 28ᵃ</span> <span dir=\"rtl\">וניתנה להם ר׳ וכ׳</span> and permission to enter was given to the students. <span class=\"citation\">Ab. III, 15</span>, v. <a href=\"#\" data-headword=\"צָפָה\">צָפָה</a>. <span class=\"citation\">Ḥull. 141ᵃ</span> <span dir=\"rtl\">לדבר הר׳</span>, v. <a href=\"#\" data-headword=\"מִצְוָה\">מִצְוָה</a>. <span class=\"citation\">Ib. 106ᵃ</span>, v. <a href=\"#\" data-headword=\"מִצְוָה\">מִצְוָה</a>. <span class=\"citation\">Ber. 27ᵇ</span>, v. <a href=\"#\" data-headword=\"חוֹבָה\">חוֹבָה</a>. <span class=\"citation\">M. Kat. III, 3</span> <span dir=\"rtl\">אגרות של ר׳</span>, v. <a href=\"#\" data-headword=\"שְׁאִילָה\">שְׁאִילָה</a>; a. fr.—נטילת ר׳ <i>taking leave of absence, parting</i>, at which a religious remark was customary. <span class=\"citation\">Lev. R. s. 17</span> <span dir=\"rtl\">עביד להו נ׳ ר</span> made these verses the text for leave-taking (cmp. <a href=\"#\" data-headword=\"אַפְטַרְתָּא\">אַפְטַרְתָּא</a>). Y. Ber. II, 5ᶜ bot. <span dir=\"rtl\">ההיא מילתא … הוה נ׳ ר׳ דידיה</span> that remark … was his leave-taking.—[</div><div class=\"sense\"><b>4)</b>  (cmp. <a href=\"#\" data-headword=\"רַשַּׁאי\">רַשַּׁאי</a> 2) <i>debt, loan, creditor’s claim</i>. <span class=\"citation\">Erub. 41ᵇ</span>, v. supra.]</div>","alt":[]},"27586":{"h":"רְשׁוּתָא","r":"T01081","html":"<div class=\"sense\"><b>1)</b> <i>power, control, authority</i>. <span class=\"citation\">Targ. Y. Lev. XXVI, 6</span>. Targ. II <span class=\"citation\">Deut. XXI, 14</span>. <span class=\"citation\">Targ. Ex. XXI, 8</span>; a. e.—Y. Gitt. IV, 50ᶜ bot. <span dir=\"rtl\">יהב רשו וכ׳</span> authorized the scribe to write &amp;c.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>permission, license</i>;<i> leave</i>. <span class=\"citation\">Targ. Esth. VIII, 16</span>. <span class=\"citation\">Targ. Y. Deut. XXII, 15</span>. <span class=\"citation\">Ib. XV, 2</span>; a. fr.—<span class=\"citation\">Cant. R. to VII, 9</span> <span dir=\"rtl\">לית את יהיב לי ר׳ וכ׳</span> would you not give me permission to go up and kiss that image on its mouth? Y. Ber. II, 5ᶜ bot. <span dir=\"rtl\">מה הוה מיזל ליה דלא מיסב ר׳</span> why did he go away without taking leave? <span class=\"citation\">Snh. 5ᵃ</span> נקיטנא ר׳ I hold a license to teach. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לשקול ר׳ מבי וכ׳</span> let him take out (a teacher and judge’s) license from the office of the Resh Galutha. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאי ר׳</span> how was the license worded?; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>domain, territory</i>. <span class=\"citation\">Targ. Y. Ex. XVI, 29</span>.</div><div class=\"sense\"><b>—4)</b> <i>debt, loan, claim;</i> מרי ר׳ <i>creditor;</i> also <i>debtor</i>. <span class=\"citation\">Targ. Jer. XV, 10</span> <span dir=\"rtl\">לא רשן בי רשו</span> some ed. <span class=\"citation\">Targ. O. Deut. XV, 2</span>; a. e.—<span class=\"citation\">Gitt. 86ᵃ</span> ורשו אינש לית עלוהי Ar. (ed. <span dir=\"rtl\">רשום</span>, v. Tosaf. a. l.) and no man’s loan rests on him (he is not hypothecated). <span class=\"citation\">Snh. 29ᵇ</span>, v. <a href=\"#\" data-headword=\"קַב\">קַב</a>. <span class=\"citation\">Y. Peah VIII, end, 21ᵇ</span> <span dir=\"rtl\">ר׳ גבן</span> the alms we receive are a loan with us (for which we are responsible); <span class=\"citation\">Y. Shek. V, 49ᵇ</span> top <a href=\"#\" data-headword=\"דשתן\">דשתן</a> (corr. acc.). <span class=\"citation\">B. Bath. 92ᵇ</span> <span dir=\"rtl\">מרי רְשׁוּתָיךְ</span> the debtor, v. <a href=\"#\" data-headword=\"פָּארֵי I\">פָּארֵי</a>; a. e.—Pl. <a href=\"#\" data-headword=\"רֵישְׁוָותָא\">רַשְׁוָותָא</a>. <span class=\"citation\">B. Kam. 46ᵇ</span> <span dir=\"rtl\">מרי רַשְׁוָותָךְ</span>.</div>","alt":["רְשׁוּ","רָ׳"]},"27587":{"h":"רשי","r":"T01082","html":"<div class=\"sense\"><i>to have power</i>.—V. <a href=\"#\" data-headword=\"רַשַּׁאי\">רַשַּׁאי</a>.</div><div class=\"sense\"><b>Hif. הִרְשָׁה</b> <div class=\"sense\"><i>to authorize, permit</i>. Y. Keth. X, 33ᵈ bot. <span dir=\"rtl\">במַרְשׁוֹת זו את זו בשהִרְשֵׁת וכ׳</span> when they gave each other power of attorney, when the third wife authorized the second to go to law with the first. <span class=\"citation\">Ḥag. 14ᵇ</span> <span dir=\"rtl\">רבי תַּרְשֵׁינִי לומר וכ׳</span> my teacher, wilt thou permit me to say something &amp;c.?; Y. ib. II, 77ᵃ bot.; a. e.</div></div><div class=\"sense\"><b>Hof. הוּרְשָׁה</b> <div class=\"sense\"><i>to be authorized, permitted</i>. <span class=\"citation\">Ḥag. 13ᵃ</span> (fr. Ben Sira) <span dir=\"rtl\">במה שהוּרְשֵׁיתָ התבונן וכ׳</span> speculate on that which has been given under thy control, and have nothing to do with secret things; Y. ib. II, 77ᶜ top; <span class=\"citation\">Gen. R. s. 8</span>. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">מהיכן ה׳</span> from where did he take leave (to go away). Ib. s. 39 <span dir=\"rtl\">עדיין לא ה׳</span> he had not yet had the permission to go away; a. e.</div></div>","alt":["רָשָׁה"]},"27588":{"h":"רְשֵׁי","r":"T01083","html":"<div class=\"sense\"><b>1)</b> <i>to have power, be permitted, dare</i>. <span class=\"citation\">Targ. Ps. CVI, 2</span>.</div><div class=\"sense\"><b>—2)</b>  with <a href=\"#\" data-headword=\"ב\">ב</a>, <i>to claim power over, to claim a debt; to lend</i>. <span class=\"citation\">Targ. O. Deut. XV, 2</span> <span dir=\"rtl\">דיִרְשֵׁי</span> ed. Berl. (ed. Vien. <span dir=\"rtl\">דיַרְ׳</span> <i>Af.</i>). Ib. XXIV, 10 <span dir=\"rtl\">תִּירְשֵׁי</span> ed. Berl. (ed. Vien. <a href=\"#\" data-headword=\"תּוּרְנָא\">תַּרְ׳</a>); a. e.—Part. <a href=\"#\" data-headword=\"רְשֵׁי\">רָשֵׁי</a>; pl. <a href=\"#\" data-headword=\"רשן\">רָשָׁן</a>, <span dir=\"rtl\">רָשָׁאן</span>. Ib. 11. <span class=\"citation\">Targ. Jer. XV, 10</span>; a. e.—<span class=\"citation\">Ned. 51ᵃ</span> <span dir=\"rtl\">חיטי דרָשֵׁינָא בך</span> the wheat which thou owest me. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חיטי דרשינא קא נסיבנא</span> that wheat on which I have a claim I take (I have no claim).</div><div class=\"sense\"><b>Af. אַרְשֵׁי</b> <div class=\"sense\"><b>1)</b> <i>to empower, permit</i>. Part. pass. <span dir=\"rtl\">מַרְשֵׁי</span>; pl. <span dir=\"rtl\">מַרְשַׁן</span>. <span class=\"citation\">Targ. Y. Ex. XIX, 13</span> (O. ed. Berl. <span dir=\"rtl\">מְרַשָּׁן</span> <i>Pa.</i>; oth. ed. <span dir=\"rtl\">מְרָשָׁן</span>). <span class=\"citation\">Targ. Y. Deut. XVI, 8</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to give leave, to dismiss</i>. <span class=\"citation\">Targ. II Chr. XXIII, 8</span>. <span class=\"citation\">Ib. XXV, 10</span>.</div><div class=\"sense\"><b>—3)</b>  with <a href=\"#\" data-headword=\"ב\">ב</a>, <i>to claim</i>. <span class=\"citation\">Targ. O. Deut. XV, 2</span>, a. e., v. supra. <span class=\"citation\">Targ. I Kings VIII, 31</span> <span dir=\"rtl\">ויַרְשֵׁי ביה מומי</span> ed. Ven. I (oth. ed. <span dir=\"rtl\">ויִרְשֵׁי</span> <i>Pe.</i>) and shall claim an oath (ask that he make oath; h. text <a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>!).</div></div><div class=\"sense\"><b>Pa. רַשֵּׁי</b> <div class=\"sense\"><i>to permit</i>. Part. pass. pl. <span dir=\"rtl\">מְרַשָּׁן</span>, <span dir=\"rtl\">מְרָשָׁן</span>, v. supra.</div></div>","alt":["רְשָׁא"]},"27589":{"h":"רַשְׁיָא","r":"T01084","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְשֵׁי\">preced.</a>) <i>money-lender, pressing creditor</i>. <span class=\"citation\">Targ. Ex. XXII, 24</span>. <span class=\"citation\">Targ. II Kings IV, 1</span>.</div>","alt":["רָ׳"]},"27590":{"h":"רָשַׁיָּא","r":"T01085","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵישׁ II\"><span dir=\"rtl\">רֵישׁ</span> II</a></div>","alt":["רַשַּׁ׳"]},"27591":{"h":"רשין","r":"T01086","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רשן\">רשן</a></div>","alt":[]},"27592":{"h":"רַשִּׁיעָא","r":"T01087","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רָשָׁע\">רָשָׁע</a>. <span class=\"citation\">Targ. Ps. XXXVII, 10</span>. <span class=\"citation\">Targ. Prov. XI, 6</span>; a. fr.—<span class=\"citation\">Macc. 14ᵃ</span> <span dir=\"rtl\">ר׳ בר ר׳</span> a wicked man (committing incest), son of a wicked man. <span class=\"citation\">Koh. R. to I, 8</span> <span dir=\"rtl\">ההוא ר׳</span> that wicked (heretic). <span class=\"citation\">Snh. 52ᵃ</span>; a. fr.—[<span class=\"citation\">Targ. Ps. XXXVI, 5</span>; <span class=\"citation\">Targ. Prov. VIII, 7</span> some ed., v. <a href=\"#\" data-headword=\"רִשְׁעָא\">רִשְׁעָא</a>.]—Pl. <span dir=\"rtl\">רַשִּׁיעִין</span>, <span dir=\"rtl\">רַשִּׁיעַיָּא</span>, <span dir=\"rtl\">רַשִּׁיעֵי</span>, <a href=\"#\" data-headword=\"רַשִּׁיעָא\">רָשִׁ׳</a>. <span class=\"citation\">Targ. Ps. I, 1</span>. <span class=\"citation\">Targ. Prov. XI, 10</span>; a. fr.—<span class=\"citation\">Pes. 68ᵃ</span> (quot. <span class=\"citation\">Targ. Is. V, 17</span>) <span dir=\"rtl\">מדמתרגם רב יוסף ונכסיהון דר׳ וכ׳</span> as Rab Joseph translates it, ‘the righteous shall inherit the estates of the wicked’. <span class=\"citation\">Bets. 25ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲצוּבָא II\"><span dir=\"rtl\">חֲצוּבָא</span> II</a>. <span class=\"citation\">B. Mets. 83ᵇ</span> a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"רַשִּׁיעָא\">רַשִּׁיעָא</a>, <span dir=\"rtl\">רַשִּׁיעֲתָא</span>. <span class=\"citation\">Targ. Lam. IV, 21</span> ed. Lag. (changed by censors in oth. eds.). <span class=\"citation\">Targ. Y. Gen. XXVII, 46</span> (ed. Vien. <a href=\"#\" data-headword=\"רַשִּׁיעָא\">רְשִׁ׳</a>).</div>","alt":["רַשִּׁיעָה","רָשִׁ׳"]},"27593":{"h":"רְשִׁישִׁים","r":"T01088","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְשָׁשִׁין\">רְשָׁשִׁין</a></div>","alt":[]},"27594":{"h":"רָשַׁל","r":"T01089","html":"<div class=\"sense\"><i>to be lax, hang down, flap</i>.</div><div class=\"sense\"><b>Pi. רִשֵּׁל</b> <div class=\"sense\"><i>to weaken, break the force of</i>. <span class=\"citation\">Gen. R. s. 24</span>; <span class=\"citation\">Lev. R. s. 15</span>; <span class=\"citation\">Yalk. Kings 219</span> the Lord <span dir=\"rtl\">מְרַשְּׁלוֹ בהרים</span> breaks it (the force of the wind) through the mountains (v. <a href=\"#\" data-headword=\"חָשַׁל\">חָשַׁל</a>). <span class=\"citation\">Num. R. s. 9</span>, beg. <span dir=\"rtl\">הנואף … מְרַשֵּׁל וכ׳</span> the adulterer, if one may say so, weakens the power of Deity; a. e.—<i>Part. pass.</i> <span dir=\"rtl\">מְרוּשָּׁל</span>; pl. <span dir=\"rtl\">מְרוּשָּׁלִין</span> <i>hanging down, trailing</i>. <span class=\"citation\">Tosef. Men. I, 8</span> <span dir=\"rtl\">היו מר׳ ומסולקין וכ׳</span> if the priest’s garments are trailing and tucked up (by the girdle), or threadbare &amp;c.; <span class=\"citation\">Zeb. 18ᵃ</span> <span dir=\"rtl\">היו מר׳ מסולקין וכ׳</span> if they are too long, or too short, or &amp;c. <span class=\"citation\">Ib. 18ᵇ</span> <span dir=\"rtl\">מר׳ כשרין מסולקין וכ׳</span> if they are too long, they are fit for service, if too short, they are unfit; a. e.</div></div><div class=\"sense\"><b>Hithpa. הִתְרַשֵּׁל</b> </div><div class=\"sense\"><b>Nithpa. נִתְרַשֵּׁל</b> <div class=\"sense\"><i>to be relaxed, weakened</i>. Num. R. l. c. <span dir=\"rtl\">כיון ששמע … נִתְרַשְּׁלוּ ידיו</span> when the artist heard (that the king whose picture he was going to paint was dead), his hands sank down (he was undecided). <span class=\"citation\">Koh. R. to VII, 1</span> <span dir=\"rtl\">נתגעשו ונתרשלו וכ׳</span> the Israelites were too excited (busy with their own affairs) and too indifferent to attend to Joshua’s burial, v. <a href=\"#\" data-headword=\"גָּעַשׁ\">גָּעַשׁ</a>. Tanḥ. Sh’laḥ 2 <span dir=\"rtl\">אף … נתרשלו ידם</span> even Moses and Aaron felt themselves powerless; <span class=\"citation\">Num. R. s. 16</span><sup>2</sup> <span dir=\"rtl\">נתר׳ את ידם</span>. Tanḥ. l. c. <span dir=\"rtl\">אתם … אלא נִתְרַשַּׁלְתֶּם</span> you do not find your hands (you are helpless) and give it up in despair; (Num. l. c. <span dir=\"rtl\">כשלתם</span>); a. fr.</div></div>","alt":[]},"27595":{"h":"רְשֵׁל","r":"T01090","html":"<div class=\"sense\">, <i>to flap, be lax, weak</i>. <span class=\"citation\">Targ. Is. XXXV, 3</span> <span dir=\"rtl\">דרָשְׁלָן</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">דמְרַשְּׁלָן</span>, some ed. <span dir=\"rtl\">דרשליין</span>, corr. acc.; h. text <span dir=\"rtl\">רפות</span>).</div><div class=\"sense\"><b>Pa. רַשֵּׁל</b> <div class=\"sense\"><i>to loosen, weaken</i>. <span class=\"citation\">Targ. Josh. X, 6</span> (h. text <span dir=\"rtl\">תרף</span>). <span class=\"citation\">Targ. Jer. XXXVIII, 4</span>.—Part. pass. <span dir=\"rtl\">מְרַשַּׁל</span>; f. <span dir=\"rtl\">מְרַשְּׁלָא</span>; pl. <span dir=\"rtl\">מְרַשְּׁלִין</span>; <span dir=\"rtl\">מְרַשְּׁלָן</span>. <span class=\"citation\">Targ. II Sam. XVII, 2</span>. Targ. Is. l. c., v. supra.</div></div><div class=\"sense\"><b>Ithpa. אִתְרַשֵּׁל</b> <div class=\"sense\"><i>to be lax, weakened</i>. <span class=\"citation\">Targ. II Sam. IV, 1</span>. <span class=\"citation\">Targ. II Chr. XXIX, 11</span> (h. text <span dir=\"rtl\">תִּשָּׁלוּ</span>); a. fr.—<span class=\"citation\">B. Bath. 21ᵇ</span> bot <span dir=\"rtl\">אתי לאִתְרַשּׁוּלֵי</span> the teacher may become discouraged (by competition).</div></div>","alt":[]},"27596":{"h":"רָשַׁם","r":"T01091","html":"<div class=\"sense\"> (late b. h.)<i>to mark, draw</i>. <span class=\"citation\">Y. Gitt. II, 44ᵇ</span> <span dir=\"rtl\">רוֹשֵׁם לפניהן בדיו וכ׳</span> one may draw (the signatures of illiterate witnesses) for them with ink, and they write them over with red paint (contrad. to <span dir=\"rtl\">קרע</span>). Ib.; <span class=\"citation\">Y. Sabb. XII, 13ᵈ</span> <span dir=\"rtl\">הרושם … כתבנית וכ׳</span> if one draws on a skin figures like writing. <span class=\"citation\">Sabb. XII, 4</span> <span dir=\"rtl\">ובכל דבר שהוא רוֹשֵׁם</span> and with any material which marks; <span class=\"citation\">Gitt. II, 3</span> (<span class=\"citation\">19ᵃ</span>), v. <a href=\"#\" data-headword=\"קַיָּימָא\">קַיָּימָא</a>. <span class=\"citation\">Ḥull. X, 3</span> <span dir=\"rtl\">צריך שיִרְשׁוֹם</span> he must mark the animal. Tanḥ. Tsav 5 <span dir=\"rtl\">האדם … רושם עליו מיתה וכ׳</span> when a man sins, the Lord makes the mark of death upon him; if he repents, the writ is cancelled. <span class=\"citation\">Sabb. 55ᵃ</span> (ref. to <span class=\"citation\">Ez. IX, 4</span>) <span dir=\"rtl\">לך ורְשׁוֹם על וכ׳</span> go and mark the foreheads of the righteous with a sign of ink …, and the foreheads of the wicked with blood; a. fr.—Part. pass. <a href=\"#\" data-headword=\"רָשׁוּם\">רָשׁוּם</a>; f. <span dir=\"rtl\">רְשׁוּמָה</span>; pl. <span dir=\"rtl\">רְשׁוּמִים</span>, <span dir=\"rtl\">רְשׁוּמִין</span>; <span dir=\"rtl\">רְשׁוּמוֹת</span>. Y. Succ. IV, 54ᶜ top <span dir=\"rtl\">עד שלא … היתה ר׳ ברקיע וכ׳</span> so long as the Israelites were not redeemed from Egypt, it (the sapphire brick) was placed as a mark in heaven &amp;c.; <span class=\"citation\">Lev. R. s. 23</span>; <span class=\"citation\">Cant. R. to IV, 8</span>. <span class=\"citation\">Gen. R. s. 81</span> (ref. to <span class=\"citation\">Dan. X, 21</span>) <span dir=\"rtl\">אם ר׳ למה אמת … למה ר׳</span> if marked (for future action), why real writing (decree), and if real writing why marked? (Answ.) <span dir=\"rtl\">ר׳ עד שלא נגזרה וכ׳</span> marked, before the divine decree was signed; <span class=\"citation\">Cant. R. to I, 9</span>; a. e.—Esp. <span dir=\"rtl\">דורשי רשומות</span> <i>those who interpret the Law metaphorically</i>. <span class=\"citation\">B. Kam. 82ᵃ</span>; <span class=\"citation\">Snh. 104ᵇ</span>; <span class=\"citation\">Ber. 24ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">חמורות</span>, v. Rashi a. l.).</div><div class=\"sense\"><b>Pi. רִשֵּׁם</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רְשֵׁל\">same</a>.—Part. pass. <span dir=\"rtl\">מְרוּשָּׁם</span>. <span class=\"citation\">Num. R. s. 9</span><sup>5</sup> <span dir=\"rtl\">וילדה בן מ׳ למה וכ׳</span> and she gave birth to a young that was marked; why? Because its mother was burnt (cauterized).</div></div><div class=\"sense\"><b>Nif. נִרְשָׁם</b> <div class=\"sense\"><i>to be marked, engraven</i>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 41</span> <span dir=\"rtl\">המכות היו נִרְשָׁמוֹת בגופן</span> the plagues were engraven on their bodies (by ref. to Ps. l. c. 43).</div></div>","alt":[]},"27597":{"h":"רְשַׁם I","r":"T01092","html":"<div class=\"sense\">, <i>to mark; to record</i>. <span class=\"citation\">Targ. Y. Gen. IV, 15</span>. <span class=\"citation\">Targ. Ez. IX, 4</span>. <span class=\"citation\">Targ. Is. X, 1</span> (h. text <span dir=\"rtl\">חקק</span>).</div><div class=\"sense\"><b>Pa. רַשֵּׁם</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רָשַׁם\">same</a>.<span class=\"citation\">Targ. Jud. V, 14</span> (h. text <span dir=\"rtl\">מחקק׳</span>).</div><div class=\"sense\"><b>—2)</b> <i>to make incisions</i>. <span class=\"citation\">Targ. Y. Lev. XXI, 5</span> (h. text <a href=\"#\" data-headword=\"קרח\">קרח</a>).</div></div><div class=\"sense\"><b>*. אִתְרְשֵׁים</b> <div class=\"sense\"><i>to be wrinkled</i>. <span class=\"citation\">Targ. Ez. XXVII, 35</span> (h. text <span dir=\"rtl\">רעמו</span>; prob. to be read: <a href=\"#\" data-headword=\"רְעַם I\">אִתְרְעִימוּ</a>, v. <a href=\"#\" data-headword=\"רְעַם I\"><span dir=\"rtl\">רְעַם</span> I</a>.).</div></div>","alt":[]},"27598":{"h":"רְשַׁם II","r":"T01093","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְשַׁם I\">preced.</a>) <i>incision, wound</i>. <span class=\"citation\">Targ. Y. Ex. XXI, 25</span> Ar. (Ms. Ar. <span dir=\"rtl\">רושם</span>; ed. <a href=\"#\" data-headword=\"*הַלְכְּשִׁישׁ\">הלכשיש</a>; h. text <a href=\"#\" data-headword=\"חַבּוּרָה\">חַבּוּרָה</a>). <span class=\"citation\">Targ. Y. Lev. XIX, 28</span>, v. <a href=\"#\" data-headword=\"רוֹשַׁם\">רוּשְׁמָא</a>.</div>","alt":[]},"27599":{"h":"רשֶׁם","r":"T01094","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹשֶׁם\">רוֹשֶׁם</a></div>","alt":[]}};
